use crate::lang::Language;
use std::rc::Rc;

pub type NodeId = usize;

#[derive(Debug, Clone)]
pub struct NodeData {
    pub kind: &'static str,
    pub is_named: bool,
    pub is_error: bool,
    pub is_missing: bool,
    pub field: Option<&'static str>,
    pub start: usize,
    pub end: usize,
    pub parent: Option<NodeId>,
    pub children: Vec<NodeId>,
}

#[derive(Debug)]
pub struct Tree {
    pub source: Rc<str>,
    pub nodes: Vec<NodeData>,
    pub root: NodeId,
    pub lang: Language,
    line_starts: Vec<usize>,
}

impl Tree {
    pub fn new(source: Rc<str>, lang: Language, nodes: Vec<NodeData>, root: NodeId) -> Tree {
        let mut line_starts = vec![0];
        for (i, b) in source.bytes().enumerate() {
            if b == b'\n' {
                line_starts.push(i + 1);
            }
        }
        Tree { source, nodes, root, lang, line_starts }
    }

    pub fn root(&self) -> Node<'_> {
        Node { tree: self, id: self.root }
    }

    pub fn node(&self, id: NodeId) -> Node<'_> {
        Node { tree: self, id }
    }

    /// 0-based line of a byte offset
    pub fn line_of(&self, offset: usize) -> usize {
        match self.line_starts.binary_search(&offset) {
            Ok(i) => i,
            Err(i) => i - 1,
        }
    }

    pub fn line_start(&self, line: usize) -> usize {
        self.line_starts.get(line).copied().unwrap_or(self.source.len())
    }

    pub fn line_count(&self) -> usize {
        self.line_starts.len()
    }

    /// (line, column in chars) of byte offset
    pub fn position(&self, offset: usize) -> (usize, usize) {
        let line = self.line_of(offset);
        let ls = self.line_start(line);
        let col = self.source[ls..offset].chars().count();
        (line, col)
    }

    /// byte column
    pub fn byte_column(&self, offset: usize) -> usize {
        let line = self.line_of(offset);
        offset - self.line_start(line)
    }
}

#[derive(Clone, Copy)]
pub struct Node<'t> {
    pub tree: &'t Tree,
    pub id: NodeId,
}

impl<'t> PartialEq for Node<'t> {
    fn eq(&self, other: &Self) -> bool {
        self.id == other.id && std::ptr::eq(self.tree, other.tree)
    }
}
impl<'t> Eq for Node<'t> {}

impl<'t> std::fmt::Debug for Node<'t> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Node({} {:?} {}..{})", self.kind(), self.text(), self.start(), self.end())
    }
}

impl<'t> Node<'t> {
    #[inline]
    pub fn data(&self) -> &'t NodeData {
