/// Helper to build trees.
pub struct TreeBuilder {
    pub nodes: Vec<NodeData>,
}

impl TreeBuilder {
    pub fn new() -> Self {
        TreeBuilder { nodes: Vec::new() }
    }
    pub fn leaf(&mut self, kind: &'static str, named: bool, start: usize, end: usize) -> NodeId {
        self.nodes.push(NodeData {
            kind,
            is_named: named,
            is_error: false,
            is_missing: false,
            field: None,
            start,
            end,
            parent: None,
            children: vec![],
        });
        self.nodes.len() - 1
    }
    pub fn token(&mut self, kind: &'static str, start: usize, end: usize) -> NodeId {
        self.leaf(kind, false, start, end)
    }
    pub fn missing(&mut self, kind: &'static str, pos: usize) -> NodeId {
        let id = self.leaf(kind, false, pos, pos);
        self.nodes[id].is_missing = true;
        id
    }
    /// Create an internal node from children; range derived from children.
    pub fn node(&mut self, kind: &'static str, children: Vec<NodeId>) -> NodeId {
        let start = children.iter().map(|&c| self.nodes[c].start).min().unwrap_or(0);
        let end = children.iter().map(|&c| self.nodes[c].end).max().unwrap_or(start);
        self.node_with_range(kind, children, start, end)
    }
    pub fn node_with_range(&mut self, kind: &'static str, children: Vec<NodeId>, start: usize, end: usize) -> NodeId {
        let id = self.nodes.len();
        self.nodes.push(NodeData {
            kind,
            is_named: true,
            is_error: kind == "ERROR",
            is_missing: false,
            field: None,
            start,
            end,
            parent: None,
            children: children.clone(),
        });
        for c in children {
            self.nodes[c].parent = Some(id);
        }
        id
    }
    pub fn set_field(&mut self, id: NodeId, field: &'static str) -> NodeId {
        self.nodes[id].field = Some(field);
        id
    }
    pub fn set_kind(&mut self, id: NodeId, kind: &'static str) {
        self.nodes[id].kind = kind;
        self.nodes[id].is_error = kind == "ERROR";
    }
    pub fn set_named(&mut self, id: NodeId, named: bool) {
        self.nodes[id].is_named = named;
    }
    pub fn start(&self, id: NodeId) -> usize {
        self.nodes[id].start
    }
    pub fn end(&self, id: NodeId) -> usize {
        self.nodes[id].end
    }
    pub fn kind(&self, id: NodeId) -> &'static str {
        self.nodes[id].kind
    }
    pub fn add_child(&mut self, parent: NodeId, child: NodeId) {
        self.nodes[parent].children.push(child);
        self.nodes[child].parent = Some(parent);
        let (cs, ce) = (self.nodes[child].start, self.nodes[child].end);
        if cs < self.nodes[parent].start {
            self.nodes[parent].start = cs;
        }
        if ce > self.nodes[parent].end {
            self.nodes[parent].end = ce;
        }
    }
    /// Reorder children by start offset (stable) — used to insert comments/extras.
    pub fn sort_children(&mut self, id: NodeId) {
        let mut ch = std::mem::take(&mut self.nodes[id].children);
        let nodes = &self.nodes;
        ch.sort_by_key(|&c| (nodes[c].start, nodes[c].end));
        self.nodes[id].children = ch;
    }
    pub fn finish(self, source: Rc<str>, lang: Language, root: NodeId) -> Tree {
        Tree::new(source, lang, self.nodes, root)
    }
}

/// Insert extra nodes (comments) into the tree at appropriate positions:
/// each extra becomes a child of the deepest node whose range contains it
/// and which has children surrounding it.
pub fn insert_extras(b: &mut TreeBuilder, root: NodeId, extras: Vec<NodeId>) {
    for ex in extras {
        let (s, e) = (b.nodes[ex].start, b.nodes[ex].end);
        // find deepest node containing [s,e) whose children don't strictly contain it
        let mut cur = root;
        loop {
            let mut descended = false;
            let children = b.nodes[cur].children.clone();
            for c in children {
                let (cs, ce) = (b.nodes[c].start, b.nodes[c].end);
                if cs <= s && e <= ce && !b.nodes[c].children.is_empty() && (cs < s || e < ce) {
                    cur = c;
                    descended = true;
                    break;
                }
            }
            if !descended {
                break;
            }
        }
        b.add_child(cur, ex);
        b.sort_children(cur);
    }
}
