    line_starts: Vec<usize>,
}

impl Tree {
    pub fn new(source: Rc<str>, lang: Language, nodes: Vec<NodeData>, root: NodeId) -> Tree {
        let mut line_starts = vec![0];
        for (i, b) in source.bytes().enumerate() {
            if b == b'\n' {
                line_starts.push(i + 1);
            }
        }
