pub fn is_ident_char(c: char) -> bool {
    c == '_' || c == '$' || c.is_alphanumeric()
}

/// Skip a string literal starting at `pos` (which points at the quote). Returns end position (after closing quote or at line end / EOF).
pub fn skip_string(src: &str, pos: usize, quote: u8, allow_newline: bool) -> usize {
    let bytes = src.as_bytes();
    let mut i = pos + 1;
    while i < bytes.len() {
        let b = bytes[i];
        if b == b'\\' {
            i += 2;
            continue;
        }
        if b == quote {
            return i + 1;
        }
        if b == b'\n' && !allow_newline {
            return i;
        }
        i += 1;
    }
    bytes.len()
}

/// Returns the length in bytes of the char at `pos`.
pub fn char_at(src: &str, pos: usize) -> Option<char> {
    src[pos..].chars().next()
}

pub fn skip_ws(src: &str, mut pos: usize) -> usize {
    let bytes = src.as_bytes();
    while pos < bytes.len() {
        let b = bytes[pos];
        if b == b' ' || b == b'\t' || b == b'\r' || b == b'\n' || b == 0x0b || b == 0x0c {
            pos += 1;
        } else if bytes[pos..].starts_with("\u{feff}".as_bytes()) || bytes[pos..].starts_with("\u{a0}".as_bytes()) {
            pos += if bytes[pos] == 0xef { 3 } else { 2 };
        } else {
            break;
        }
    }
    pos
}

pub fn scan_number(src: &str, pos: usize) -> usize {
    let bytes = src.as_bytes();
    let mut i = pos;
    let n = bytes.len();
    if i + 1 < n && bytes[i] == b'0' && matches!(bytes[i + 1], b'x' | b'X' | b'o' | b'O' | b'b' | b'B') {
        i += 2;
        while i < n && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'_') {
            i += 1;
        }
        return i;
    }
    while i < n && (bytes[i].is_ascii_digit() || bytes[i] == b'_') {
        i += 1;
    }
    if i < n && bytes[i] == b'.' {
        i += 1;
        while i < n && (bytes[i].is_ascii_digit() || bytes[i] == b'_') {
            i += 1;
        }
    }
    if i < n && (bytes[i] == b'e' || bytes[i] == b'E') {
        let mut j = i + 1;
        if j < n && (bytes[j] == b'+' || bytes[j] == b'-') {
            j += 1;
        }
        if j < n && bytes[j].is_ascii_digit() {
            while j < n && bytes[j].is_ascii_digit() {
                j += 1;
            }
            i = j;
        }
    }
    // suffixes (n for bigint, or letters for other languages like f, L, u)
    while i < n && bytes[i].is_ascii_alphabetic() {
        i += 1;
    }
    i
}

pub fn ident_end(src: &str, pos: usize) -> usize {
    let mut end = pos;
    for (i, c) in src[pos..].char_indices() {
        if i == 0 {
            if !is_ident_start(c) {
                return pos;
            }
        } else if !is_ident_char(c) {
            break;
        }
        end = pos + i + c.len_utf8();
    }
    end
}
