//! Hand-written JavaScript / TypeScript / TSX parser producing
//! tree-sitter-like concrete syntax trees.
use super::lexer::*;
use crate::lang::Language;
use crate::tree::{insert_extras, NodeId, Tree, TreeBuilder};
use std::rc::Rc;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Dialect {
    Js,
    Ts,
    Tsx,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum TK {
    Ident,
    Number,
    Str,
    Punct,
    Template,
    Private,
    Eof,
}

#[derive(Clone, Copy, Debug)]
struct Tok {
    kind: TK,
    start: usize,
    end: usize,
    nl_before: bool,
}

const PUNCTS: &[&str] = &[
    ">>>=", "...", "===", "!==", "**=", "<<=", ">>=", ">>>", "&&=", "||=", "??=", "=>", "==", "!=", "<=", ">=", "&&",
    "||", "??", "?.", "++", "--", "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", "<<", ">>", "**", "</", "/>",
    "${", "{", "}", "(", ")", "[", "]", ";", ",", "<", ">", "+", "-", "*", "/", "%", "&", "|", "^", "!", "~", "?",
    ":", "=", ".", "@", "#",
];

const KEYWORDS: &[&str] = &[
    "var", "let", "const", "function", "class", "if", "else", "for", "while", "do", "try", "catch", "finally",
    "switch", "case", "default", "return", "break", "continue", "throw", "import", "export", "from", "as", "new",
    "delete", "typeof", "void", "instanceof", "in", "of", "this", "super", "true", "false", "null", "undefined",
    "async", "await", "yield", "static", "get", "set", "extends", "implements", "interface", "type", "enum",
    "declare", "namespace", "module", "abstract", "readonly", "public", "private", "protected", "override",
    "debugger", "with", "keyof", "infer", "is", "asserts", "satisfies", "unique", "accessor", "any", "number",
    "boolean", "string", "symbol", "object", "never", "unknown", "bigint", "require", "global",
];

pub fn static_str(s: &str) -> &'static str {
    for p in PUNCTS.iter().chain(KEYWORDS.iter()) {
        if *p == s {
            return p;
        }
    }
    Box::leak(s.to_string().into_boxed_str())
}

struct Parser<'s> {
    src: &'s str,
    pos: usize,
    b: TreeBuilder,
    dialect: Dialect,
    extras: Vec<NodeId>,
    peeked: Option<(Tok, Vec<(usize, usize)>)>,
    in_pattern: bool,
    depth: usize,
}

type P = NodeId;

impl<'s> Parser<'s> {
    fn ts(&self) -> bool {
        self.dialect != Dialect::Js
    }

    // ---------------- lexing ----------------
    fn skip_trivia(&self, mut pos: usize, comments: &mut Vec<(usize, usize)>) -> (usize, bool) {
        let bytes = self.src.as_bytes();
        let mut nl = false;
        loop {
            let p = skip_ws(self.src, pos);
            if self.src[pos..p].contains('\n') {
                nl = true;
            }
            pos = p;
            if pos + 1 < bytes.len() && bytes[pos] == b'/' && bytes[pos + 1] == b'/' {
                let end = self.src[pos..].find('\n').map(|i| pos + i).unwrap_or(bytes.len());
                comments.push((pos, end));
                pos = end;
                continue;
            }
            if pos + 1 < bytes.len() && bytes[pos] == b'/' && bytes[pos + 1] == b'*' {
                let end = self.src[pos + 2..].find("*/").map(|i| pos + i + 4).unwrap_or(bytes.len());
                if self.src[pos..end].contains('\n') {
                    nl = true;
                }
                comments.push((pos, end));
                pos = end;
                continue;
            }
            break;
        }
        (pos, nl)
    }

    fn lex_at(&self, start: usize, nl: bool) -> Tok {
        let bytes = self.src.as_bytes();
        if start >= bytes.len() {
            return Tok { kind: TK::Eof, start, end: start, nl_before: nl };
        }
        let c = char_at(self.src, start).unwrap();
        if is_ident_start(c) || c == '\\' {
            let mut end = ident_end(self.src, start);
            if end == start {
                end = start + c.len_utf8();
            }
            return Tok { kind: TK::Ident, start, end, nl_before: nl };
        }
        if c.is_ascii_digit() || (c == '.' && start + 1 < bytes.len() && bytes[start + 1].is_ascii_digit()) {
            let end = scan_number(self.src, start);
            return Tok { kind: TK::Number, start, end, nl_before: nl };
        }
        if c == '"' || c == '\'' {
            let end = skip_string(self.src, start, c as u8, false);
            return Tok { kind: TK::Str, start, end, nl_before: nl };
        }
        if c == '`' {
            return Tok { kind: TK::Template, start, end: start + 1, nl_before: nl };
        }
        if c == '#' && start + 1 < bytes.len() && is_ident_start(char_at(self.src, start + 1).unwrap()) {
            let end = ident_end(self.src, start + 1);
            return Tok { kind: TK::Private, start, end, nl_before: nl };
        }
        for p in PUNCTS {
            if self.src[start..].starts_with(p) {
                return Tok { kind: TK::Punct, start, end: start + p.len(), nl_before: nl };
            }
        }
        Tok { kind: TK::Punct, start, end: start + c.len_utf8(), nl_before: nl }
    }

    fn peek(&mut self) -> Tok {
        if let Some((t, _)) = &self.peeked {
            return *t;
        }
        let mut comments = Vec::new();
        let (p, nl) = self.skip_trivia(self.pos, &mut comments);
        let t = self.lex_at(p, nl);
        self.peeked = Some((t, comments));
        t
    }

    fn peek2(&mut self) -> Tok {
        let t = self.peek();
        let mut c = Vec::new();
        let (p, nl) = self.skip_trivia(t.end, &mut c);
        self.lex_at(p, nl)
    }

    fn peek_text(&mut self) -> &'s str {
        let t = self.peek();
        &self.src[t.start..t.end]
    }

    fn peek2_text(&mut self) -> &'s str {
        let t = self.peek2();
        &self.src[t.start..t.end]
    }

    fn commit_comments(&mut self) {
        if let Some((_, comments)) = self.peeked.take() {
            for (s, e) in comments {
                let id = self.b.leaf("comment", true, s, e);
                self.extras.push(id);
            }
        }
    }

    fn advance(&mut self) -> Tok {
        let t = self.peek();
        self.commit_comments();
        self.pos = t.end;
        t
    }

    fn eof(&mut self) -> bool {
        self.peek().kind == TK::Eof
    }

    fn at(&mut self, s: &str) -> bool {
        let t = self.peek();
        t.kind != TK::Eof && t.kind != TK::Str && t.kind != TK::Template && &self.src[t.start..t.end] == s
    }

    fn at_ident(&mut self) -> bool {
        self.peek().kind == TK::Ident
    }

    fn at_kw(&mut self, s: &str) -> bool {
        let t = self.peek();
        t.kind == TK::Ident && &self.src[t.start..t.end] == s
    }

    /// Consume token and create an anonymous token node with the given kind.
    fn tok(&mut self, kind: &'static str) -> P {
        let t = self.advance();
        self.b.token(kind, t.start, t.end)
    }

    fn eat(&mut self, s: &'static str) -> Option<P> {
        if self.at(s) {
            Some(self.tok(s))
        } else {
            None
        }
    }

    fn expect(&mut self, s: &'static str) -> P {
        if self.at(s) {
            self.tok(s)
        } else {
            let t = self.peek();
            self.b.missing(s, t.start.min(self.pos.max(0)))
        }
    }

    fn eat_into(&mut self, s: &'static str, ch: &mut Vec<P>) -> bool {
        if let Some(n) = self.eat(s) {
            ch.push(n);
            true
        } else {
            false
        }
    }

    fn expect_into(&mut self, s: &'static str, ch: &mut Vec<P>) {
        let n = self.expect(s);
        ch.push(n);
    }

    fn named_leaf(&mut self, kind: &'static str) -> P {
        let t = self.advance();
        self.b.leaf(kind, true, t.start, t.end)
    }

    fn field(&mut self, id: P, f: &'static str) -> P {
        self.b.set_field(id, f)
    }

    fn node(&mut self, kind: &'static str, ch: Vec<P>) -> P {
        self.b.node(kind, ch)
    }

    fn error_tok(&mut self) -> P {
        let t = self.advance();
        let leaf = if t.kind == TK::Ident {
            self.b.leaf("identifier", true, t.start, t.end)
        } else if t.kind == TK::Number {
            self.b.leaf("number", true, t.start, t.end)
        } else {
            let k = static_str(&self.src[t.start..t.end]);
            self.b.token(k, t.start, t.end)
        };
        leaf
    }

    /// Statement terminator: consumes `;` if present. Returns token node if consumed.
    fn semi(&mut self, ch: &mut Vec<P>) {
        if self.at(";") {
            let n = self.tok(";");
            ch.push(n);
        }
    }

    // ---------------- program ----------------
    fn parse_program(&mut self) -> P {
        let mut ch = Vec::new();
        if self.src.starts_with("#!") {
            let end = self.src.find('\n').unwrap_or(self.src.len());
            let n = self.b.leaf("hash_bang_line", true, 0, end);
            ch.push(n);
            self.pos = end;
        }
        while !self.eof() {
            let before = self.pos;
            let s = self.parse_statement();
            ch.push(s);
            if self.pos == before && !self.eof() {
                let e = self.error_tok();
                let err = self.node("ERROR", vec![e]);
                ch.push(err);
            }
        }
        let start = ch.iter().map(|&c| self.b.start(c)).min().unwrap_or_else(|| {
            let mut c = Vec::new();
            self.skip_trivia(0, &mut c).0.min(self.src.len())
        });
        let start = if ch.is_empty() { 0.min(self.src.len()) } else { start };
        self.b.node_with_range("program", ch, start, self.src.len())
    }

    // ---------------- statements ----------------
    fn parse_statement(&mut self) -> P {
        self.depth += 1;
        let r = self.parse_statement_inner();
        self.depth -= 1;
        r
    }

    fn parse_statement_inner(&mut self) -> P {
        let t = self.peek();
        if t.kind == TK::Punct {
            match self.peek_text() {
                "{" => return self.parse_block(),
                ";" => {
                    let n = self.tok(";");
                    return self.node("empty_statement", vec![n]);
                }
                "@" => return self.parse_class_declaration(vec![]),
                _ => {}
            }
        }
        if t.kind == TK::Ident {
            let text = self.peek_text();
            match text {
                "var" | "let" | "const" => {
                    if text != "let" || self.let_is_declaration() {
                        let mut ch = Vec::new();
                        let d = self.parse_variable_declaration(true);
                        ch.push(d);
                        return d;
                    }
                }
                "function" => return self.parse_function_declaration(vec![]),
                "async" => {
                    if self.peek2_text() == "function" && !self.peek2().nl_before {
                        return self.parse_function_declaration(vec![]);
                    }
                }
                "class" => return self.parse_class_declaration(vec![]),
                "if" => return self.parse_if(),
                "for" => return self.parse_for(),
                "while" => return self.parse_while(),
                "do" => return self.parse_do(),
                "try" => return self.parse_try(),
                "switch" => return self.parse_switch(),
                "return" => return self.parse_simple_stmt("return_statement", "return", true),
                "throw" => return self.parse_simple_stmt("throw_statement", "throw", true),
                "break" => return self.parse_jump("break_statement", "break"),
                "continue" => return self.parse_jump("continue_statement", "continue"),
                "debugger" => {
                    let k = self.tok("debugger");
                    let mut ch = vec![k];
                    self.semi(&mut ch);
                    return self.node("debugger_statement", ch);
                }
                "import" => {
                    let n2 = self.peek2_text();
                    if n2 != "(" && n2 != "." {
                        return self.parse_import();
                    }
                }
                "export" => return self.parse_export(),
                "with" => {
                    let k = self.tok("with");
                    let obj = self.parse_parenthesized();
                    let obj = self.field(obj, "object");
                    let body = self.parse_statement();
                    let body = self.field(body, "body");
                    return self.node("with_statement", vec![k, obj, body]);
                }
                _ => {}
            }
            if self.ts() {
                match text {
                    "type" if self.peek2().kind == TK::Ident && !self.peek2().nl_before => {
                        return self.parse_type_alias();
                    }
                    "interface" if self.peek2().kind == TK::Ident => return self.parse_interface(),
                    "enum" if self.peek2().kind == TK::Ident => return self.parse_enum(vec![]),
                    "declare" if self.peek2().kind == TK::Ident && !self.peek2().nl_before => {
                        return self.parse_ambient();
                    }
                    "abstract" if self.peek2_text() == "class" => return self.parse_class_declaration(vec![]),
                    "namespace" | "module" if self.peek2().kind == TK::Ident || self.peek2().kind == TK::Str => {
                        let m = self.parse_module();
                        let mut ch = vec![m];
                        self.semi(&mut ch);
                        return self.node("expression_statement", ch);
                    }
                    "global" if self.peek2_text() == "{" => {
                        let m = self.parse_module();
                        return self.node("expression_statement", vec![m]);
                    }
                    _ => {}
                }
            }
            // labeled statement
            if self.peek2_text() == ":" && !KEYWORD_NOT_LABEL.contains(&text) {
                let label = self.named_leaf("statement_identifier");
                let label = self.field(label, "label");
                let colon = self.tok(":");
                let body = self.parse_statement();
                let body = self.field(body, "body");
                return self.node("labeled_statement", vec![label, colon, body]);
            }
        }
        self.parse_expression_statement()
    }

    fn let_is_declaration(&mut self) -> bool {
        let t2 = self.peek2();
        t2.kind == TK::Ident || (t2.kind == TK::Punct && (self.peek2_text() == "[" || self.peek2_text() == "{"))
    }

    fn parse_expression_statement(&mut self) -> P {
        let start_pos = self.pos;
        let e = self.parse_expression();
        let mut ch = vec![e];
        if self.pos == start_pos {
            // no progress; wrap as error
            let bad = self.error_tok();
            return self.node("ERROR", vec![bad]);
        }
        self.semi(&mut ch);
        self.node("expression_statement", ch)
    }

    fn parse_block(&mut self) -> P {
        let mut ch = vec![self.tok("{")];
        while !self.eof() && !self.at("}") {
            let before = self.pos;
            let s = self.parse_statement();
            ch.push(s);
            if self.pos == before {
                let e = self.error_tok();
                let err = self.node("ERROR", vec![e]);
                ch.push(err);
            }
        }
        self.expect_into("}", &mut ch);
        self.node("statement_block", ch)
    }

    fn parse_simple_stmt(&mut self, kind: &'static str, kw: &'static str, allow_expr: bool) -> P {
        let k = self.tok(kw);
        let mut ch = vec![k];
        if allow_expr {
            let t = self.peek();
            if t.kind != TK::Eof && !(t.nl_before && kind == "return_statement") && !self.at(";") && !self.at("}") {
                let e = self.parse_expression();
                ch.push(e);
            }
        }
        self.semi(&mut ch);
        self.node(kind, ch)
    }

    fn parse_jump(&mut self, kind: &'static str, kw: &'static str) -> P {
        let k = self.tok(kw);
        let mut ch = vec![k];
        let t = self.peek();
        if t.kind == TK::Ident && !t.nl_before {
            let l = self.named_leaf("statement_identifier");
            let l = self.field(l, "label");
            ch.push(l);
        }
        self.semi(&mut ch);
        self.node(kind, ch)
    }

    fn parse_parenthesized(&mut self) -> P {
        let mut ch = vec![self.expect("(")];
        let e = self.parse_expression();
        ch.push(e);
        self.expect_into(")", &mut ch);
        self.node("parenthesized_expression", ch)
    }

    fn parse_if(&mut self) -> P {
        let k = self.tok("if");
        let cond = self.parse_parenthesized();
        let cond = self.field(cond, "condition");
        let cons = self.parse_statement();
        let cons = self.field(cons, "consequence");
        let mut ch = vec![k, cond, cons];
        if self.at_kw("else") {
            let e = self.tok("else");
            let alt = self.parse_statement();
            let clause = self.node("else_clause", vec![e, alt]);
            let clause = self.field(clause, "alternative");
            ch.push(clause);
        }
        self.node("if_statement", ch)
    }

    fn parse_while(&mut self) -> P {
        let k = self.tok("while");
        let cond = self.parse_parenthesized();
        let cond = self.field(cond, "condition");
        let body = self.parse_statement();
        let body = self.field(body, "body");
        self.node("while_statement", vec![k, cond, body])
    }

    fn parse_do(&mut self) -> P {
        let k = self.tok("do");
        let body = self.parse_statement();
        let body = self.field(body, "body");
        let mut ch = vec![k, body];
        self.expect_into("while", &mut ch);
        let cond = self.parse_parenthesized();
        let cond = self.field(cond, "condition");
        ch.push(cond);
        self.semi(&mut ch);
        self.node("do_statement", ch)
    }

    fn parse_for(&mut self) -> P {
        let k = self.tok("for");
        let mut ch = vec![k];
        if self.at_kw("await") {
            let a = self.tok("await");
            ch.push(a);
        }
        self.expect_into("(", &mut ch);
        // detect for-in / for-of
        let save = self.save();
        let mut is_for_in = false;
        {
            let mut kind_tok = None;
            if self.at_kw("var") || self.at_kw("let") || self.at_kw("const") {
                let t = self.peek_text();
                let k = static_str(t);
                kind_tok = Some(self.tok(k));
            }
            let left = self.parse_binding_target();
            if (self.at_kw("in") || self.at_kw("of")) && self.b.start(left) < self.b.end(left) {
                is_for_in = true;
                if let Some(kt) = kind_tok {
                    let kt = self.field(kt, "kind");
                    ch.push(kt);
                }
                let left = self.field(left, "left");
                ch.push(left);
                let op = if self.at_kw("in") { self.tok("in") } else { self.tok("of") };
                let op = self.field(op, "operator");
                ch.push(op);
                let right = self.parse_expression();
                let right = self.field(right, "right");
                ch.push(right);
            }
        }
        if !is_for_in {
            self.restore(save);
            // initializer
            if self.at(";") {
                let s = self.tok(";");
                let e = self.node("empty_statement", vec![s]);
                let e = self.field(e, "initializer");
                ch.push(e);
            } else if self.at_kw("var") || self.at_kw("let") || self.at_kw("const") {
                let d = self.parse_variable_declaration(true);
                let d = self.field(d, "initializer");
                ch.push(d);
            } else {
                let e = self.parse_expression();
                let mut ech = vec![e];
                self.semi(&mut ech);
                let es = self.node("expression_statement", ech);
                let es = self.field(es, "initializer");
                ch.push(es);
            }
            // condition
            if self.at(";") {
                let s = self.tok(";");
                let s = self.field(s, "condition");
                ch.push(s);
            } else {
                let e = self.parse_expression();
                let e = self.field(e, "condition");
                ch.push(e);
                if self.at(";") {
                    let s = self.tok(";");
                    let s = self.field(s, "condition");
                    ch.push(s);
                }
            }
            if !self.at(")") {
                let e = self.parse_expression();
                let e = self.field(e, "increment");
                ch.push(e);
            }
        }
        self.expect_into(")", &mut ch);
        let body = self.parse_statement();
        let body = self.field(body, "body");
        ch.push(body);
        self.node(if is_for_in { "for_in_statement" } else { "for_statement" }, ch)
    }

    fn parse_try(&mut self) -> P {
        let k = self.tok("try");
        let body = self.parse_block();
        let body = self.field(body, "body");
        let mut ch = vec![k, body];
        if self.at_kw("catch") {
            let c = self.tok("catch");
            let mut cch = vec![c];
            if self.at("(") {
                self.eat_into("(", &mut cch);
                let p = self.parse_binding_target();
                let p = self.field(p, "parameter");
                cch.push(p);
                if self.ts() && self.at(":") {
                    let ta = self.parse_type_annotation();
                    let ta = self.field(ta, "type");
                    cch.push(ta);
                }
                self.expect_into(")", &mut cch);
            }
            let b = self.parse_block();
            let b = self.field(b, "body");
            cch.push(b);
            let clause = self.node("catch_clause", cch);
            let clause = self.field(clause, "handler");
            ch.push(clause);
        }
        if self.at_kw("finally") {
            let f = self.tok("finally");
            let b = self.parse_block();
            let b = self.field(b, "body");
            let clause = self.node("finally_clause", vec![f, b]);
            let clause = self.field(clause, "finalizer");
            ch.push(clause);
        }
        self.node("try_statement", ch)
    }

    fn parse_switch(&mut self) -> P {
        let k = self.tok("switch");
        let v = self.parse_parenthesized();
        let v = self.field(v, "value");
        let mut bch = vec![self.expect("{")];
        while !self.eof() && !self.at("}") {
            if self.at_kw("case") {
                let c = self.tok("case");
                let val = self.parse_expression();
                let val = self.field(val, "value");
                let mut cch = vec![c, val];
                self.expect_into(":", &mut cch);
                while !self.eof() && !self.at("}") && !self.at_kw("case") && !self.at_kw("default") {
                    let s = self.parse_statement();
                    let s = self.field(s, "body");
                    cch.push(s);
                }
                let n = self.node("switch_case", cch);
                bch.push(n);
            } else if self.at_kw("default") {
                let c = self.tok("default");
                let mut cch = vec![c];
                self.expect_into(":", &mut cch);
                while !self.eof() && !self.at("}") && !self.at_kw("case") && !self.at_kw("default") {
                    let s = self.parse_statement();
                    let s = self.field(s, "body");
                    cch.push(s);
                }
                let n = self.node("switch_default", cch);
                bch.push(n);
            } else {
                let e = self.error_tok();
                let err = self.node("ERROR", vec![e]);
                bch.push(err);
            }
        }
        self.expect_into("}", &mut bch);
        let body = self.node("switch_body", bch);
        let body = self.field(body, "body");
        self.node("switch_statement", vec![k, v, body])
    }

    fn parse_variable_declaration(&mut self, with_semi: bool) -> P {
        let kw = self.peek_text();
        let kind = static_str(kw);
        let is_var = kw == "var";
        let k = self.tok(kind);
        let k = if is_var { k } else { self.field(k, "kind") };
        let mut ch = vec![k];
        loop {
            let d = self.parse_variable_declarator();
            ch.push(d);
            if !self.eat_into(",", &mut ch) {
                break;
            }
        }
        if with_semi {
            self.semi(&mut ch);
        }
        self.node(if is_var { "variable_declaration" } else { "lexical_declaration" }, ch)
    }

    fn parse_variable_declarator(&mut self) -> P {
        let name = self.parse_binding_target();
        let name = self.field(name, "name");
        let mut ch = vec![name];
        if self.ts() && self.at("!") {
            let b = self.tok("!");
            ch.push(b);
        }
        if self.ts() && self.at(":") {
            let ta = self.parse_type_annotation();
            let ta = self.field(ta, "type");
            ch.push(ta);
        }
        if self.at("=") {
            let eq = self.tok("=");
            ch.push(eq);
            let v = self.parse_assignment_expr();
            let v = self.field(v, "value");
            ch.push(v);
        }
        self.node("variable_declarator", ch)
    }

    /// identifier | object_pattern | array_pattern
    fn parse_binding_target(&mut self) -> P {
        if self.at("{") {
            return self.parse_object_pattern();
        }
        if self.at("[") {
            return self.parse_array_pattern();
        }
        if self.at_ident() {
            return self.named_leaf("identifier");
        }
        let t = self.peek();
        self.b.missing("identifier", t.start)
    }

    fn parse_object_pattern(&mut self) -> P {
        let mut ch = vec![self.tok("{")];
        while !self.eof() && !self.at("}") {
            if self.at("...") {
                let d = self.tok("...");
                let t = self.parse_binding_target();
                let r = self.node("rest_pattern", vec![d, t]);
                ch.push(r);
            } else if self.at("[") {
                let k = self.parse_computed_property_name();
                let k = self.field(k, "key");
                let c = self.expect(":");
                let v = self.parse_pattern_with_default();
                let v = self.field(v, "value");
                let p = self.node("pair_pattern", vec![k, c, v]);
                ch.push(p);
            } else if self.at_ident() || self.peek().kind == TK::Str || self.peek().kind == TK::Number {
                if self.peek2_text() == ":" {
                    let k = self.parse_property_name();
                    let k = self.field(k, "key");
                    let c = self.tok(":");
                    let v = self.parse_pattern_with_default();
                    let v = self.field(v, "value");
                    let p = self.node("pair_pattern", vec![k, c, v]);
                    ch.push(p);
                } else {
                    let id = self.named_leaf("shorthand_property_identifier_pattern");
                    if self.at("=") {
                        let id = self.field(id, "left");
                        let eq = self.tok("=");
                        let v = self.parse_assignment_expr();
                        let v = self.field(v, "right");
                        let p = self.node("object_assignment_pattern", vec![id, eq, v]);
                        ch.push(p);
                    } else {
                        ch.push(id);
                    }
                }
            } else {
                let e = self.error_tok();
                let err = self.node("ERROR", vec![e]);
                ch.push(err);
            }
            if !self.eat_into(",", &mut ch) {
                break;
            }
        }
        self.expect_into("}", &mut ch);
        self.node("object_pattern", ch)
    }

    fn parse_pattern_with_default(&mut self) -> P {
        let t = self.parse_binding_target();
        if self.at("=") {
            let t = self.field(t, "left");
            let eq = self.tok("=");
            let v = self.parse_assignment_expr();
            let v = self.field(v, "right");
            return self.node("assignment_pattern", vec![t, eq, v]);
        }
        t
    }

    fn parse_array_pattern(&mut self) -> P {
        let mut ch = vec![self.tok("[")];
        while !self.eof() && !self.at("]") {
            if self.at(",") {
                let c = self.tok(",");
                ch.push(c);
                continue;
            }
            if self.at("...") {
                let d = self.tok("...");
                let t = self.parse_binding_target();
                let r = self.node("rest_pattern", vec![d, t]);
                ch.push(r);
            } else {
                let p = self.parse_pattern_with_default();
                ch.push(p);
            }
            if !self.eat_into(",", &mut ch) {
                break;
            }
        }
        self.expect_into("]", &mut ch);
        self.node("array_pattern", ch)
    }

    fn parse_function_declaration(&mut self, mut ch: Vec<P>) -> P {
        if self.at_kw("async") {
            let a = self.tok("async");
            ch.push(a);
        }
        let f = self.tok("function");
        ch.push(f);
        let gen = self.eat_into("*", &mut ch);
        if self.at_ident() {
            let n = self.named_leaf("identifier");
            let n = self.field(n, "name");
            ch.push(n);
        }
        self.parse_function_rest(&mut ch);
        if !self.at("{") && self.ts() {
            // function signature (overload)
            self.semi(&mut ch);
            return self.node("function_signature", ch);
        }
        let body = self.parse_block();
        let body = self.field(body, "body");
        ch.push(body);
        self.node(if gen { "generator_function_declaration" } else { "function_declaration" }, ch)
    }

    fn parse_function_rest(&mut self, ch: &mut Vec<P>) {
        if self.ts() && self.at("<") {
            let tp = self.parse_type_parameters();
            let tp = self.field(tp, "type_parameters");
            ch.push(tp);
        }
        let params = self.parse_formal_parameters();
        let params = self.field(params, "parameters");
        ch.push(params);
        if self.ts() && self.at(":") {
            let rt = self.parse_type_annotation_or_predicate();
            let rt = self.field(rt, "return_type");
            ch.push(rt);
        }
    }

    fn parse_formal_parameters(&mut self) -> P {
        let mut ch = vec![self.expect("(")];
        while !self.eof() && !self.at(")") {
            let before = self.pos;
            let p = self.parse_parameter();
            ch.push(p);
            if !self.eat_into(",", &mut ch) {
                if self.pos == before {
                    let e = self.error_tok();
                    let err = self.node("ERROR", vec![e]);
                    ch.push(err);
                } else {
                    break;
                }
            }
        }
        self.expect_into(")", &mut ch);
        self.node("formal_parameters", ch)
    }

    fn parse_parameter(&mut self) -> P {
        let mut mods = Vec::new();
        if self.ts() {
            while self.at("@") {
                let d = self.parse_decorator();
                mods.push(d);
            }
            while matches!(self.peek_text(), "public" | "private" | "protected")
                && self.peek2().kind == TK::Ident
            {
                let m = self.named_leaf_kw("accessibility_modifier");
                mods.push(m);
            }
            while matches!(self.peek_text(), "readonly" | "override") && self.peek2().kind == TK::Ident {
                let m = self.named_leaf_kw("override_modifier");
                mods.push(m);
            }
        }
        if self.at("...") {
            let d = self.tok("...");
            let t = self.parse_binding_target();
            let mut rch = vec![d, t];
            if self.ts() && self.at(":") {
                let ta = self.parse_type_annotation();
                let ta = self.field(ta, "type");
                rch.push(ta);
            }
            return self.node("rest_pattern", rch);
        }
        let target = self.parse_binding_target();
        if !self.ts() {
            if self.at("=") {
                let target = self.field(target, "left");
                let eq = self.tok("=");
                let v = self.parse_assignment_expr();
                let v = self.field(v, "right");
                return self.node("assignment_pattern", vec![target, eq, v]);
            }
            return target;
        }
        let target = self.field(target, "pattern");
        let mut ch = mods;
        ch.push(target);
        let optional = self.eat_into("?", &mut ch);
        if self.at(":") {
            let ta = self.parse_type_annotation();
            let ta = self.field(ta, "type");
            ch.push(ta);
        }
        if self.at("=") {
            let eq = self.tok("=");
            ch.push(eq);
            let v = self.parse_assignment_expr();
            let v = self.field(v, "value");
            ch.push(v);
        }
        self.node(if optional { "optional_parameter" } else { "required_parameter" }, ch)
    }

    fn named_leaf_kw(&mut self, kind: &'static str) -> P {
        let t = self.advance();
        let k = static_str(&self.src[t.start..t.end]);
        let inner = self.b.token(k, t.start, t.end);
        self.node(kind, vec![inner])
    }

    fn parse_decorator(&mut self) -> P {
        let at = self.tok("@");
        let e = self.parse_lhs_expression(false);
        let d = self.node("decorator", vec![at, e]);
        self.field(d, "decorator")
    }

    fn parse_class_declaration(&mut self, mut ch: Vec<P>) -> P {
        while self.at("@") {
            let d = self.parse_decorator();
            ch.push(d);
        }
        let abs = if self.at_kw("abstract") {
            let a = self.tok("abstract");
            ch.push(a);
            true
        } else {
            false
        };
        let c = self.expect("class");
        ch.push(c);
        if self.at_ident() && !self.at_kw("extends") && !self.at_kw("implements") {
            let n = self.named_leaf(if self.ts() { "type_identifier" } else { "identifier" });
            let n = self.field(n, "name");
            ch.push(n);
        }
        self.parse_class_tail(&mut ch);
        self.node(if abs { "abstract_class_declaration" } else { "class_declaration" }, ch)
    }

    fn parse_class_tail(&mut self, ch: &mut Vec<P>) {
        if self.ts() && self.at("<") {
            let tp = self.parse_type_parameters();
            let tp = self.field(tp, "type_parameters");
            ch.push(tp);
        }
        if self.at_kw("extends") || self.at_kw("implements") {
            let mut hch = Vec::new();
            if self.at_kw("extends") {
                let e = self.tok("extends");
                hch.push(e);
                let v = self.parse_lhs_expression(false);
                hch.push(v);
                if self.ts() && self.at("<") {
                    let ta = self.parse_type_arguments();
                    hch.push(ta);
                }
            }
            if self.ts() && self.at_kw("implements") {
                let i = self.tok("implements");
                let mut ich = vec![i];
                loop {
                    let t = self.parse_type();
                    ich.push(t);
                    if !self.eat_into(",", &mut ich) {
                        break;
                    }
                }
                let ic = self.node("implements_clause", ich);
                hch.push(ic);
            }
            let h = self.node("class_heritage", hch);
            ch.push(h);
        }
        let body = self.parse_class_body();
        let body = self.field(body, "body");
        ch.push(body);
    }

    fn parse_class_body(&mut self) -> P {
        let mut ch = vec![self.expect("{")];
        while !self.eof() && !self.at("}") {
            if self.at(";") {
                let s = self.tok(";");
                ch.push(s);
                continue;
            }
            let before = self.pos;
            let m = self.parse_class_member();
            ch.push(m);
            if self.pos == before {
                let e = self.error_tok();
                let err = self.node("ERROR", vec![e]);
                ch.push(err);
            }
        }
        self.expect_into("}", &mut ch);
        self.node("class_body", ch)
    }

    fn is_member_name_start(&mut self) -> bool {
        let t = self.peek();
        matches!(t.kind, TK::Ident | TK::Str | TK::Number | TK::Private) || self.at("[")
    }

    fn parse_class_member(&mut self) -> P {
        let mut ch = Vec::new();
        while self.at("@") {
            let d = self.parse_decorator();
            ch.push(d);
        }
        // static block
        if self.at_kw("static") && self.peek2_text() == "{" {
            let s = self.tok("static");
            let b = self.parse_block();
            let b = self.field(b, "body");
            let n = self.node("class_static_block", vec![s, b]);
            return self.field(n, "member");
        }
        // modifiers
        let mut is_ts_field = false;
        loop {
            let text = self.peek_text();
            let t2 = self.peek2();
            let next_is_name = t2.kind == TK::Ident
                || t2.kind == TK::Str
                || t2.kind == TK::Number
                || t2.kind == TK::Private
                || (t2.kind == TK::Punct && matches!(&self.src[t2.start..t2.end], "[" | "*" | "{"));
            if !next_is_name {
                break;
            }
            match text {
                "static" => {
                    let s = self.tok("static");
                    ch.push(s);
                }
                "public" | "private" | "protected" if self.ts() => {
                    let m = self.named_leaf_kw("accessibility_modifier");
                    ch.push(m);
                    is_ts_field = true;
                }
                "abstract" | "override" | "readonly" | "declare" | "accessor" if self.ts() => {
                    let k = static_str(text);
                    let m = self.tok(k);
                    ch.push(m);
                    is_ts_field = true;
                }
                _ => break,
            }
        }
        let mut kind_prefix: Option<&'static str> = None;
        if self.at_kw("async") && self.peek2().kind != TK::Punct || (self.at_kw("async") && self.peek2_text() == "[") || (self.at_kw("async") && self.peek2_text() == "*") {
            let a = self.tok("async");
            ch.push(a);
        }
        if (self.at_kw("get") || self.at_kw("set")) && {
            let t2 = self.peek2();
            t2.kind != TK::Punct || matches!(&self.src[t2.start..t2.end], "[")
        } {
            let k = if self.at_kw("get") { "get" } else { "set" };
            let g = self.tok(k);
            ch.push(g);
            kind_prefix = Some(k);
        }
        let _ = kind_prefix;
        if self.at("*") {
            let s = self.tok("*");
            ch.push(s);
        }
        if !self.is_member_name_start() {
            if ch.is_empty() {
                let e = self.error_tok();
                return self.node("ERROR", vec![e]);
            }
            return self.node("ERROR", ch);
        }
        let name = self.parse_property_name();
        let name_is_private = self.b.kind(name) == "private_property_identifier";
        let _ = name_is_private;
        // method?
        if self.at("(") || self.at("<") {
            let name = self.field(name, "name");
            ch.push(name);
            if self.ts() && self.at("?") {
                let q = self.tok("?");
                ch.push(q);
            }
            self.parse_function_rest(&mut ch);
            if self.at("{") {
                let body = self.parse_block();
                let body = self.field(body, "body");
                ch.push(body);
                let n = self.node("method_definition", ch);
                return self.field(n, "member");
            }
            self.semi(&mut ch);
            let is_abstract = ch.iter().any(|&c| self.b.kind(c) == "abstract");
            let n = self.node(if is_abstract { "abstract_method_signature" } else { "method_signature" }, ch);
            return self.field(n, "member");
        }
        // field
        let ts_field = self.ts();
        let name = self.field(name, if ts_field { "name" } else { "property" });
        ch.push(name);
        if self.ts() && (self.at("?") || self.at("!")) {
            let t = if self.at("?") { self.tok("?") } else { self.tok("!") };
            ch.push(t);
        }
        if self.ts() && self.at(":") {
            let ta = self.parse_type_annotation();
            let ta = self.field(ta, "type");
            ch.push(ta);
        }
        if self.at("=") {
            let eq = self.tok("=");
            ch.push(eq);
            let v = self.parse_assignment_expr();
            let v = self.field(v, "value");
            ch.push(v);
        }
        self.semi(&mut ch);
        let _ = is_ts_field;
        let n = self.node(if ts_field { "public_field_definition" } else { "field_definition" }, ch);
        self.field(n, "member")
    }

    /// property_identifier | string | number | computed_property_name | private_property_identifier
    fn parse_property_name(&mut self) -> P {
        let t = self.peek();
        match t.kind {
            TK::Str => self.parse_string(),
            TK::Number => self.named_leaf("number"),
            TK::Private => self.named_leaf("private_property_identifier"),
            TK::Punct if self.at("[") => self.parse_computed_property_name(),
            _ => self.named_leaf("property_identifier"),
        }
    }

    fn parse_computed_property_name(&mut self) -> P {
        let l = self.tok("[");
        let e = self.parse_expression();
        let r = self.expect("]");
        self.node("computed_property_name", vec![l, e, r])
    }

    fn parse_import(&mut self) -> P {
        let k = self.tok("import");
        let mut ch = vec![k];
        if self.ts() && self.at_kw("type") && {
            let t2 = self.peek2();
            (t2.kind == TK::Ident && self.peek2_text() != "from") || self.peek2_text() == "{" || self.peek2_text() == "*"
        } {
            let t = self.tok("type");
            ch.push(t);
        }
        if self.peek().kind == TK::Str {
            let s = self.parse_string();
            let s = self.field(s, "source");
            ch.push(s);
            self.parse_import_attribute(&mut ch);
            self.semi(&mut ch);
            return self.node("import_statement", ch);
        }
        // import x = require("y") (TS)
        if self.ts() && self.at_ident() && self.peek2_text() == "=" {
            let id = self.named_leaf("identifier");
            let eq = self.tok("=");
            let mut rch = vec![id, eq];
            self.expect_into("require", &mut rch);
            self.expect_into("(", &mut rch);
            let s = self.parse_string();
            let s = self.field(s, "source");
            rch.push(s);
            self.expect_into(")", &mut rch);
            let r = self.node("import_require_clause", rch);
            ch.push(r);
            self.semi(&mut ch);
            return self.node("import_statement", ch);
        }
        let mut cch = Vec::new();
        if self.at_ident() && !self.at_kw("from") || (self.at_kw("from") && self.peek2_text() == "from") {
            let id = self.named_leaf("identifier");
            cch.push(id);
            self.eat_into(",", &mut cch);
        }
        if self.at("*") {
            let s = self.tok("*");
            let a = self.expect("as");
            let id = self.parse_identifier();
            let ns = self.node("namespace_import", vec![s, a, id]);
            cch.push(ns);
        } else if self.at("{") {
            let mut nch = vec![self.tok("{")];
            while !self.eof() && !self.at("}") {
                let mut sch = Vec::new();
                if self.ts() && self.at_kw("type") && self.peek2().kind == TK::Ident && self.peek2_text() != "as" {
                    let t = self.tok("type");
                    sch.push(t);
                }
                let n = if self.peek().kind == TK::Str { self.parse_string() } else { self.parse_identifier() };
                let n = self.field(n, "name");
                sch.push(n);
                if self.at_kw("as") {
                    let a = self.tok("as");
                    sch.push(a);
                    let al = self.parse_identifier();
                    let al = self.field(al, "alias");
                    sch.push(al);
                }
                let spec = self.node("import_specifier", sch);
                nch.push(spec);
                if !self.eat_into(",", &mut nch) {
                    break;
                }
            }
            self.expect_into("}", &mut nch);
            let ni = self.node("named_imports", nch);
            cch.push(ni);
        }
        if !cch.is_empty() {
            let clause = self.node("import_clause", cch);
            ch.push(clause);
        }
        self.expect_into("from", &mut ch);
        let s = self.parse_string();
        let s = self.field(s, "source");
        ch.push(s);
        self.parse_import_attribute(&mut ch);
        self.semi(&mut ch);
        self.node("import_statement", ch)
    }

    fn parse_import_attribute(&mut self, ch: &mut Vec<P>) {
        if (self.at_kw("with") || self.at_kw("assert")) && self.peek2_text() == "{" {
            let k = if self.at_kw("with") { self.tok("with") } else { self.tok("assert") };
            let o = self.parse_object();
            let n = self.node("import_attribute", vec![k, o]);
            ch.push(n);
        }
    }

    fn parse_identifier(&mut self) -> P {
        if self.at_ident() {
            self.named_leaf("identifier")
        } else {
            let t = self.peek();
            self.b.missing("identifier", t.start)
        }
    }

    fn parse_export(&mut self) -> P {
        let mut ch = Vec::new();
        while self.at("@") {
            let d = self.parse_decorator();
            ch.push(d);
        }
        let k = self.tok("export");
        ch.push(k);
        if self.ts() && self.at_kw("type") && (self.peek2_text() == "{" || self.peek2_text() == "*") {
            let t = self.tok("type");
            ch.push(t);
        }
        if self.at("*") {
            let s = self.tok("*");
            ch.push(s);
            if self.at_kw("as") {
                let a = self.tok("as");
                ch.push(a);
                let id = self.parse_identifier();
                ch.push(id);
                let ns = self.node("namespace_export", ch.split_off(ch.len() - 3));
                ch.push(ns);
            }
            self.expect_into("from", &mut ch);
            let s = self.parse_string();
            let s = self.field(s, "source");
            ch.push(s);
            self.semi(&mut ch);
            return self.node("export_statement", ch);
        }
        if self.at("{") {
            let mut cch = vec![self.tok("{")];
            while !self.eof() && !self.at("}") {
                let mut sch = Vec::new();
                if self.ts() && self.at_kw("type") && self.peek2().kind == TK::Ident && self.peek2_text() != "as" {
                    let t = self.tok("type");
                    sch.push(t);
                }
                let n = if self.peek().kind == TK::Str { self.parse_string() } else { self.parse_identifier() };
                let n = self.field(n, "name");
                sch.push(n);
                if self.at_kw("as") {
                    let a = self.tok("as");
                    sch.push(a);
                    let al = if self.peek().kind == TK::Str { self.parse_string() } else { self.parse_identifier() };
                    let al = self.field(al, "alias");
                    sch.push(al);
                }
                let spec = self.node("export_specifier", sch);
                cch.push(spec);
                if !self.eat_into(",", &mut cch) {
                    break;
                }
            }
            self.expect_into("}", &mut cch);
            let clause = self.node("export_clause", cch);
            ch.push(clause);
            if self.at_kw("from") {
                let f = self.tok("from");
                ch.push(f);
                let s = self.parse_string();
                let s = self.field(s, "source");
                ch.push(s);
            }
            self.semi(&mut ch);
            return self.node("export_statement", ch);
        }
        if self.at_kw("default") {
            let d = self.tok("default");
            ch.push(d);
            let is_decl = self.at_kw("function")
                || self.at_kw("class")
                || (self.at_kw("async") && self.peek2_text() == "function")
                || (self.ts() && self.at_kw("abstract") && self.peek2_text() == "class")
                || (self.ts() && self.at_kw("interface"));
            if is_decl {
                let decl = self.parse_statement();
                let decl = self.field(decl, "declaration");
                ch.push(decl);
            } else {
                let e = self.parse_expression();
                let e = self.field(e, "value");
                ch.push(e);
                self.semi(&mut ch);
            }
            return self.node("export_statement", ch);
        }
        if self.ts() && self.at("=") {
            let eq = self.tok("=");
            ch.push(eq);
            let e = self.parse_expression();
            ch.push(e);
            self.semi(&mut ch);
            return self.node("export_statement", ch);
        }
        if self.ts() && self.at_kw("as") {
            let a = self.tok("as");
            ch.push(a);
            self.expect_into("namespace", &mut ch);
            let id = self.parse_identifier();
            ch.push(id);
            self.semi(&mut ch);
            return self.node("export_statement", ch);
        }
        let decl = self.parse_statement();
        let decl = self.field(decl, "declaration");
        ch.push(decl);
        self.node("export_statement", ch)
    }

    fn save(&self) -> (usize, usize, usize) {
        (self.pos, self.b.nodes.len(), self.extras.len())
    }

    fn restore(&mut self, s: (usize, usize, usize)) {
        self.pos = s.0;
        self.b.nodes.truncate(s.1);
        self.extras.truncate(s.2);
        self.peeked = None;
    }
}

const KEYWORD_NOT_LABEL: &[&str] = &["case", "default", "this", "true", "false", "null", "super"];
