// ---------------- expressions ----------------
fn binary_prec(op: &str) -> Option<(u8, bool)> {
    // (precedence, right_assoc)
    Some(match op {
        "??" => (1, false),
        "||" => (2, false),
        "&&" => (3, false),
        "|" => (4, false),
        "^" => (5, false),
        "&" => (6, false),
        "==" | "!=" | "===" | "!==" => (7, false),
        "<" | ">" | "<=" | ">=" | "instanceof" | "in" => (8, false),
        "<<" | ">>" | ">>>" => (9, false),
        "+" | "-" => (10, false),
        "*" | "/" | "%" => (11, false),
        "**" => (12, true),
        _ => return None,
    })
}

const ASSIGN_OPS: &[&str] = &[
    "+=", "-=", "*=", "/=", "%=", "**=", "<<=", ">>=", ">>>=", "&=", "|=", "^=", "&&=", "||=", "??=",
];

impl<'s> Parser<'s> {
    pub fn parse_expression(&mut self) -> P {
        let first = self.parse_assignment_expr();
        if self.at(",") {
            let mut ch = vec![first];
            while self.at(",") {
                let c = self.tok(",");
                ch.push(c);
                let e = self.parse_assignment_expr();
                ch.push(e);
            }
            return self.node("sequence_expression", ch);
        }
        first
    }

    fn parse_assignment_expr(&mut self) -> P {
        // arrow functions
        if let Some(a) = self.try_arrow_function() {
            return a;
        }
        if self.at_kw("yield") {
            return self.parse_yield();
        }
        let lhs = self.parse_ternary();
        if self.at("=") && !self.in_pattern {
            let lhs = self.to_pattern(lhs);
            let lhs = self.field(lhs, "left");
            let eq = self.tok("=");
            let rhs = self.parse_assignment_expr();
            let rhs = self.field(rhs, "right");
            return self.node("assignment_expression", vec![lhs, eq, rhs]);
        }
        let t = self.peek();
        if t.kind == TK::Punct {
            let text = self.peek_text();
            if let Some(op) = ASSIGN_OPS.iter().find(|o| **o == text) {
                let lhs = self.field(lhs, "left");
                let o = self.tok(op);
                let o = self.field(o, "operator");
                let rhs = self.parse_assignment_expr();
                let rhs = self.field(rhs, "right");
                return self.node("augmented_assignment_expression", vec![lhs, o, rhs]);
            }
        }
        lhs
    }

    fn parse_yield(&mut self) -> P {
        let y = self.tok("yield");
        let mut ch = vec![y];
        if self.at("*") {
            let s = self.tok("*");
            ch.push(s);
        }
        let t = self.peek();
        if t.kind != TK::Eof && !t.nl_before && !self.at(")") && !self.at("]") && !self.at("}") && !self.at(",") && !self.at(";") && !self.at(":") {
            let e = self.parse_assignment_expr();
            ch.push(e);
        }
        self.node("yield_expression", ch)
    }

    /// Convert expression node to pattern node (for destructuring assignment)
    fn to_pattern(&mut self, n: P) -> P {
        let kind = self.b.kind(n);
        match kind {
            "object" => {
                self.b.set_kind(n, "object_pattern");
                let ch = self.b.nodes[n].children.clone();
                for c in ch {
                    match self.b.kind(c) {
                        "pair" => {
                            self.b.set_kind(c, "pair_pattern");
                            let v = self.b.nodes[c].children.iter().copied().find(|&x| self.b.nodes[x].field == Some("value"));
                            if let Some(v) = v {
                                self.to_pattern(v);
                            }
                        }
                        "shorthand_property_identifier" => self.b.set_kind(c, "shorthand_property_identifier_pattern"),
                        "spread_element" => {
                            self.b.set_kind(c, "rest_pattern");
                        }
                        "assignment_expression" => {
                            self.b.set_kind(c, "object_assignment_pattern");
                            let l = self.b.nodes[c].children[0];
                            if self.b.kind(l) == "identifier" {
                                self.b.set_kind(l, "shorthand_property_identifier_pattern");
                            }
                        }
                        _ => {}
                    }
                }
            }
            "array" => {
                self.b.set_kind(n, "array_pattern");
                let ch = self.b.nodes[n].children.clone();
                for c in ch {
                    match self.b.kind(c) {
                        "spread_element" => self.b.set_kind(c, "rest_pattern"),
                        "assignment_expression" => {
                            self.b.set_kind(c, "assignment_pattern");
                            let l = self.b.nodes[c].children[0];
                            self.to_pattern(l);
                        }
                        "object" | "array" => {
                            self.to_pattern(c);
                        }
                        _ => {}
                    }
                }
            }
            _ => {}
        }
        n
    }

    fn parse_ternary(&mut self) -> P {
        let cond = self.parse_binary(0);
        if self.at("?") {
            // TS: optional parameter ambiguity ignored here
            let cond = self.field(cond, "condition");
            let q = self.tok("?");
            let cons = self.parse_assignment_expr();
            let cons = self.field(cons, "consequence");
            let colon = self.expect(":");
            let alt = self.parse_assignment_expr();
            let alt = self.field(alt, "alternative");
            return self.node("ternary_expression", vec![cond, q, cons, colon, alt]);
        }
        cond
    }

    fn parse_binary(&mut self, min_prec: u8) -> P {
        let mut lhs = self.parse_unary();
        loop {
            let t = self.peek();
            if t.kind == TK::Eof {
                break;
            }
            let text = self.peek_text();
            if self.ts() && (text == "as" || text == "satisfies") && !t.nl_before {
                let k = static_str(text);
                let a = self.tok(k);
                let ty = if self.at_kw("const") { self.named_leaf("const") } else { self.parse_type() };
                lhs = self.node(if k == "as" { "as_expression" } else { "satisfies_expression" }, vec![lhs, a, ty]);
                continue;
            }
            let is_op_tok = t.kind == TK::Punct || (t.kind == TK::Ident && (text == "in" || text == "instanceof"));
            if !is_op_tok {
                break;
            }
            let Some((prec, right)) = binary_prec(text) else { break };
            if prec < min_prec || (prec == min_prec && !right) {
                break;
            }
            // '<' in TS could begin type arguments for a call: f<T>(x)
            let op = static_str(text);
            let lhs_f = self.field(lhs, "left");
            let o = self.tok(op);
            let o = self.field(o, "operator");
            let next_min = if right { prec } else { prec + 1 };
            let rhs = self.parse_binary(next_min);
            let rhs = self.field(rhs, "right");
            lhs = self.node("binary_expression", vec![lhs_f, o, rhs]);
        }
        lhs
    }

    fn parse_unary(&mut self) -> P {
        let t = self.peek();
        let text = self.peek_text();
        if t.kind == TK::Punct {
            match text {
                "!" | "~" | "-" | "+" => {
                    let op = static_str(text);
                    let o = self.tok(op);
                    let o = self.field(o, "operator");
                    let arg = self.parse_unary();
                    let arg = self.field(arg, "argument");
                    return self.node("unary_expression", vec![o, arg]);
                }
                "++" | "--" => {
                    let op = static_str(text);
                    let o = self.tok(op);
                    let o = self.field(o, "operator");
                    let arg = self.parse_unary();
                    let arg = self.field(arg, "argument");
                    return self.node("update_expression", vec![o, arg]);
                }
                "<" if self.dialect == Dialect::Ts => {
                    // type assertion <T>expr
                    let save = self.save();
                    let ta = self.parse_type_arguments();
                    if self.b.nodes[ta].children.len() >= 3 && !self.at("=>") && !self.eof() {
                        let e = self.parse_unary();
                        return self.node("type_assertion", vec![ta, e]);
                    }
                    self.restore(save);
                }
                _ => {}
            }
        } else if t.kind == TK::Ident {
            match text {
                "typeof" | "void" | "delete" => {
                    let op = static_str(text);
                    let o = self.tok(op);
                    let o = self.field(o, "operator");
                    let arg = self.parse_unary();
                    let arg = self.field(arg, "argument");
                    return self.node("unary_expression", vec![o, arg]);
                }
                "await" => {
                    let t2 = self.peek2();
                    let t2t = &self.src[t2.start..t2.end];
                    if !(t2.kind == TK::Punct && matches!(t2t, ")" | "]" | "}" | "," | ";" | ":" | "=" | "." | "?.")) && t2.kind != TK::Eof {
                        let a = self.tok("await");
                        let arg = self.parse_unary();
                        return self.node("await_expression", vec![a, arg]);
                    }
                }
                _ => {}
            }
        }
        self.parse_postfix()
    }

    fn parse_postfix(&mut self) -> P {
        let e = self.parse_lhs_expression(true);
        let t = self.peek();
        if t.kind == TK::Punct && !t.nl_before {
            let text = self.peek_text();
            if text == "++" || text == "--" {
                let op = static_str(text);
                let e = self.field(e, "argument");
                let o = self.tok(op);
                let o = self.field(o, "operator");
                return self.node("update_expression", vec![e, o]);
            }
        }
        e
    }

    /// Member / call / subscript chains.
    fn parse_lhs_expression(&mut self, allow_call: bool) -> P {
        let mut e = if self.at_kw("new") && !(self.peek2_text() == "." ) {
            self.parse_new()
        } else {
            self.parse_primary()
        };
        loop {
            let t = self.peek();
            if t.kind == TK::Template {
                if !allow_call {
                    break;
                }
                let e2 = self.field(e, "function");
                let ts = self.parse_template();
                let ts = self.field(ts, "arguments");
                e = self.node("call_expression", vec![e2, ts]);
                continue;
            }
            if t.kind != TK::Punct {
                break;
            }
            let text = self.peek_text();
            match text {
                "." => {
                    let e2 = self.field(e, "object");
                    let d = self.tok(".");
                    let p = if self.peek().kind == TK::Private {
                        self.named_leaf("private_property_identifier")
                    } else if self.at_ident() {
                        self.named_leaf("property_identifier")
                    } else {
                        let tt = self.peek();
                        self.b.missing("property_identifier", tt.start)
                    };
                    let p = self.field(p, "property");
                    e = self.node("member_expression", vec![e2, d, p]);
                }
                "?." => {
                    let oc = self.named_leaf("optional_chain");
                    let oc = self.field(oc, "optional_chain");
                    if self.at("(") {
                        if !allow_call {
                            break;
                        }
                        let e2 = self.field(e, "function");
                        let args = self.parse_arguments();
                        let args = self.field(args, "arguments");
                        e = self.node("call_expression", vec![e2, oc, args]);
                    } else if self.at("[") {
                        let e2 = self.field(e, "object");
                        let l = self.tok("[");
                        let idx = self.parse_expression();
                        let idx = self.field(idx, "index");
                        let r = self.expect("]");
                        e = self.node("subscript_expression", vec![e2, oc, l, idx, r]);
                    } else {
                        let e2 = self.field(e, "object");
                        let p = if self.peek().kind == TK::Private {
                            self.named_leaf("private_property_identifier")
                        } else {
                            self.named_leaf("property_identifier")
                        };
                        let p = self.field(p, "property");
                        e = self.node("member_expression", vec![e2, oc, p]);
                    }
                }
                "[" => {
                    let e2 = self.field(e, "object");
                    let l = self.tok("[");
                    let idx = self.parse_expression();
                    let idx = self.field(idx, "index");
                    let r = self.expect("]");
                    e = self.node("subscript_expression", vec![e2, l, idx, r]);
                }
                "(" if allow_call => {
                    let e2 = self.field(e, "function");
                    let args = self.parse_arguments();
                    let args = self.field(args, "arguments");
                    e = self.node("call_expression", vec![e2, args]);
                }
                "!" if self.ts() && !t.nl_before => {
                    // non-null assertion: only if not followed by something that makes it binary `!=`
                    let b = self.tok("!");
                    e = self.node("non_null_expression", vec![e, b]);
                }
                "<" if self.ts() && allow_call => {
                    // generic call f<T>(x)
                    let save = self.save();
                    let ta = self.parse_type_arguments();
                    if self.at("(") && self.b.nodes[ta].children.len() >= 3 {
                        let e2 = self.field(e, "function");
                        let ta = self.field(ta, "type_arguments");
                        let args = self.parse_arguments();
                        let args = self.field(args, "arguments");
                        e = self.node("call_expression", vec![e2, ta, args]);
                    } else if self.peek().kind == TK::Template && self.b.nodes[ta].children.len() >= 3 {
                        let e2 = self.field(e, "function");
                        let ta = self.field(ta, "type_arguments");
                        let ts = self.parse_template();
                        let ts = self.field(ts, "arguments");
                        e = self.node("call_expression", vec![e2, ta, ts]);
                    } else {
                        self.restore(save);
                        break;
                    }
                }
                _ => break,
            }
        }
        e
    }

    fn parse_new(&mut self) -> P {
        let n = self.tok("new");
        let mut ch = vec![n];
        let ctor = self.parse_lhs_expression(false);
        let ctor = self.field(ctor, "constructor");
        ch.push(ctor);
        if self.ts() && self.at("<") {
            let save = self.save();
            let ta = self.parse_type_arguments();
            if self.at("(") {
                let ta = self.field(ta, "type_arguments");
                ch.push(ta);
            } else {
                self.restore(save);
            }
        }
        if self.at("(") {
            let args = self.parse_arguments();
            let args = self.field(args, "arguments");
            ch.push(args);
        }
        self.node("new_expression", ch)
    }

    fn parse_arguments(&mut self) -> P {
        let mut ch = vec![self.expect("(")];
        while !self.eof() && !self.at(")") {
            if self.at(",") {
                let c = self.tok(",");
                ch.push(c);
                continue;
            }
            let before = self.pos;
            let e = if self.at("...") {
                let d = self.tok("...");
                let v = self.parse_assignment_expr();
                self.node("spread_element", vec![d, v])
            } else {
                self.parse_assignment_expr()
            };
            ch.push(e);
            if self.pos == before {
                let bad = self.error_tok();
                let err = self.node("ERROR", vec![bad]);
                ch.push(err);
                continue;
            }
            if !self.eat_into(",", &mut ch) {
                break;
            }
        }
        self.expect_into(")", &mut ch);
        self.node("arguments", ch)
    }

    fn try_arrow_function(&mut self) -> Option<P> {
        let t = self.peek();
        let mut ch = Vec::new();
        let save = self.save();
        if t.kind == TK::Ident && self.peek_text() == "async" && !self.peek2().nl_before {
            let t2 = self.peek2();
            let t2t = &self.src[t2.start..t2.end];
            if t2.kind == TK::Ident && t2t != "function" || (t2.kind == TK::Punct && (t2t == "(" || t2t == "<")) {
                let a = self.tok("async");
                ch.push(a);
            }
        }
        let t = self.peek();
        if t.kind == TK::Ident {
            if self.peek2_text() == "=>" && !KEYWORDS_NOT_IDENT.contains(&self.peek_text()) {
                let p = self.named_leaf("identifier");
                let p = self.field(p, "parameter");
                ch.push(p);
                let arrow = self.tok("=>");
                ch.push(arrow);
                let body = self.parse_arrow_body();
                ch.push(body);
                return Some(self.node("arrow_function", ch));
            }
            self.restore(save);
            return None;
        }
        if t.kind == TK::Punct && (self.peek_text() == "(" || (self.ts() && self.peek_text() == "<")) {
            // speculative parse
            if self.ts() && self.at("<") {
                let tp = self.parse_type_parameters();
                if !self.at("(") {
                    self.restore(save);
                    return None;
                }
                let tp = self.field(tp, "type_parameters");
                ch.push(tp);
            }
            if !self.looks_like_arrow_params() {
                self.restore(save);
                return None;
            }
            let params = self.parse_formal_parameters();
            let params = self.field(params, "parameters");
            ch.push(params);
            if self.ts() && self.at(":") {
                let rt = self.parse_type_annotation_or_predicate();
                let rt = self.field(rt, "return_type");
                ch.push(rt);
            }
            if !self.at("=>") {
                self.restore(save);
                return None;
            }
            let arrow = self.tok("=>");
            ch.push(arrow);
            let body = self.parse_arrow_body();
            ch.push(body);
            return Some(self.node("arrow_function", ch));
        }
        self.restore(save);
        None
    }

    /// Scan balanced parens starting at `(` and check whether `=>` (or `: type =>`) follows.
    fn looks_like_arrow_params(&mut self) -> bool {
        let start = self.peek();
        let mut depth = 0i32;
        let mut pos = start.start;
        loop {
            let mut c = Vec::new();
            let (p, nl) = self.skip_trivia(pos, &mut c);
            let t = self.lex_at(p, nl);
            if t.kind == TK::Eof {
                return false;
            }
            pos = t.end;
            if t.kind == TK::Template {
                // skip template roughly
                let e = self.skip_template_raw(t.start);
                pos = e;
                continue;
            }
            if t.kind == TK::Punct {
                match &self.src[t.start..t.end] {
                    "(" | "[" | "{" | "${" => depth += 1,
                    ")" | "]" | "}" => {
                        depth -= 1;
                        if depth == 0 {
                            break;
                        }
                    }
                    _ => {}
                }
            }
        }
        let mut c = Vec::new();
        let (p, nl) = self.skip_trivia(pos, &mut c);
        let t = self.lex_at(p, nl);
        if t.kind == TK::Punct && &self.src[t.start..t.end] == "=>" {
            return true;
        }
        if self.ts() && t.kind == TK::Punct && &self.src[t.start..t.end] == ":" {
            // speculative type parse
            let save = self.save();
            self.pos = pos;
            self.peeked = None;
            let _ = self.parse_type_annotation_or_predicate();
            let ok = self.at("=>");
            self.restore(save);
            // restore also resets pos to before the '(' because save() captured it
            return ok;
        }
        false
    }

    fn skip_template_raw(&self, start: usize) -> usize {
        let bytes = self.src.as_bytes();
        let mut i = start + 1;
        let mut depth = 0;
        while i < bytes.len() {
            match bytes[i] {
                b'\\' => i += 2,
                b'`' if depth == 0 => return i + 1,
                b'$' if i + 1 < bytes.len() && bytes[i + 1] == b'{' => {
                    depth += 1;
                    i += 2;
                }
                b'}' if depth > 0 => {
                    depth -= 1;
                    i += 1;
                }
                _ => i += 1,
            }
        }
        bytes.len()
    }

    fn parse_arrow_body(&mut self) -> P {
        let b = if self.at("{") { self.parse_block() } else { self.parse_assignment_expr() };
        self.field(b, "body")
    }

    fn parse_primary(&mut self) -> P {
        let t = self.peek();
        match t.kind {
            TK::Eof => self.b.missing("identifier", t.start),
            TK::Number => self.named_leaf("number"),
            TK::Str => self.parse_string(),
            TK::Template => self.parse_template(),
            TK::Private => {
                let p = self.named_leaf("private_property_identifier");
                p
            }
            TK::Ident => {
                let text = self.peek_text();
                match text {
                    "this" | "super" | "true" | "false" | "null" | "undefined" => {
                        let k = static_str(text);
                        self.named_leaf(k)
                    }
                    "function" => self.parse_function_expression(vec![]),
                    "async" if self.peek2_text() == "function" && !self.peek2().nl_before => {
                        let a = self.tok("async");
                        self.parse_function_expression(vec![a])
                    }
                    "class" => {
                        let mut ch = vec![self.tok("class")];
                        if self.at_ident() && !self.at_kw("extends") && !self.at_kw("implements") {
                            let n = self.named_leaf(if self.ts() { "type_identifier" } else { "identifier" });
                            let n = self.field(n, "name");
                            ch.push(n);
                        }
                        self.parse_class_tail(&mut ch);
                        self.node("class", ch)
                    }
                    "new" => self.parse_new(),
                    "import" => {
                        let i = self.named_leaf("import");
                        i
                    }
                    _ => self.named_leaf("identifier"),
                }
            }
            TK::Punct => {
                let text = self.peek_text();
                match text {
                    "(" => {
                        let l = self.tok("(");
                        let e = self.parse_expression();
                        let mut ch = vec![l, e];
                        if self.ts() && self.at(":") {
                            let ta = self.parse_type_annotation();
                            let ta = self.field(ta, "type");
                            ch.push(ta);
                        }
                        self.expect_into(")", &mut ch);
                        self.node("parenthesized_expression", ch)
                    }
                    "[" => self.parse_array(),
                    "{" => self.parse_object(),
                    "/" | "/=" => self.parse_regex(),
                    "<" if self.dialect != Dialect::Ts => self.parse_jsx_element(),
                    "@" => {
                        let mut decos = Vec::new();
                        while self.at("@") {
                            let d = self.parse_decorator();
                            decos.push(d);
                        }
                        let mut ch = decos;
                        ch.push(self.expect("class"));
                        if self.at_ident() && !self.at_kw("extends") {
                            let n = self.named_leaf("identifier");
                            let n = self.field(n, "name");
                            ch.push(n);
                        }
                        self.parse_class_tail(&mut ch);
                        self.node("class", ch)
                    }
                    "#" => {
                        let e = self.error_tok();
                        self.node("ERROR", vec![e])
                    }
                    _ => {
                        let e = self.error_tok();
                        self.node("ERROR", vec![e])
                    }
                }
            }
        }
    }

    fn parse_function_expression(&mut self, mut ch: Vec<P>) -> P {
        let f = self.tok("function");
        ch.push(f);
        let gen = self.eat_into("*", &mut ch);
        if self.at_ident() {
            let n = self.named_leaf("identifier");
            let n = self.field(n, "name");
            ch.push(n);
        }
        self.parse_function_rest(&mut ch);
        let body = self.parse_block();
        let body = self.field(body, "body");
        ch.push(body);
        self.node(if gen { "generator_function" } else { "function_expression" }, ch)
    }

    fn parse_array(&mut self) -> P {
        let mut ch = vec![self.tok("[")];
        while !self.eof() && !self.at("]") {
            if self.at(",") {
                let c = self.tok(",");
                ch.push(c);
                continue;
            }
            let before = self.pos;
            let e = if self.at("...") {
                let d = self.tok("...");
                let v = self.parse_assignment_expr();
                self.node("spread_element", vec![d, v])
            } else {
                self.parse_assignment_expr()
            };
            ch.push(e);
            if self.pos == before {
                let bad = self.error_tok();
                let err = self.node("ERROR", vec![bad]);
                ch.push(err);
                continue;
            }
            if !self.eat_into(",", &mut ch) {
                break;
            }
        }
        self.expect_into("]", &mut ch);
        self.node("array", ch)
    }

    fn parse_object(&mut self) -> P {
        let mut ch = vec![self.expect("{")];
        while !self.eof() && !self.at("}") {
            if self.at(",") {
                let c = self.tok(",");
                ch.push(c);
                continue;
            }
            let before = self.pos;
            let m = self.parse_object_member();
            ch.push(m);
            if self.pos == before {
                let bad = self.error_tok();
                let err = self.node("ERROR", vec![bad]);
                ch.push(err);
                continue;
            }
            if !self.eat_into(",", &mut ch) {
                break;
            }
        }
        self.expect_into("}", &mut ch);
        self.node("object", ch)
    }

    fn parse_object_member(&mut self) -> P {
        if self.at("...") {
            let d = self.tok("...");
            let v = self.parse_assignment_expr();
            return self.node("spread_element", vec![d, v]);
        }
        let mut ch = Vec::new();
        // method modifiers
        let t = self.peek();
        let t2 = self.peek2();
        let t2t = &self.src[t2.start..t2.end];
        let next_is_name = t2.kind == TK::Ident || t2.kind == TK::Str || t2.kind == TK::Number || t2t == "[" || t2t == "*";
        if t.kind == TK::Ident && next_is_name {
            match self.peek_text() {
                "async" => {
                    let a = self.tok("async");
                    ch.push(a);
                }
                "get" | "set" => {
                    let k = static_str(self.peek_text());
                    let g = self.tok(k);
                    ch.push(g);
                }
                _ => {}
            }
        }
        if self.at("*") {
            let s = self.tok("*");
            ch.push(s);
        }
        let t = self.peek();
        if t.kind == TK::Ident && ch.is_empty() {
            let t2t = self.peek2_text();
            if t2t != ":" && t2t != "(" && t2t != "<" {
                // shorthand
                let id = self.named_leaf("shorthand_property_identifier");
                if self.at("=") {
                    // object_assignment_pattern (only valid in patterns, but tree-sitter parses it)
                    let id = self.field(id, "left");
                    let eq = self.tok("=");
                    let v = self.parse_assignment_expr();
                    let v = self.field(v, "right");
                    return self.node("object_assignment_pattern", vec![id, eq, v]);
                }
                return id;
            }
        }
        if !self.is_member_name_start() {
            if ch.is_empty() {
                let e = self.error_tok();
                return self.node("ERROR", vec![e]);
            }
            return self.node("ERROR", ch);
        }
        let name = self.parse_property_name();
        if self.at("(") || self.at("<") {
            let name = self.field(name, "name");
            ch.push(name);
            self.parse_function_rest(&mut ch);
            let body = self.parse_block();
            let body = self.field(body, "body");
            ch.push(body);
            return self.node("method_definition", ch);
        }
        let name = self.field(name, "key");
        ch.push(name);
        let c = self.expect(":");
        ch.push(c);
        let v = self.parse_assignment_expr();
        let v = self.field(v, "value");
        ch.push(v);
        self.node("pair", ch)
    }

    fn parse_string(&mut self) -> P {
        let t = self.advance();
        let quote = &self.src[t.start..t.start + 1];
        let q: &'static str = if quote == "\"" { "\"" } else { "'" };
        let mut ch = vec![self.b.token(q, t.start, t.start + 1)];
        let closed = t.end > t.start + 1 && self.src.as_bytes()[t.end - 1] == q.as_bytes()[0] && t.end - 1 > t.start;
        let content_end = if closed { t.end - 1 } else { t.end };
        self.string_fragments(t.start + 1, content_end, &mut ch);
        if closed {
            let c = self.b.token(q, t.end - 1, t.end);
            ch.push(c);
        } else {
            let m = self.b.missing(q, t.end);
            ch.push(m);
        }
        self.b.node_with_range("string", ch, t.start, t.end)
    }

    fn string_fragments(&mut self, start: usize, end: usize, ch: &mut Vec<P>) {
        let bytes = self.src.as_bytes();
        let mut i = start;
        let mut frag_start = start;
        while i < end {
            if bytes[i] == b'\\' {
                if frag_start < i {
                    let f = self.b.leaf("string_fragment", true, frag_start, i);
                    ch.push(f);
                }
                let mut esc_end = (i + 2).min(end);
                // unicode escapes
                if i + 1 < end {
                    match bytes[i + 1] {
                        b'u' => {
                            if i + 2 < end && bytes[i + 2] == b'{' {
                                let close = self.src[i..end].find('}').map(|x| i + x + 1).unwrap_or(end);
                                esc_end = close;
                            } else {
                                esc_end = (i + 6).min(end);
                            }
                        }
                        b'x' => esc_end = (i + 4).min(end),
                        _ => {}
                    }
                }
                let e = self.b.leaf("escape_sequence", true, i, esc_end);
                ch.push(e);
                i = esc_end;
                frag_start = i;
                continue;
            }
            i += 1;
        }
        if frag_start < end {
            let f = self.b.leaf("string_fragment", true, frag_start, end);
            ch.push(f);
        }
    }

    fn parse_template(&mut self) -> P {
        let t = self.advance(); // the opening backtick
        let mut ch = vec![self.b.token("`", t.start, t.end)];
        let bytes = self.src.as_bytes();
        let mut i = t.end;
        let mut frag_start = i;
        loop {
            if i >= bytes.len() {
                if frag_start < i {
                    let f = self.b.leaf("string_fragment", true, frag_start, i);
                    ch.push(f);
                }
                let m = self.b.missing("`", i);
                ch.push(m);
                self.pos = i;
                self.peeked = None;
                break;
            }
            match bytes[i] {
                b'\\' => {
                    if frag_start < i {
                        let f = self.b.leaf("string_fragment", true, frag_start, i);
                        ch.push(f);
                    }
                    let esc_end = (i + 2).min(bytes.len());
                    let e = self.b.leaf("escape_sequence", true, i, esc_end);
                    ch.push(e);
                    i = esc_end;
                    frag_start = i;
                }
                b'`' => {
                    if frag_start < i {
                        let f = self.b.leaf("string_fragment", true, frag_start, i);
                        ch.push(f);
                    }
                    let c = self.b.token("`", i, i + 1);
                    ch.push(c);
                    self.pos = i + 1;
                    self.peeked = None;
                    break;
                }
                b'$' if i + 1 < bytes.len() && bytes[i + 1] == b'{' => {
                    if frag_start < i {
                        let f = self.b.leaf("string_fragment", true, frag_start, i);
                        ch.push(f);
                    }
                    let open = self.b.token("${", i, i + 2);
                    self.pos = i + 2;
                    self.peeked = None;
                    let e = self.parse_expression();
                    let mut sch = vec![open, e];
                    if self.ts() && self.at(":") {
                        let ta = self.parse_type_annotation();
                        sch.push(ta);
                    }
                    let close = self.expect("}");
                    sch.push(close);
                    let sub = self.node("template_substitution", sch);
                    ch.push(sub);
                    i = self.pos;
                    frag_start = i;
                }
                _ => i += 1,
            }
        }
        self.node("template_string", ch)
    }

    fn parse_regex(&mut self) -> P {
        let t = self.peek();
        let start = t.start;
        let bytes = self.src.as_bytes();
        let mut i = start + 1;
        let mut in_class = false;
        while i < bytes.len() {
            match bytes[i] {
                b'\\' => i += 2,
                b'[' => {
                    in_class = true;
                    i += 1;
                }
                b']' => {
                    in_class = false;
                    i += 1;
                }
                b'/' if !in_class => break,
                b'\n' => break,
                _ => i += 1,
            }
        }
        let pat_end = i.min(bytes.len());
        let mut ch = vec![];
        self.commit_comments();
        let open = self.b.token("/", start, start + 1);
        ch.push(open);
        let pat = self.b.leaf("regex_pattern", true, start + 1, pat_end);
        let pat = self.field(pat, "pattern");
        ch.push(pat);
        let mut end = pat_end;
        if pat_end < bytes.len() && bytes[pat_end] == b'/' {
            let close = self.b.token("/", pat_end, pat_end + 1);
            ch.push(close);
            end = pat_end + 1;
            let fe = ident_end(self.src, end);
            if fe > end {
                let flags = self.b.leaf("regex_flags", true, end, fe);
                let flags = self.field(flags, "flags");
                ch.push(flags);
                end = fe;
            }
        } else {
            let m = self.b.missing("/", pat_end);
            ch.push(m);
        }
        self.pos = end;
        self.peeked = None;
        self.b.node_with_range("regex", ch, start, end)
    }

    // ---------------- JSX ----------------
    fn parse_jsx_element(&mut self) -> P {
        let lt = self.tok("<");
        let mut och = vec![lt];
        if self.at(">") {
            // fragment
            let gt = self.tok(">");
            och.push(gt);
            let open = self.node("jsx_opening_element", och);
            let open = self.field(open, "open_tag");
            let mut ch = vec![open];
            self.parse_jsx_children(&mut ch);
            let close = self.parse_jsx_closing();
            ch.push(close);
            return self.node("jsx_element", ch);
        }
        let name = self.parse_jsx_name();
        let name = self.field(name, "name");
        och.push(name);
        if self.ts() && self.at("<") {
            let ta = self.parse_type_arguments();
            och.push(ta);
        }
        while !self.eof() && !self.at(">") && !self.at("/>") {
            let before = self.pos;
            if self.at("{") {
                let l = self.tok("{");
                let d = self.expect("...");
                let e = self.parse_assignment_expr();
                let sp = self.node("spread_element", vec![d, e]);
                let r = self.expect("}");
                let je = self.node("jsx_expression", vec![l, sp, r]);
                let je = self.field(je, "attribute");
                och.push(je);
            } else if self.at_ident() {
                let mut ach = Vec::new();
                let n = self.named_leaf("property_identifier");
                if self.at(":") {
                    let c = self.tok(":");
                    let n2 = self.named_leaf("property_identifier");
                    let nn = self.node("jsx_namespace_name", vec![n, c, n2]);
                    ach.push(nn);
                } else {
                    ach.push(n);
                }
                if self.at("=") {
                    let eq = self.tok("=");
                    ach.push(eq);
                    if self.peek().kind == TK::Str {
                        let s = self.parse_string();
                        ach.push(s);
                    } else if self.at("{") {
                        let l = self.tok("{");
                        let e = self.parse_expression();
                        let r = self.expect("}");
                        let je = self.node("jsx_expression", vec![l, e, r]);
                        ach.push(je);
                    } else if self.at("<") {
                        let el = self.parse_jsx_element();
                        ach.push(el);
                    }
                }
                let a = self.node("jsx_attribute", ach);
                let a = self.field(a, "attribute");
                och.push(a);
            } else {
                let e = self.error_tok();
                let err = self.node("ERROR", vec![e]);
                och.push(err);
            }
            if self.pos == before {
                break;
            }
        }
        if self.at("/>") {
            let s = self.tok("/>");
            och.push(s);
            return self.node("jsx_self_closing_element", och);
        }
        let gt = self.expect(">");
        och.push(gt);
        let open = self.node("jsx_opening_element", och);
        let open = self.field(open, "open_tag");
        let mut ch = vec![open];
        self.parse_jsx_children(&mut ch);
        let close = self.parse_jsx_closing();
        ch.push(close);
        self.node("jsx_element", ch)
    }

    fn parse_jsx_name(&mut self) -> P {
        let mut n = self.named_leaf("identifier");
        if self.at(":") {
            let c = self.tok(":");
            let n2 = self.named_leaf("identifier");
            return self.node("jsx_namespace_name", vec![n, c, n2]);
        }
        while self.at(".") {
            let o = self.field(n, "object");
            let d = self.tok(".");
            let p = self.named_leaf("property_identifier");
            let p = self.field(p, "property");
            n = self.node("member_expression", vec![o, d, p]);
        }
        n
    }

    fn parse_jsx_children(&mut self, ch: &mut Vec<P>) {
        // raw scanning of jsx text
        loop {
            self.peeked = None;
            let bytes = self.src.as_bytes();
            let mut i = self.pos;
            let text_start = i;
            while i < bytes.len() && bytes[i] != b'<' && bytes[i] != b'{' {
                i += 1;
            }
            if i > text_start {
                let txt = &self.src[text_start..i];
                if !txt.trim().is_empty() {
                    let t = self.b.leaf("jsx_text", true, text_start, i);
                    ch.push(t);
                } else if txt.contains('\n') || true {
                    // whitespace-only text containing newline is dropped by tree-sitter;
                    // whitespace only without newline is jsx_text
                    if !txt.contains('\n') && !txt.is_empty() {
                        let t = self.b.leaf("jsx_text", true, text_start, i);
                        ch.push(t);
                    }
                }
            }
            self.pos = i;
            self.peeked = None;
            if i >= bytes.len() {
                return;
            }
            if bytes[i] == b'{' {
                let l = self.tok("{");
                let mut ech = vec![l];
                if !self.at("}") {
                    let e = if self.at("...") {
                        let d = self.tok("...");
                        let v = self.parse_assignment_expr();
                        self.node("spread_element", vec![d, v])
                    } else {
                        self.parse_expression()
                    };
                    ech.push(e);
                }
                let r = self.expect("}");
                ech.push(r);
                let je = self.node("jsx_expression", ech);
                ch.push(je);
                continue;
            }
            // '<'
            if self.src[i..].starts_with("</") {
                return;
            }
            let el = self.parse_jsx_element();
            ch.push(el);
        }
    }

    fn parse_jsx_closing(&mut self) -> P {
        let mut ch = vec![self.expect("</")];
        if !self.at(">") {
            let n = self.parse_jsx_name();
            let n = self.field(n, "name");
            ch.push(n);
        }
        self.expect_into(">", &mut ch);
        let c = self.node("jsx_closing_element", ch);
        self.field(c, "close_tag")
    }
}

