// ---------------- TypeScript types ----------------
const PREDEFINED_TYPES: &[&str] = &["any", "number", "boolean", "string", "symbol", "void", "unknown", "never", "object", "bigint", "undefined", "null"];

impl<'s> Parser<'s> {
    fn parse_type_annotation(&mut self) -> P {
        let c = self.expect(":");
        let t = self.parse_type();
        self.node("type_annotation", vec![c, t])
    }

    fn parse_type_annotation_or_predicate(&mut self) -> P {
        let c = self.expect(":");
        // asserts x is T / x is T
        if self.at_kw("asserts") && self.peek2().kind == TK::Ident {
            let a = self.tok("asserts");
            let mut ch = vec![a];
            let id = if self.at_kw("this") { self.named_leaf("this") } else { self.named_leaf("identifier") };
            ch.push(id);
            if self.at_kw("is") {
                let i = self.tok("is");
                ch.push(i);
                let t = self.parse_type();
                ch.push(t);
            }
            let n = self.node("asserts", ch);
            let a2 = self.node("asserts_annotation", vec![c, n]);
            return a2;
        }
        if self.at_ident() && self.peek2_text() == "is" {
            let id = if self.at_kw("this") { self.named_leaf("this") } else { self.named_leaf("identifier") };
            let id = self.field(id, "name");
            let i = self.tok("is");
            let t = self.parse_type();
            let t = self.field(t, "type");
            let p = self.node("type_predicate", vec![id, i, t]);
            return self.node("type_predicate_annotation", vec![c, p]);
        }
        let t = self.parse_type();
        self.node("type_annotation", vec![c, t])
    }

    fn parse_type_parameters(&mut self) -> P {
        let mut ch = vec![self.expect("<")];
        while !self.eof() && !self.at(">") {
            let mut pch = Vec::new();
            if self.at_kw("const") {
                let c = self.tok("const");
                pch.push(c);
            }
            if self.at_kw("in") || self.at_kw("out") {
                let k = static_str(self.peek_text());
                let c = self.tok(k);
                pch.push(c);
            }
            let n = self.named_leaf("type_identifier");
            let n = self.field(n, "name");
            pch.push(n);
            if self.at_kw("extends") {
                let e = self.tok("extends");
                let t = self.parse_type();
                let c = self.node("constraint", vec![e, t]);
                let c = self.field(c, "constraint");
                pch.push(c);
            }
            if self.at("=") {
                let e = self.tok("=");
                let t = self.parse_type();
                let d = self.node("default_type", vec![e, t]);
                let d = self.field(d, "value");
                pch.push(d);
            }
            let p = self.node("type_parameter", pch);
            ch.push(p);
            if !self.eat_into(",", &mut ch) {
                break;
            }
        }
        self.expect_gt(&mut ch);
        self.node("type_parameters", ch)
    }

    /// handle `>` possibly glued as `>>` or `>>>` or `>=`
    fn expect_gt(&mut self, ch: &mut Vec<P>) {
        let t = self.peek();
        if t.kind == TK::Punct && self.src[t.start..].starts_with('>') {
            self.commit_comments();
            let n = self.b.token(">", t.start, t.start + 1);
            self.pos = t.start + 1;
            self.peeked = None;
            ch.push(n);
        } else {
            let m = self.b.missing(">", t.start);
            ch.push(m);
        }
    }

    fn parse_type_arguments(&mut self) -> P {
        let mut ch = vec![self.expect("<")];
        while !self.eof() && !self.at(">") && !self.src[self.peek().start..].starts_with('>') {
            let before = self.pos;
            let t = self.parse_type();
            ch.push(t);
            if self.pos == before {
                break;
            }
            if !self.eat_into(",", &mut ch) {
                break;
            }
        }
        self.expect_gt(&mut ch);
        self.node("type_arguments", ch)
    }

    pub fn parse_type(&mut self) -> P {
        // function types / constructor types
        if self.at_kw("new") && self.peek2_text() == "(" || (self.at_kw("abstract") && self.peek2_text() == "new") {
            let mut ch = Vec::new();
            if self.at_kw("abstract") {
                let a = self.tok("abstract");
                ch.push(a);
            }
            let n = self.tok("new");
            ch.push(n);
            let p = self.parse_formal_parameters();
            let p = self.field(p, "parameters");
            ch.push(p);
            let a = self.expect("=>");
            ch.push(a);
            let t = self.parse_type();
            let t = self.field(t, "type");
            ch.push(t);
            return self.node("constructor_type", ch);
        }
        if self.at("<") || (self.at("(") && self.looks_like_arrow_params()) {
            let mut ch = Vec::new();
            if self.at("<") {
                let tp = self.parse_type_parameters();
                let tp = self.field(tp, "type_parameters");
                ch.push(tp);
            }
            let p = self.parse_formal_parameters();
            let p = self.field(p, "parameters");
            ch.push(p);
            let a = self.expect("=>");
            ch.push(a);
            let t = if self.at_kw("asserts") || (self.at_ident() && self.peek2_text() == "is") {
                let save = self.save();
                let _ = save;
                self.parse_type_predicate_bare()
            } else {
                self.parse_type()
            };
            let t = self.field(t, "return_type");
            ch.push(t);
            return self.node("function_type", ch);
        }
        let first = self.parse_intersection_type();
        if self.at("|") {
            let mut ch = vec![first];
            while self.at("|") {
                let o = self.tok("|");
                ch.push(o);
                let t = self.parse_intersection_type();
                ch.push(t);
            }
            let u = self.node("union_type", ch);
            return self.parse_conditional_tail(u);
        }
        self.parse_conditional_tail(first)
    }

    fn parse_type_predicate_bare(&mut self) -> P {
        if self.at_kw("asserts") {
            let a = self.tok("asserts");
            let mut ch = vec![a];
            let id = self.named_leaf("identifier");
            ch.push(id);
            if self.at_kw("is") {
                let i = self.tok("is");
                ch.push(i);
                let t = self.parse_type();
                ch.push(t);
            }
            return self.node("asserts", ch);
        }
        let id = self.named_leaf("identifier");
        let id = self.field(id, "name");
        let i = self.tok("is");
        let t = self.parse_type();
        let t = self.field(t, "type");
        self.node("type_predicate", vec![id, i, t])
    }

    fn parse_conditional_tail(&mut self, left: P) -> P {
        if self.at_kw("extends") {
            let left = self.field(left, "left");
            let e = self.tok("extends");
            let right = self.parse_type_no_conditional();
            let right = self.field(right, "right");
            let q = self.expect("?");
            let cons = self.parse_type();
            let cons = self.field(cons, "consequence");
            let c = self.expect(":");
            let alt = self.parse_type();
            let alt = self.field(alt, "alternative");
            return self.node("conditional_type", vec![left, e, right, q, cons, c, alt]);
        }
        left
    }

    fn parse_type_no_conditional(&mut self) -> P {
        let first = self.parse_intersection_type();
        if self.at("|") {
            let mut ch = vec![first];
            while self.at("|") {
                let o = self.tok("|");
                ch.push(o);
                let t = self.parse_intersection_type();
                ch.push(t);
            }
            return self.node("union_type", ch);
        }
        first
    }

    fn parse_intersection_type(&mut self) -> P {
        // leading | or & allowed
        let first = self.parse_type_operator();
        if self.at("&") {
            let mut ch = vec![first];
            while self.at("&") {
                let o = self.tok("&");
                ch.push(o);
                let t = self.parse_type_operator();
                ch.push(t);
            }
            return self.node("intersection_type", ch);
        }
        first
    }

    fn parse_type_operator(&mut self) -> P {
        if self.at_kw("keyof") {
            let k = self.tok("keyof");
            let t = self.parse_type_operator();
            return self.node("index_type_query", vec![k, t]);
        }
        if self.at_kw("readonly") {
            let k = self.tok("readonly");
            let t = self.parse_type_operator();
            return self.node("readonly_type", vec![k, t]);
        }
        if self.at_kw("unique") {
            let k = self.tok("unique");
            let t = self.parse_type_operator();
            return self.node("unique_type", vec![k, t]); // approximate
        }
        if self.at_kw("infer") {
            let k = self.tok("infer");
            let n = self.named_leaf("type_identifier");
            let n = self.field(n, "name");
            let mut ch = vec![k, n];
            if self.at_kw("extends") {
                let e = self.tok("extends");
                let t = self.parse_type_no_conditional();
                let c = self.node("constraint", vec![e, t]);
                let c = self.field(c, "constraint");
                ch.push(c);
            }
            return self.node("infer_type", ch);
        }
        if self.at_kw("typeof") {
            let k = self.tok("typeof");
            let e = self.parse_lhs_expression(false);
            let mut ch = vec![k, e];
            if self.at("<") {
                let ta = self.parse_type_arguments();
                let ta = self.field(ta, "type_arguments");
                ch.push(ta);
            }
            let q = self.node("type_query", ch);
            return self.parse_type_postfix(q);
        }
        let p = self.parse_primary_type();
        self.parse_type_postfix(p)
    }

    fn parse_type_postfix(&mut self, mut t: P) -> P {
        loop {
            let tk = self.peek();
            if tk.nl_before || tk.kind != TK::Punct {
                break;
            }
            if self.at("[") {
                let l = self.tok("[");
                if self.at("]") {
                    let r = self.tok("]");
                    t = self.node("array_type", vec![t, l, r]);
                } else {
                    let idx = self.parse_type();
                    let r = self.expect("]");
                    t = self.node("lookup_type", vec![t, l, idx, r]);
                }
            } else {
                break;
            }
        }
        t
    }

    fn parse_primary_type(&mut self) -> P {
        let t = self.peek();
        match t.kind {
            TK::Str => {
                let s = self.parse_string();
                self.node("literal_type", vec![s])
            }
            TK::Number => {
                let n = self.named_leaf("number");
                self.node("literal_type", vec![n])
            }
            TK::Template => {
                let tpl = self.parse_template();
                self.b.set_kind(tpl, "template_literal_type");
                tpl
            }
            TK::Ident => {
                let text = self.peek_text();
                match text {
                    "true" | "false" | "null" | "undefined" => {
                        let k = static_str(text);
                        let n = self.named_leaf(k);
                        if text == "null" || text == "undefined" {
                            return n;
                        }
                        self.node("literal_type", vec![n])
                    }
                    "this" => self.named_leaf("this_type"),
                    "void" => {
                        let k = self.tok("void");
                        self.node("predefined_type", vec![k])
                    }
                    "asserts" => self.parse_type_predicate_bare(),
                    _ if PREDEFINED_TYPES.contains(&text) && self.peek2_text() != "." => {
                        let k = static_str(text);
                        let n = self.tok(k);
                        self.node("predefined_type", vec![n])
                    }
                    "-" => unreachable!(),
                    _ => {
                        // type identifier, possibly nested & generic
                        let mut n = self.named_leaf("type_identifier");
                        while self.at(".") && self.peek2().kind == TK::Ident {
                            self.b.set_kind(n, "identifier");
                            let m = self.field(n, "module");
                            let d = self.tok(".");
                            let p = self.named_leaf("type_identifier");
                            let p = self.field(p, "name");
                            n = self.node("nested_type_identifier", vec![m, d, p]);
                        }
                        if self.at("<") && !self.peek().nl_before {
                            let n = self.field(n, "name");
                            let ta = self.parse_type_arguments();
                            let ta = self.field(ta, "type_arguments");
                            return self.node("generic_type", vec![n, ta]);
                        }
                        n
                    }
                }
            }
            TK::Punct => {
                let text = self.peek_text();
                match text {
                    "{" => self.parse_object_type(),
                    "[" => {
                        let mut ch = vec![self.tok("[")];
                        while !self.eof() && !self.at("]") {
                            let el = if self.at("...") {
                                let d = self.tok("...");
                                let t = self.parse_type();
                                self.node("rest_type", vec![d, t])
                            } else if self.at_ident() && self.peek2_text() == ":" {
                                let n = self.named_leaf("identifier");
                                let c = self.tok(":");
                                let t = self.parse_type();
                                self.node("named_tuple_member", vec![n, c, t])
                            } else if self.at_ident() && self.peek2_text() == "?" {
                                let n = self.named_leaf("identifier");
                                let q = self.tok("?");
                                let c = self.expect(":");
                                let t = self.parse_type();
                                self.node("optional_tuple_member", vec![n, q, c, t]) // approximate
                            } else {
                                let t = self.parse_type();
                                if self.at("?") {
                                    let q = self.tok("?");
                                    self.node("optional_type", vec![t, q])
                                } else {
                                    t
                                }
                            };
                            ch.push(el);
                            if !self.eat_into(",", &mut ch) {
                                break;
                            }
                        }
                        self.expect_into("]", &mut ch);
                        self.node("tuple_type", ch)
                    }
                    "(" => {
                        let l = self.tok("(");
                        let t = self.parse_type();
                        let r = self.expect(")");
                        self.node("parenthesized_type", vec![l, t, r])
                    }
                    "-" => {
                        let m = self.tok("-");
                        let n = self.named_leaf("number");
                        let u = self.node("unary_expression", vec![m, n]);
                        self.node("literal_type", vec![u])
                    }
                    "|" | "&" => {
                        // leading operator
                        let k = static_str(text);
                        let _ = self.tok(k);
                        self.parse_type_operator()
                    }
                    "*" => self.named_leaf("existential_type"),
                    "?" => {
                        let q = self.tok("?");
                        let t = self.parse_type_operator();
                        self.node("flow_maybe_type", vec![q, t])
                    }
                    _ => {
                        let e = self.error_tok();
                        self.node("ERROR", vec![e])
                    }
                }
            }
            _ => {
                let e = self.error_tok();
                self.node("ERROR", vec![e])
            }
        }
    }

    fn parse_object_type(&mut self) -> P {
        let mut ch = vec![self.expect("{")];
        while !self.eof() && !self.at("}") {
            if self.at(",") || self.at(";") {
                let k = if self.at(",") { self.tok(",") } else { self.tok(";") };
                ch.push(k);
                continue;
            }
            let before = self.pos;
            let m = self.parse_type_member();
            ch.push(m);
            if self.pos == before {
                let e = self.error_tok();
                let err = self.node("ERROR", vec![e]);
                ch.push(err);
            }
        }
        self.expect_into("}", &mut ch);
        self.node("object_type", ch)
    }

    fn parse_type_member(&mut self) -> P {
        let mut ch = Vec::new();
        // mapped type: { [K in T]: V }
        if self.at("[") && self.peek2().kind == TK::Ident {
            let save = self.save();
            let l = self.tok("[");
            let n = self.named_leaf("type_identifier");
            if self.at_kw("in") {
                let n = self.field(n, "name");
                let i = self.tok("in");
                let t = self.parse_type();
                let t = self.field(t, "type");
                let mut mch = vec![l, n, i, t];
                if self.at_kw("as") {
                    let a = self.tok("as");
                    let at = self.parse_type();
                    let at = self.field(at, "alias");
                    mch.push(a);
                    mch.push(at);
                }
                let r = self.expect("]");
                mch.push(r);
                let m = self.node("mapped_type_clause", mch.split_off(1));
                let mut ich = vec![l, m, r];
                let _ = &mut ich;
                // Actually tree-sitter: index_signature(mapped_type_clause ...)? approximate
                let mut sig = vec![l, m, r];
                if self.at("?") || self.at("-") || self.at("+") {
                    let k = static_str(self.peek_text());
                    let q = self.tok(k);
                    sig.push(q);
                    if self.at("?") {
                        let q2 = self.tok("?");
                        sig.push(q2);
                    }
                }
                if self.at(":") {
                    let ta = self.parse_type_annotation();
                    let ta = self.field(ta, "type");
                    sig.push(ta);
                }
                return self.node("index_signature", sig);
            }
            self.restore(save);
        }
        // index signature: [key: string]: T
        if self.at("[") && self.peek2().kind == TK::Ident {
            let save = self.save();
            let l = self.tok("[");
            let n = self.named_leaf("identifier");
            if self.at(":") {
                let n = self.field(n, "name");
                let ta = self.parse_type_annotation();
                let ta = self.field(ta, "index_type");
                let r = self.expect("]");
                let mut sig = vec![l, n, ta, r];
                if self.at(":") {
                    let t2 = self.parse_type_annotation();
                    let t2 = self.field(t2, "type");
                    sig.push(t2);
                }
                return self.node("index_signature", sig);
            }
            self.restore(save);
        }
        // modifiers
        loop {
            let text = self.peek_text();
            let t2 = self.peek2();
            let next_is_name = matches!(t2.kind, TK::Ident | TK::Str | TK::Number) || self.peek2_text() == "[";
            if !next_is_name {
                break;
            }
            match text {
                "readonly" | "static" | "abstract" | "override" | "declare" => {
                    let k = static_str(text);
                    let m = self.tok(k);
                    ch.push(m);
                }
                "public" | "private" | "protected" => {
                    let m = self.named_leaf_kw("accessibility_modifier");
                    ch.push(m);
                }
                "get" | "set" => {
                    let k = static_str(text);
                    let m = self.tok(k);
                    ch.push(m);
                }
                _ => break,
            }
        }
        // call signature / construct signature
        if self.at("(") || self.at("<") {
            self.parse_function_rest(&mut ch);
            return self.node("call_signature", ch);
        }
        if self.at_kw("new") && (self.peek2_text() == "(" || self.peek2_text() == "<") {
            let n = self.tok("new");
            ch.push(n);
            self.parse_function_rest(&mut ch);
            return self.node("construct_signature", ch);
        }
        if !self.is_member_name_start() {
            let e = self.error_tok();
            ch.push(e);
            return self.node("ERROR", ch);
        }
        let name = self.parse_property_name();
        let name = self.field(name, "name");
        ch.push(name);
        let optional = self.at("?");
        if optional {
            let q = self.tok("?");
            ch.push(q);
        }
        if self.at("(") || self.at("<") {
            self.parse_function_rest(&mut ch);
            return self.node("method_signature", ch);
        }
        if self.at(":") {
            let ta = self.parse_type_annotation();
            let ta = self.field(ta, "type");
            ch.push(ta);
        }
        self.node("property_signature", ch)
    }

    fn parse_type_alias(&mut self) -> P {
        let k = self.tok("type");
        let n = self.named_leaf("type_identifier");
        let n = self.field(n, "name");
        let mut ch = vec![k, n];
        if self.at("<") {
            let tp = self.parse_type_parameters();
            let tp = self.field(tp, "type_parameters");
            ch.push(tp);
        }
        self.expect_into("=", &mut ch);
        let v = self.parse_type();
        let v = self.field(v, "value");
        ch.push(v);
        self.semi(&mut ch);
        self.node("type_alias_declaration", ch)
    }

    fn parse_interface(&mut self) -> P {
        let k = self.tok("interface");
        let n = self.named_leaf("type_identifier");
        let n = self.field(n, "name");
        let mut ch = vec![k, n];
        if self.at("<") {
            let tp = self.parse_type_parameters();
            let tp = self.field(tp, "type_parameters");
            ch.push(tp);
        }
        if self.at_kw("extends") {
            let e = self.tok("extends");
            let mut ech = vec![e];
            loop {
                let t = self.parse_type();
                let t = self.field(t, "type");
                ech.push(t);
                if !self.eat_into(",", &mut ech) {
                    break;
                }
            }
            let ec = self.node("extends_type_clause", ech);
            ch.push(ec);
        }
        let body = self.parse_object_type();
        self.b.set_kind(body, "interface_body");
        let body = self.field(body, "body");
        ch.push(body);
        self.node("interface_declaration", ch)
    }

    fn parse_enum(&mut self, mut ch: Vec<P>) -> P {
        if self.at_kw("const") {
            let c = self.tok("const");
            ch.push(c);
        }
        let k = self.tok("enum");
        ch.push(k);
        let n = self.named_leaf("identifier");
        let n = self.field(n, "name");
        ch.push(n);
        let mut bch = vec![self.expect("{")];
        while !self.eof() && !self.at("}") {
            let name = self.parse_property_name();
            let name = self.field(name, "name");
            if self.at("=") {
                let eq = self.tok("=");
                let v = self.parse_assignment_expr();
                let v = self.field(v, "value");
                let a = self.node("enum_assignment", vec![name, eq, v]);
                bch.push(a);
            } else {
                bch.push(name);
            }
            if !self.eat_into(",", &mut bch) {
                break;
            }
        }
        self.expect_into("}", &mut bch);
        let body = self.node("enum_body", bch);
        let body = self.field(body, "body");
        ch.push(body);
        self.node("enum_declaration", ch)
    }

    fn parse_ambient(&mut self) -> P {
        let d = self.tok("declare");
        let mut ch = vec![d];
        if self.at_kw("global") {
            let g = self.tok("global");
            ch.push(g);
            let b = self.parse_block();
            ch.push(b);
            return self.node("ambient_declaration", ch);
        }
        if self.at_kw("module") || self.at_kw("namespace") {
            let m = self.parse_module();
            ch.push(m);
            return self.node("ambient_declaration", ch);
        }
        let s = self.parse_statement();
        ch.push(s);
        self.node("ambient_declaration", ch)
    }

    fn parse_module(&mut self) -> P {
        let kw = self.peek_text();
        let is_ns = kw == "namespace";
        let k = static_str(kw);
        let kt = self.tok(k);
        let mut ch = vec![kt];
        if kw != "global" {
            let n = if self.peek().kind == TK::Str {
                self.parse_string()
            } else {
                let mut n = self.named_leaf("identifier");
                while self.at(".") {
                    let o = self.field(n, "object");
                    let d = self.tok(".");
                    let p = self.named_leaf("property_identifier");
                    let p = self.field(p, "property");
                    n = self.node("nested_identifier", vec![o, d, p]);
                }
                n
            };
            let n = self.field(n, "name");
            ch.push(n);
        }
        if self.at("{") {
            let b = self.parse_block();
            let b = self.field(b, "body");
            ch.push(b);
        }
        self.node(if is_ns { "internal_module" } else { "module" }, ch)
    }
}

pub fn parse(src: Rc<str>, lang: Language, dialect: Dialect) -> Tree {
    let mut p = Parser {
        src: &src,
        pos: 0,
        b: TreeBuilder::new(),
        dialect,
        extras: Vec::new(),
        peeked: None,
        in_pattern: false,
        depth: 0,
    };
    let root = p.parse_program();
    // commit any trailing comments
    p.peek();
    p.commit_comments();
    let extras = std::mem::take(&mut p.extras);
    insert_extras(&mut p.b, root, extras);
    let b = p.b;
    b.finish(src, lang, root)
}
