struct Lexer<'s> {
    src: &'s str,
    lang: Language,
}

#[derive(Clone, Copy, PartialEq)]
enum Kind {
    Ident,
    Number,
    Str,
    Comment,
    Punct,
}

impl<'s> Lexer<'s> {
    fn line_comment_prefix(&self) -> &'static [&'static str] {
        use Language::*;
        match self.lang {
            Bash | Python | Ruby | Yaml | Nix | Elixir | Hcl => &["#"],
            Lua | Haskell => &["--"],
            Html | Css | Json => &[],
            _ => &["//"],
        }
    }
    fn block_comment(&self) -> Option<(&'static str, &'static str)> {
        use Language::*;
        match self.lang {
            Bash | Python | Ruby | Yaml | Elixir => None,
            Lua => Some(("--[[", "]]")),
            Haskell => Some(("{-", "-}")),
            Html => Some(("<!--", "-->")),
            Nix => Some(("/*", "*/")),
            _ => Some(("/*", "*/")),
        }
    }
    fn tokens(&self) -> Vec<(Kind, usize, usize)> {
        let src = self.src;
        let bytes = src.as_bytes();
        let mut out = Vec::new();
        let mut i = 0;
        while i < bytes.len() {
            let p = skip_ws(src, i);
            if p != i {
                i = p;
                continue;
            }
            let rest = &src[i..];
            let mut matched = false;
            for pre in self.line_comment_prefix() {
                if rest.starts_with(pre) {
                    let end = rest.find('\n').map(|x| i + x).unwrap_or(bytes.len());
                    out.push((Kind::Comment, i, end));
                    i = end;
                    matched = true;
                    break;
                }
            }
            if matched {
                continue;
            }
            if let Some((open, close)) = self.block_comment() {
                if rest.starts_with(open) {
                    let end = rest[open.len()..].find(close).map(|x| i + open.len() + x + close.len()).unwrap_or(bytes.len());
                    out.push((Kind::Comment, i, end));
                    i = end;
                    continue;
                }
            }
            let c = rest.chars().next().unwrap();
            if is_ident_start(c) {
                let e = ident_end(src, i);
                out.push((Kind::Ident, i, e));
                i = e;
                continue;
            }
            if c.is_ascii_digit() {
                let e = scan_number(src, i);
                out.push((Kind::Number, i, e));
                i = e;
                continue;
            }
            if c == '"' || c == '\'' || c == '`' {
                let e = skip_string(src, i, c as u8, true);
                out.push((Kind::Str, i, e));
                i = e;
                continue;
            }
            // punctuation: longest of a few multi-char operators
            const OPS: &[&str] = &[
                ">>>=", "...", "===", "!==", "**=", "<<=", ">>=", "&&=", "||=", "??=", "::", "->", "=>", "==", "!=", "<=", ">=", "&&",
                "||", "??", "?.", "++", "--", "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", "<<", ">>", "**", ":=", "<-",
            ];
            let mut len = c.len_utf8();
            for op in OPS {
                if rest.starts_with(op) {
                    len = op.len();
                    break;
                }
            }
            out.push((Kind::Punct, i, i + len));
            i += len;
        }
        out
    }
}

pub fn parse(src: Rc<str>, lang: Language) -> Tree {
    let lexer = Lexer { src: &src, lang };
    let toks = lexer.tokens();
    let mut b = TreeBuilder::new();
    let mut stack: Vec<(&'static str, Vec<NodeId>)> = vec![("source_file", Vec::new())];
    let mut extras = Vec::new();
    for (k, s, e) in toks {
        let text = &src[s..e];
        match k {
            Kind::Ident => {
                let id = b.leaf("identifier", true, s, e);
                stack.last_mut().unwrap().1.push(id);
            }
            Kind::Number => {
                let id = b.leaf("number", true, s, e);
                stack.last_mut().unwrap().1.push(id);
            }
            Kind::Str => {
                let id = b.leaf("string", true, s, e);
                stack.last_mut().unwrap().1.push(id);
            }
            Kind::Comment => {
                let id = b.leaf("comment", true, s, e);
                extras.push(id);
            }
            Kind::Punct => match text {
                "(" | "[" | "{" => {
                    let kind = static_tok(text);
                    let open = b.token(kind, s, e);
                    stack.push((kind, vec![open]));
                }
                ")" | "]" | "}" => {
                    let want = match text {
                        ")" => "(",
                        "]" => "[",
                        _ => "{",
                    };
                    let kind = static_tok(text);
                    let close = b.token(kind, s, e);
                    if stack.len() > 1 && stack.last().unwrap().0 == want {
                        let (open, mut ch) = stack.pop().unwrap();
                        ch.push(close);
                        let nk = match open {
                            "(" => "parenthesized",
                            "[" => "bracketed",
                            _ => "block",
                        };
                        let n = b.node(nk, ch);
                        stack.last_mut().unwrap().1.push(n);
                    } else {
                        let err = b.node("ERROR", vec![close]);
                        stack.last_mut().unwrap().1.push(err);
                    }
                }
                _ => {
                    let kind = static_tok(text);
                    let t = b.token(kind, s, e);
                    stack.last_mut().unwrap().1.push(t);
                }
            },
        }
    }
    while stack.len() > 1 {
        let (_, ch) = stack.pop().unwrap();
        let n = b.node("ERROR", ch);
        stack.last_mut().unwrap().1.push(n);
    }
    let (_, ch) = stack.pop().unwrap();
    let start = ch.iter().map(|&c| b.start(c)).min().unwrap_or(0);
    let root = b.node_with_range("source_file", ch, start, src.len());
    crate::tree::insert_extras(&mut b, root, extras);
    b.finish(src, lang, root)
}
