//! JSON parser compatible with tree-sitter-json node kinds.
use super::lexer::*;
use crate::lang::Language;
use crate::tree::{NodeId, Tree, TreeBuilder};
use std::rc::Rc;

struct P<'s> {
    src: &'s str,
    pos: usize,
    b: TreeBuilder,
    extras: Vec<NodeId>,
}

impl<'s> P<'s> {
    fn skip(&mut self) {
        loop {
            self.pos = skip_ws(self.src, self.pos);
            if self.src[self.pos..].starts_with("//") {
                let end = self.src[self.pos..].find('\n').map(|x| self.pos + x).unwrap_or(self.src.len());
                let c = self.b.leaf("comment", true, self.pos, end);
                self.extras.push(c);
                self.pos = end;
            } else if self.src[self.pos..].starts_with("/*") {
                let end = self.src[self.pos + 2..].find("*/").map(|x| self.pos + x + 4).unwrap_or(self.src.len());
                let c = self.b.leaf("comment", true, self.pos, end);
                self.extras.push(c);
                self.pos = end;
            } else {
                break;
            }
        }
    }
    fn peek(&mut self) -> Option<char> {
        self.skip();
        char_at(self.src, self.pos)
    }
    fn tok(&mut self, s: &'static str) -> NodeId {
        self.skip();
        let n = self.b.token(s, self.pos, self.pos + s.len());
        self.pos += s.len();
        n
    }
    fn expect(&mut self, s: &'static str) -> NodeId {
        if self.src[self.pos..].starts_with(s) {
            self.tok(s)
        } else {
            self.b.missing(s, self.pos)
        }
    }
    fn parse_value(&mut self) -> NodeId {
        let c = match self.peek() {
            Some(c) => c,
            None => return self.b.missing("null", self.pos),
        };
        match c {
            '{' => {
                let mut ch = vec![self.tok("{")];
                while let Some(c) = self.peek() {
                    if c == '}' {
                        break;
                    }
                    let before = self.pos;
                    let k = self.parse_value();
                    let k = self.b.set_field(k, "key");
                    let colon = self.expect(":");
                    let v = self.parse_value();
                    let v = self.b.set_field(v, "value");
                    let pair = self.b.node("pair", vec![k, colon, v]);
                    ch.push(pair);
                    if self.peek() == Some(',') {
                        let c = self.tok(",");
                        ch.push(c);
                    } else if self.pos == before {
                        let e = self.error_char();
                        ch.push(e);
                    } else {
                        break;
                    }
                }
                let close = self.expect("}");
                ch.push(close);
                self.b.node("object", ch)
            }
            '[' => {
                let mut ch = vec![self.tok("[")];
                while let Some(c) = self.peek() {
                    if c == ']' {
                        break;
                    }
                    let before = self.pos;
                    let v = self.parse_value();
                    ch.push(v);
                    if self.peek() == Some(',') {
                        let c = self.tok(",");
                        ch.push(c);
                    } else if self.pos == before {
                        let e = self.error_char();
                        ch.push(e);
                    } else {
                        break;
                    }
                }
                let close = self.expect("]");
                ch.push(close);
                self.b.node("array", ch)
            }
            '"' => {
                let start = self.pos;
                let end = skip_string(self.src, start, b'"', false);
                let open = self.b.token("\"", start, start + 1);
                let mut ch = vec![open];
                let closed = end > start + 1 && self.src.as_bytes()[end - 1] == b'"';
                let cend = if closed { end - 1 } else { end };
                if cend > start + 1 {
                    let f = self.b.leaf("string_content", true, start + 1, cend);
                    ch.push(f);
                }
                if closed {
                    let c = self.b.token("\"", end - 1, end);
                    ch.push(c);
                } else {
                    let m = self.b.missing("\"", end);
                    ch.push(m);
                }
                self.pos = end;
                self.b.node_with_range("string", ch, start, end)
            }
            c if c.is_ascii_digit() || c == '-' => {
                let start = self.pos;
                let mut p = start;
                if c == '-' {
                    p += 1;
                }
                let end = scan_number(self.src, p);
                self.pos = end;
                self.b.leaf("number", true, start, end)
            }
            _ => {
                let start = self.pos;
                let end = ident_end(self.src, start);
                if end > start {
                    let word = &self.src[start..end];
                    self.pos = end;
                    let kind = match word {
                        "true" => "true",
                        "false" => "false",
                        "null" => "null",
                        _ => "ERROR",
                    };
                    if kind == "ERROR" {
                        let id = self.b.leaf("identifier", true, start, end);
                        return self.b.node("ERROR", vec![id]);
                    }
                    return self.b.leaf(kind, true, start, end);
                }
                self.error_char()
            }
        }
    }
    fn error_char(&mut self) -> NodeId {
        let start = self.pos;
        let c = char_at(self.src, start).map(|c| c.len_utf8()).unwrap_or(0);
        let k = super::js::static_str(&self.src[start..start + c]);
        let t = self.b.token(k, start, start + c);
        self.pos = start + c;
        self.b.node("ERROR", vec![t])
    }
}

pub fn parse(src: Rc<str>, lang: Language) -> Tree {
    let mut p = P { src: &src, pos: 0, b: TreeBuilder::new(), extras: Vec::new() };
    let mut ch = Vec::new();
    while p.peek().is_some() {
        let before = p.pos;
        let v = p.parse_value();
        ch.push(v);
        if p.pos == before {
            let e = p.error_char();
            ch.push(e);
        }
    }
    let start = ch.iter().map(|&c| p.b.start(c)).min().unwrap_or(0);
    let root = p.b.node_with_range("document", ch, start, src.len());
    let extras = std::mem::take(&mut p.extras);
    crate::tree::insert_extras(&mut p.b, root, extras);
    p.b.finish(src, lang, root)
}
