use crate::tree::Node;
use std::collections::HashMap;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum MetaVariable {
    /// $A (named=true) or $$A (named=false)
    Capture(String, bool),
    /// $_ or $$_ (or $_NAME)
    Dropped(bool),
    /// $$$
    Multiple,
    /// $$$A
    MultiCapture(String),
}

fn is_valid_meta_var_name(s: &str) -> bool {
    !s.is_empty()
        && s.chars().all(|c| c.is_ascii_uppercase() || c.is_ascii_digit() || c == '_')
}

/// Extract a meta variable from text if the whole text is a meta variable.
pub fn extract_meta_var(text: &str, sigil: char) -> Option<MetaVariable> {
    let mut rest = text;
    let mut dollars = 0;
    while let Some(r) = rest.strip_prefix(sigil) {
        rest = r;
        dollars += 1;
        if dollars == 3 {
            break;
        }
    }
    if dollars == 0 {
        return None;
    }
    if dollars == 3 {
        if rest.is_empty() {
            return Some(MetaVariable::Multiple);
        }
        if is_valid_meta_var_name(rest) {
            if rest.starts_with('_') {
                return Some(MetaVariable::Multiple);
            }
            return Some(MetaVariable::MultiCapture(rest.to_string()));
        }
        return None;
    }
    let named = dollars == 1;
    if !is_valid_meta_var_name(rest) {
        return None;
    }
    if rest.starts_with('_') {
        return Some(MetaVariable::Dropped(named));
    }
    Some(MetaVariable::Capture(rest.to_string(), named))
}

#[derive(Clone, Debug, Default)]
pub struct MetaVarEnv<'t> {
    pub single: HashMap<String, Node<'t>>,
    pub multi: HashMap<String, Vec<Node<'t>>>,
    pub transformed: HashMap<String, String>,
    /// insertion order for deterministic output
    pub order: Vec<String>,
}

impl<'t> MetaVarEnv<'t> {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn insert_single(&mut self, name: &str, node: Node<'t>) -> bool {
        if let Some(existing) = self.single.get(name) {
            return existing.text() == node.text();
        }
        self.single.insert(name.to_string(), node);
        self.order.push(name.to_string());
        true
    }

    pub fn insert_multi(&mut self, name: &str, nodes: Vec<Node<'t>>) -> bool {
        if let Some(existing) = self.multi.get(name) {
            if existing.len() != nodes.len() {
                return false;
            }
            return existing.iter().zip(nodes.iter()).all(|(a, b)| a.text() == b.text());
        }
        self.multi.insert(name.to_string(), nodes);
        self.order.push(name.to_string());
        true
    }

    pub fn get_single(&self, name: &str) -> Option<Node<'t>> {
        self.single.get(name).copied()
    }

    pub fn get_multi(&self, name: &str) -> Option<&Vec<Node<'t>>> {
        self.multi.get(name)
    }

    /// Text of a variable: single node text, multi nodes source span, or transformed.
    pub fn get_text(&self, name: &str) -> Option<String> {
        if let Some(n) = self.single.get(name) {
            return Some(n.text().to_string());
        }
        if let Some(t) = self.transformed.get(name) {
            return Some(t.clone());
        }
        if let Some(nodes) = self.multi.get(name) {
            if nodes.is_empty() {
                return Some(String::new());
            }
            let first = nodes.first().unwrap();
            let last = nodes.last().unwrap();
            return Some(first.tree.source[first.start()..last.end()].to_string());
        }
        None
    }

    pub fn is_empty(&self) -> bool {
        self.single.is_empty() && self.multi.is_empty() && self.transformed.is_empty()
    }

    pub fn merge(&mut self, other: &MetaVarEnv<'t>) {
        for (k, v) in &other.single {
            if !self.single.contains_key(k) {
                self.single.insert(k.clone(), *v);
                self.order.push(k.clone());
            }
        }
        for (k, v) in &other.multi {
            if !self.multi.contains_key(k) {
                self.multi.insert(k.clone(), v.clone());
                self.order.push(k.clone());
            }
        }
        for (k, v) in &other.transformed {
            self.transformed.entry(k.clone()).or_insert_with(|| v.clone());
        }
    }
}

/// Split a template string into literal and meta-variable segments.
/// Returns Vec of (literal_text, Option<(var_name, is_multi)>)
#[derive(Debug, Clone)]
pub enum TemplatePart {
    Lit(String),
    Var(String),
}

pub fn split_template(template: &str, sigil: char) -> Vec<TemplatePart> {
    let mut parts = Vec::new();
    let mut lit = String::new();
    let chars: Vec<char> = template.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == sigil {
            // count sigils
            let mut j = i;
            while j < chars.len() && chars[j] == sigil && j - i < 3 {
                j += 1;
            }
            let dollars = j - i;
            // name
            let mut k = j;
            while k < chars.len() && (chars[k].is_ascii_uppercase() || chars[k].is_ascii_digit() || chars[k] == '_') {
                k += 1;
            }
            let name: String = chars[j..k].iter().collect();
            let valid = !name.is_empty() && (dollars == 1 || dollars == 3 || dollars == 2);
            if valid {
                if !lit.is_empty() {
                    parts.push(TemplatePart::Lit(std::mem::take(&mut lit)));
                }
                parts.push(TemplatePart::Var(name));
                i = k;
                continue;
            }
            lit.push(chars[i]);
            i += 1;
            continue;
        }
        lit.push(chars[i]);
        i += 1;
    }
    if !lit.is_empty() {
        parts.push(TemplatePart::Lit(lit));
    }
    parts
}

/// Expand a template with the given environment. Unknown variables are left as-is.
pub fn expand_template(template: &str, env: &MetaVarEnv, sigil: char) -> String {
    let mut out = String::new();
    // we need to re-derive how the var was written to keep it when unknown
    let chars: Vec<char> = template.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == sigil {
            let mut j = i;
            while j < chars.len() && chars[j] == sigil && j - i < 3 {
                j += 1;
            }
            let mut k = j;
            while k < chars.len() && (chars[k].is_ascii_uppercase() || chars[k].is_ascii_digit() || chars[k] == '_') {
                k += 1;
            }
            let name: String = chars[j..k].iter().collect();
            if !name.is_empty() {
                if let Some(t) = env.get_text(&name) {
                    out.push_str(&t);
                    i = k;
                    continue;
                }
            }
            out.push(chars[i]);
            i += 1;
            continue;
        }
        out.push(chars[i]);
        i += 1;
    }
    out
}
