#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub enum Strictness {
    Cst,
    #[default]
    Smart,
    Ast,
    Relaxed,
    Signature,
    Template,
}

impl Strictness {
    pub fn parse(s: &str) -> Option<Strictness> {
        Some(match s {
            "cst" => Strictness::Cst,
            "smart" => Strictness::Smart,
            "ast" => Strictness::Ast,
            "relaxed" => Strictness::Relaxed,
            "signature" => Strictness::Signature,
            "template" => Strictness::Template,
            _ => return None,
        })
    }
}

#[derive(Clone, Debug)]
pub enum PatternNode {
    MetaVar(MetaVariable),
    Terminal { text: String, kind: &'static str, is_named: bool },
    Internal { kind: &'static str, is_named: bool, children: Vec<PatternNode> },
}

impl PatternNode {
    pub fn is_named(&self) -> bool {
        match self {
            PatternNode::MetaVar(_) => true,
            PatternNode::Terminal { is_named, .. } => *is_named,
            PatternNode::Internal { is_named, .. } => *is_named,
        }
    }
    pub fn is_ellipsis(&self) -> bool {
        matches!(self, PatternNode::MetaVar(MetaVariable::Multiple) | PatternNode::MetaVar(MetaVariable::MultiCapture(_)))
    }
    pub fn is_trivial(&self) -> bool {
        matches!(self, PatternNode::Terminal { is_named: false, .. })
    }
    pub fn kind(&self) -> Option<&'static str> {
        match self {
            PatternNode::MetaVar(_) => None,
            PatternNode::Terminal { kind, .. } => Some(kind),
            PatternNode::Internal { kind, .. } => Some(kind),
        }
    }
    fn has_error(&self) -> bool {
        match self {
            PatternNode::MetaVar(_) => false,
            PatternNode::Terminal { kind, .. } => *kind == "ERROR",
            PatternNode::Internal { kind, children, .. } => *kind == "ERROR" || children.iter().any(|c| c.has_error()),
        }
    }
    fn debug_fmt(&self, depth: usize, out: &mut String) {
        for _ in 0..depth {
            out.push_str("  ");
        }
        match self {
            PatternNode::MetaVar(mv) => {
                let s = match mv {
                    MetaVariable::Capture(n, _) => format!("MetaVar ${}", n),
                    MetaVariable::Dropped(_) => "MetaVar $_".to_string(),
                    MetaVariable::Multiple => "MetaVar $$$".to_string(),
                    MetaVariable::MultiCapture(n) => format!("MetaVar $$${}", n),
                };
                out.push_str(&s);
                out.push('\n');
            }
            PatternNode::Terminal { text, kind, is_named } => {
                if *is_named {
                    out.push_str(&format!("{} {}\n", kind, text));
                } else {
                    out.push_str(&format!("{}\n", kind));
                }
            }
            PatternNode::Internal { kind, children, .. } => {
                out.push_str(kind);
                out.push('\n');
                for c in children {
                    c.debug_fmt(depth + 1, out);
                }
            }
        }
    }
}

#[derive(Clone, Debug)]
pub struct Pattern {
    pub node: PatternNode,
    pub strictness: Strictness,
    pub lang: Language,
    pub has_error: bool,
}

#[derive(Debug)]
pub enum PatternError {
    NoContent(String),
    MultipleNode(String),
    NoSelector(String, String),
}

impl fmt::Display for PatternError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            PatternError::NoContent(src) => write!(f, "No AST root is detected. Please check the pattern source `{}`.", src),
            PatternError::MultipleNode(src) => write!(f, "Multiple AST nodes are detected. Please check the pattern source `{}`.", src),
            PatternError::NoSelector(sel, src) => write!(f, "Fails to create Contextual pattern: selector `{}` matches no node in the context `{}`.", sel, src),
        }
    }
}
impl std::error::Error for PatternError {}

fn convert_node(node: Node, sigil: char) -> PatternNode {
    let text = node.text();
    if let Some(mv) = extract_meta_var(text, sigil) {
        return PatternNode::MetaVar(mv);
    }
    if node.is_leaf() {
        return PatternNode::Terminal { text: text.to_string(), kind: node.kind(), is_named: node.is_named() };
    }
    let children = node.children().map(|c| convert_node(c, sigil)).collect();
    PatternNode::Internal { kind: node.kind(), is_named: node.is_named(), children }
}

/// Descend from root while the node has exactly one child.
fn single_child_root<'t>(root: Node<'t>) -> Node<'t> {
    let mut cur = root;
    loop {
        if cur.child_count() == 1 {
            cur = cur.child(0).unwrap();
        } else {
            return cur;
        }
    }
}

pub fn parse_pattern_tree(lang: Language, src: &str) -> Tree {
    crate::parsers::parse(lang, src)
}

impl Pattern {
    pub fn new(src: &str, lang: Language) -> Result<Pattern, PatternError> {
        Pattern::with_strictness(src, lang, Strictness::Smart)
    }

    pub fn with_strictness(src: &str, lang: Language, strictness: Strictness) -> Result<Pattern, PatternError> {
        let tree = parse_pattern_tree(lang, src);
        let root = tree.root();
        if root.child_count() == 0 {
            return Err(PatternError::NoContent(src.to_string()));
        }
        if root.child_count() > 1 {
            return Err(PatternError::MultipleNode(src.to_string()));
        }
        let node = single_child_root(root);
        let pn = convert_node(node, lang.meta_var_char());
        let has_error = pn.has_error();
        Ok(Pattern { node: pn, strictness, lang, has_error })
    }

    pub fn contextual(context: &str, selector: &str, lang: Language, strictness: Strictness) -> Result<Pattern, PatternError> {
        let tree = parse_pattern_tree(lang, context);
        let root = tree.root();
        let found = root.dfs().into_iter().find(|n| n.kind() == selector);
        let Some(node) = found else {
            return Err(PatternError::NoSelector(selector.to_string(), context.to_string()));
        };
        let pn = convert_node(node, lang.meta_var_char());
        let has_error = pn.has_error();
        Ok(Pattern { node: pn, strictness, lang, has_error })
    }

