    pub fn match_node<'t>(&self, node: Node<'t>) -> Option<MetaVarEnv<'t>> {
        let mut env = MetaVarEnv::new();
        if crate::matcher::match_node_impl(&self.node, node, &mut env, self.strictness) {
            Some(env)
        } else {
            None
        }
    }

    pub fn match_node_with_env<'t>(&self, node: Node<'t>, env: &mut MetaVarEnv<'t>) -> bool {
        crate::matcher::match_node_impl(&self.node, node, env, self.strictness)
    }

    /// Kinds this pattern could match (for quick filtering); None if any.
    pub fn root_kind(&self) -> Option<&'static str> {
        self.node.kind()
    }

    pub fn is_meta_var_root(&self) -> bool {
        matches!(self.node, PatternNode::MetaVar(_))
    }

    /// Variables defined in the pattern.
    pub fn defined_vars(&self) -> Vec<String> {
        fn walk(n: &PatternNode, out: &mut Vec<String>) {
            match n {
                PatternNode::MetaVar(MetaVariable::Capture(name, _)) | PatternNode::MetaVar(MetaVariable::MultiCapture(name)) => {
                    if !out.contains(name) {
