use std::fmt;

/// ast-grep style error with message, help, optional link and exit code.
#[derive(Debug)]
pub struct SgError {
    pub message: String,
    pub help: String,
    pub see_also: Option<String>,
    pub causes: Vec<String>,
    pub code: i32,
}

impl fmt::Display for SgError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.message)
    }
}
impl std::error::Error for SgError {}

impl SgError {
    pub fn new(message: impl Into<String>, help: impl Into<String>, see_also: Option<&str>, code: i32) -> SgError {
        SgError {
            message: message.into(),
            help: help.into(),
            see_also: see_also.map(|s| s.to_string()),
            causes: vec![],
            code,
        }
    }
    pub fn cause(mut self, c: impl Into<String>) -> SgError {
        self.causes.push(c.into());
        self
    }
    pub fn causes(mut self, cs: Vec<String>) -> SgError {
        self.causes.extend(cs);
        self
    }
    pub fn render(&self) -> String {
        let mut out = String::new();
        out.push_str(&format!("Error: {}\n", self.message));
        out.push_str(&format!("Help: {}\n", self.help));
        if let Some(url) = &self.see_also {
            out.push_str(&format!("See also: {}\n", url));
        }
        out.push('\n');
        if !self.causes.is_empty() {
            out.push_str("✖ Caused by\n");
            for c in &self.causes {
                out.push_str(&format!("╰▻ {}\n", c));
            }
            out.push('\n');
        }
        out
    }
    pub fn exit(&self) -> ! {
