//! Line based diff with grouping (like difflib / similar) and inline word diff.

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Tag {
    Equal,
    Delete,
    Insert,
    Replace,
}

#[derive(Clone, Copy, Debug)]
pub struct Op {
    pub tag: Tag,
    pub old_index: usize,
    pub old_len: usize,
    pub new_index: usize,
    pub new_len: usize,
}

/// Compute Myers diff ops over slices of comparable items.
pub fn myers_ops<T: PartialEq>(old: &[T], new: &[T]) -> Vec<Op> {
    // Use a simple O(ND) Myers with path recording (fine for typical file sizes).
    let n = old.len();
    let m = new.len();
    // trim common prefix/suffix
    let mut prefix = 0;
    while prefix < n && prefix < m && old[prefix] == new[prefix] {
        prefix += 1;
    }
    let mut suffix = 0;
    while suffix < n - prefix && suffix < m - prefix && old[n - 1 - suffix] == new[m - 1 - suffix] {
        suffix += 1;
    }
    let a = &old[prefix..n - suffix];
    let b = &new[prefix..m - suffix];
    let mut ops = Vec::new();
    if prefix > 0 {
        ops.push(Op { tag: Tag::Equal, old_index: 0, old_len: prefix, new_index: 0, new_len: prefix });
    }
    let mid = diff_core(a, b, prefix, prefix);
    ops.extend(mid);
    if suffix > 0 {
        ops.push(Op { tag: Tag::Equal, old_index: n - suffix, old_len: suffix, new_index: m - suffix, new_len: suffix });
    }
    merge_ops(ops)
}

fn diff_core<T: PartialEq>(a: &[T], b: &[T], off_a: usize, off_b: usize) -> Vec<Op> {
    let n = a.len();
    let m = b.len();
    if n == 0 && m == 0 {
        return vec![];
    }
    if n == 0 {
        return vec![Op { tag: Tag::Insert, old_index: off_a, old_len: 0, new_index: off_b, new_len: m }];
    }
    if m == 0 {
        return vec![Op { tag: Tag::Delete, old_index: off_a, old_len: n, new_index: off_b, new_len: 0 }];
    }
    // LCS via DP for small inputs, else greedy Myers forward with trace
    let max = n + m;
    let offset = max;
    let mut v = vec![0usize; 2 * max + 2];
    let mut trace: Vec<Vec<usize>> = Vec::new();
    let mut found = false;
    for d in 0..=max {
        trace.push(v.clone());
        let mut k = -(d as isize);
        while k <= d as isize {
            let idx = (k + offset as isize) as usize;
            let mut x = if k == -(d as isize) || (k != d as isize && v[idx - 1] < v[idx + 1]) {
                v[idx + 1]
            } else {
                v[idx - 1] + 1
            };
            let mut y = (x as isize - k) as usize;
            while x < n && y < m && a[x] == b[y] {
                x += 1;
                y += 1;
            }
            v[idx] = x;
            if x >= n && y >= m {
                found = true;
                break;
            }
            k += 2;
        }
        if found {
            break;
        }
    }
    // backtrack
    let mut x = n;
    let mut y = m;
    let mut rev: Vec<(Tag, usize, usize)> = Vec::new(); // (tag, x, y) steps
    for d in (0..trace.len()).rev() {
        let v = &trace[d];
        let k = x as isize - y as isize;
        let idx = (k + offset as isize) as usize;
        let prev_k = if k == -(d as isize) || (k != d as isize && v[idx - 1] < v[idx + 1]) { k + 1 } else { k - 1 };
        let prev_idx = (prev_k + offset as isize) as usize;
        let prev_x = if d == 0 { 0 } else { v[prev_idx] };
        let prev_y = (prev_x as isize - prev_k).max(0) as usize;
        while x > prev_x && y > prev_y && d > 0 {
            x -= 1;
            y -= 1;
            rev.push((Tag::Equal, x, y));
        }
        if d > 0 {
            if x == prev_x {
                y -= 1;
                rev.push((Tag::Insert, x, y));
            } else {
                x -= 1;
                rev.push((Tag::Delete, x, y));
            }
        } else {
            while x > 0 && y > 0 {
                x -= 1;
                y -= 1;
                rev.push((Tag::Equal, x, y));
            }
        }
    }
    rev.reverse();
    let mut ops: Vec<Op> = Vec::new();
    for (tag, x, y) in rev {
        let (ol, nl) = match tag {
            Tag::Equal => (1, 1),
            Tag::Delete => (1, 0),
            Tag::Insert => (0, 1),
            Tag::Replace => unreachable!(),
        };
        ops.push(Op { tag, old_index: off_a + x, old_len: ol, new_index: off_b + y, new_len: nl });
    }
    ops
}

/// Merge consecutive ops of same tag and convert delete+insert pairs into Replace.
fn merge_ops(ops: Vec<Op>) -> Vec<Op> {
    let mut merged: Vec<Op> = Vec::new();
    for op in ops {
        if let Some(last) = merged.last_mut() {
            if last.tag == op.tag && last.old_index + last.old_len == op.old_index && last.new_index + last.new_len == op.new_index {
                last.old_len += op.old_len;
                last.new_len += op.new_len;
                continue;
            }
        }
        merged.push(op);
    }
    // combine Delete followed by Insert (or vice versa) into Replace
    let mut out: Vec<Op> = Vec::new();
    let mut i = 0;
    while i < merged.len() {
        let op = merged[i];
        if i + 1 < merged.len() {
            let next = merged[i + 1];
            if (op.tag == Tag::Delete && next.tag == Tag::Insert) || (op.tag == Tag::Insert && next.tag == Tag::Delete) {
                let (del, ins) = if op.tag == Tag::Delete { (op, next) } else { (next, op) };
                out.push(Op { tag: Tag::Replace, old_index: del.old_index, old_len: del.old_len, new_index: ins.new_index, new_len: ins.new_len });
                i += 2;
                continue;
            }
        }
        out.push(op);
        i += 1;
    }
    out
}

/// Group ops like difflib.get_grouped_opcodes with context n.
pub fn group_ops(ops: &[Op], n: usize) -> Vec<Vec<Op>> {
    let mut codes: Vec<Op> = ops.to_vec();
    if codes.is_empty() {
        return vec![];
    }
    if let Some(first) = codes.first_mut() {
        if first.tag == Tag::Equal {
            let i1 = first.old_index;
            let i2 = first.old_index + first.old_len;
            let j1 = first.new_index;
            let j2 = first.new_index + first.new_len;
            let ni1 = i1.max(i2.saturating_sub(n));
            let nj1 = j1.max(j2.saturating_sub(n));
            *first = Op { tag: Tag::Equal, old_index: ni1, old_len: i2 - ni1, new_index: nj1, new_len: j2 - nj1 };
        }
    }
    if let Some(last) = codes.last_mut() {
        if last.tag == Tag::Equal {
            let i1 = last.old_index;
            let i2 = (last.old_index + last.old_len).min(i1 + n);
            let j1 = last.new_index;
            let j2 = (last.new_index + last.new_len).min(j1 + n);
            *last = Op { tag: Tag::Equal, old_index: i1, old_len: i2 - i1, new_index: j1, new_len: j2 - j1 };
        }
    }
    let nn = n + n;
    let mut groups = Vec::new();
    let mut group: Vec<Op> = Vec::new();
    for op in codes {
        let mut op = op;
        if op.tag == Tag::Equal && op.old_len > nn {
            let i1 = op.old_index;
            let i2 = op.old_index + op.old_len;
            let j1 = op.new_index;
            let j2 = op.new_index + op.new_len;
            group.push(Op { tag: Tag::Equal, old_index: i1, old_len: (i2.min(i1 + n)) - i1, new_index: j1, new_len: (j2.min(j1 + n)) - j1 });
            groups.push(std::mem::take(&mut group));
            let ni1 = i1.max(i2 - n);
            let nj1 = j1.max(j2 - n);
            op = Op { tag: Tag::Equal, old_index: ni1, old_len: i2 - ni1, new_index: nj1, new_len: j2 - nj1 };
        }
        group.push(op);
    }
    if !group.is_empty() && !(group.len() == 1 && group[0].tag == Tag::Equal) {
        groups.push(group);
    }
    groups
}

/// Split text into lines keeping line endings.
pub fn split_lines(s: &str) -> Vec<&str> {
    let mut out = Vec::new();
    let mut start = 0;
    for (i, c) in s.char_indices() {
        if c == '\n' {
            out.push(&s[start..=i]);
            start = i + 1;
        }
    }
    if start < s.len() {
        out.push(&s[start..]);
    }
    out
}

/// Tokenize into runs of whitespace / non-whitespace.
pub fn tokenize_words(s: &str) -> Vec<&str> {
    let mut out = Vec::new();
    let mut iter = s.char_indices().peekable();
    while let Some((start, c)) = iter.next() {
        let mut end = start + c.len_utf8();
        while let Some(&(_, nc)) = iter.peek() {
            if nc.is_whitespace() != c.is_whitespace() {
                break;
            }
            iter.next();
            end += nc.len_utf8();
        }
        out.push(&s[start..end]);
    }
    out
}

#[derive(Clone, Debug)]
pub struct InlineLine {
    pub tag: Tag, // Equal / Delete / Insert
    pub old_index: Option<usize>,
    pub new_index: Option<usize>,
    /// (text, emphasized)
    pub segments: Vec<(String, bool)>,
}

/// Expand an op into per-line changes with inline (word) emphasis for replaces.
pub fn inline_changes(op: &Op, old: &[&str], new: &[&str]) -> Vec<InlineLine> {
    let mut out = Vec::new();
    match op.tag {
        Tag::Equal => {
            for i in 0..op.old_len {
                out.push(InlineLine {
                    tag: Tag::Equal,
                    old_index: Some(op.old_index + i),
                    new_index: Some(op.new_index + i),
                    segments: vec![(old[op.old_index + i].to_string(), false)],
                });
            }
        }
        Tag::Delete => {
            for i in 0..op.old_len {
                out.push(InlineLine { tag: Tag::Delete, old_index: Some(op.old_index + i), new_index: None, segments: vec![(old[op.old_index + i].to_string(), false)] });
            }
        }
        Tag::Insert => {
