                            push(&mut new_lines, new_tokens[o.new_index + i], false);
                        }
                    }
                    Tag::Delete => {
                        for i in 0..o.old_len {
                            push(&mut old_lines, old_tokens[o.old_index + i], true);
                        }
                    }
                    Tag::Insert => {
                        for i in 0..o.new_len {
                            push(&mut new_lines, new_tokens[o.new_index + i], true);
                        }
                    }
                    Tag::Replace => {
                        for i in 0..o.old_len {
                            push(&mut old_lines, old_tokens[o.old_index + i], true);
                        }
                        for i in 0..o.new_len {
                            push(&mut new_lines, new_tokens[o.new_index + i], true);
                        }
                    }
                }
            }
            old_lines.retain(|l| !l.is_empty());
            new_lines.retain(|l| !l.is_empty());
            for (i, segs) in old_lines.into_iter().enumerate() {
                out.push(InlineLine { tag: Tag::Delete, old_index: Some(op.old_index + i), new_index: None, segments: segs });
