            y = prev_y;
        }
    }
    rev.reverse();
    let mut ops: Vec<Op> = Vec::new();
    for (tag, x, y) in rev {
        let (ol, nl) = match tag {
            Tag::Equal => (1, 1),
            Tag::Delete => (1, 0),
            Tag::Insert => (0, 1),
            Tag::Replace => unreachable!(),
        };
        ops.push(Op { tag, old_index: off_a + x.max(0) as usize, old_len: ol, new_index: off_b + y.max(0) as usize, new_len: nl });
    }
    ops
}

