use super::{Edit, NodeMatch, Styles};
use crate::diff::{group_ops, inline_changes, myers_ops, split_lines, Tag};
use crate::tree::Tree;
use std::fmt::Write;

pub struct ColoredPrinter {
    pub styles: Styles,
    pub heading: bool,
    pub before: usize,
    pub after: usize,
}

struct Group {
    start_line: usize,
    end_line: usize,
    ranges: Vec<(usize, usize)>,
}

fn merge_groups(matches: &[NodeMatch], tree: &Tree) -> Vec<Group> {
    let mut groups: Vec<Group> = Vec::new();
    let mut sorted: Vec<(usize, usize)> = matches.iter().map(|m| (m.node.start(), m.node.end())).collect();
    sorted.sort_by(|a, b| a.0.cmp(&b.0).then(b.1.cmp(&a.1)));
    for (s, e) in sorted {
        let sl = tree.line_of(s);
        let el = if e > s { tree.line_of(e.saturating_sub(1).max(s)) } else { sl };
        let el = if e > s && tree.source.as_bytes().get(e - 1) == Some(&b'\n') && el > sl { tree.line_of(e - 1) } else { tree.line_of(e.max(s)) };
        let el = el.max(sl);
        if let Some(g) = groups.last_mut() {
            if sl <= g.end_line {
                if el > g.end_line {
                    g.end_line = el;
                }
                let contained = g.ranges.iter().any(|&(rs, re)| rs <= s && e <= re);
                if !contained {
                    g.ranges.push((s, e));
                }
                continue;
            }
        }
        groups.push(Group { start_line: sl, end_line: el, ranges: vec![(s, e)] });
    }
    groups
}

impl ColoredPrinter {
    fn line_text<'a>(&self, tree: &'a Tree, line: usize) -> (&'a str, usize) {
        let start = tree.line_start(line);
        let end = if line + 1 < tree.line_count() { tree.line_start(line + 1) } else { tree.source.len() };
        let mut text = &tree.source[start..end];
        if text.ends_with('\n') {
            text = &text[..text.len() - 1];
        }
        if text.ends_with('\r') {
            text = &text[..text.len() - 1];
        }
        (text, start)
    }

    fn highlighted_line(&self, tree: &Tree, line: usize, ranges: &[(usize, usize)]) -> String {
        let (text, lstart) = self.line_text(tree, line);
        let lend = lstart + text.len();
        let mut out = String::new();
        let mut pos = lstart;
        let mut rs: Vec<(usize, usize)> = ranges.iter().copied().filter(|&(s, e)| s < lend && e > lstart || (s == e && s >= lstart && s <= lend)).collect();
        rs.sort();
        for (s, e) in rs {
            let s = s.max(lstart).min(lend);
            let e = e.min(lend).max(s);
            if s < pos {
                continue;
            }
            out.push_str(&tree.source[pos..s]);
            out.push_str(&self.styles.matched(&tree.source[s..e]));
            pos = e;
        }
        out.push_str(&tree.source[pos..lend]);
        out
    }

    pub fn print_matches(&self, out: &mut String, path: &str, tree: &Tree, matches: &[NodeMatch]) {
        if matches.is_empty() {
            return;
        }
        let groups = merge_groups(matches, tree);
        let total_lines = tree.line_count();
        let last_line_idx = {
            // if source ends with newline, the final empty "line" is not displayable
            if tree.source.ends_with('\n') && total_lines > 1 {
                total_lines - 2
            } else {
                total_lines - 1
            }
        };
        if self.heading {
            let _ = writeln!(out, "{}", self.styles.file(path));
        }
        let mut last_printed: Option<usize> = None;
        for g in &groups {
            let first = g.start_line.saturating_sub(self.before);
            let last = (g.end_line + self.after).min(last_line_idx.max(g.end_line));
            let mut start = first;
            if let Some(lp) = last_printed {
                if first > lp + 1 {
                    if self.before > 0 || self.after > 0 {
                        if self.heading {
                            let _ = writeln!(out, "╴┤");
                        } else {
                            let _ = writeln!(out, "--");
                        }
                    }
                } else {
                    start = lp + 1;
                }
            }
            for line in start..=last {
                if line >= total_lines {
                    break;
                }
                let content = self.highlighted_line(tree, line, &g.ranges);
                if self.heading {
                    let _ = writeln!(out, "{}│{}", self.styles.dim(&(line + 1).to_string()), content);
                } else {
                    let _ = writeln!(out, "{}:{}:{}", path, line + 1, content);
                }
            }
            last_printed = Some(last);
        }
        if self.heading {
            out.push('\n');
        }
    }

    /// Print the diff of applying edits to the file (run --rewrite).
    pub fn print_diffs(&self, out: &mut String, path: &str, source: &str, edits: &[Edit]) {
        if edits.is_empty() {
            return;
        }
        let new_source = super::apply_edits(source, edits);
        let _ = writeln!(out, "{}", self.styles.file(path));
        self.print_unified(out, source, &new_source);
    }

    pub fn print_unified(&self, out: &mut String, old_src: &str, new_src: &str) {
        let old = split_lines(old_src);
        let new = split_lines(new_src);
        let ops = myers_ops(&old, &new);
        for group in group_ops(&ops, 3) {
            let first = group.first().unwrap();
            let last = group.last().unwrap();
            let old_start = first.old_index;
            let old_end = last.old_index + last.old_len;
            let new_start = first.new_index;
            let new_end = last.new_index + last.new_len;
            let header = format!("@@ -{},{} +{},{} @@", old_start, old_end - old_start, new_start, new_end - new_start);
            let _ = writeln!(out, "{}", self.styles.hunk(&header));
            let ow = old_end.to_string().len();
            let nw = new_end.to_string().len();
            for op in &group {
                for change in inline_changes(op, &old, &new) {
                    let old_no = change.old_index.map(|i| (i + 1).to_string()).unwrap_or_default();
                    let new_no = change.new_index.map(|i| (i + 1).to_string()).unwrap_or_default();
                    let old_s = format!("{:<w$}", old_no, w = ow);
                    let new_s = format!("{:<w$}", new_no, w = nw);
                    match change.tag {
                        Tag::Equal => {
                            let _ = write!(out, "{} {}│ ", self.styles.dim(&old_s), self.styles.dim(&new_s));
                            for (seg, _) in &change.segments {
                                out.push_str(seg);
                            }
                            if !change.segments.last().map(|s| s.0.ends_with('\n')).unwrap_or(false) {
                                out.push('\n');
                            }
                        }
                        Tag::Delete => {
                            let _ = write!(out, "{} {}│{}", self.styles.delete(&old_s), self.styles.delete(&new_s), self.styles.delete("-"));
                            for (seg, emph) in &change.segments {
                                if *emph {
                                    out.push_str(&self.styles.delete_emph(seg));
                                } else {
                                    out.push_str(&self.styles.delete(seg));
                                }
                            }
                            if !change.segments.last().map(|s| s.0.ends_with('\n')).unwrap_or(false) {
                                out.push('\n');
                            }
                        }
                        Tag::Insert => {
                            let _ = write!(out, "{} {}│{}", self.styles.insert(&old_s), self.styles.insert(&new_s), self.styles.insert("+"));
                            for (seg, emph) in &change.segments {
                                if *emph {
                                    out.push_str(&self.styles.insert_emph(seg));
                                } else {
                                    out.push_str(&self.styles.insert(seg));
                                }
                            }
                            if !change.segments.last().map(|s| s.0.ends_with('\n')).unwrap_or(false) {
                                out.push('\n');
                            }
                        }
                        Tag::Replace => {}
                    }
                }
            }
        }
    }
}
