}

pub fn match_json(m: &NodeMatch, path: &str, replacement: Option<&(String, usize, usize)>, rule: Option<&RuleInfo>) -> Value {
    let node = m.node;
    let tree = node.tree;
    let (sl, _) = node.start_pos();
    let end_off = if node.end() > node.start() { node.end() - 1 } else { node.end() };
    let el = tree.line_of(end_off.max(node.start()));
    let el = el.max(sl);
    let line_start = tree.line_start(sl);
    let line_end = {
        let e = if el + 1 < tree.line_count() { tree.line_start(el + 1) } else { tree.source.len() };
        let mut t = e;
        if t > line_start && tree.source.as_bytes()[t - 1] == b'\n' {
            t -= 1;
        }
        if t > line_start && tree.source.as_bytes()[t - 1] == b'\r' {
            t -= 1;
        }
        t
    };
    let lines = &tree.source[line_start..line_end.max(line_start)];
    let leading = tree.source[line_start..node.start()].chars().count();
    let trailing = if node.end() <= line_end { tree.source[node.end()..line_end].chars().count() } else { 0 };
    let mut map = Map::new();
    map.insert("text".into(), Value::String(node.text().to_string()));
    map.insert("range".into(), range_json(node));
    map.insert("file".into(), Value::String(path.to_string()));
    map.insert("lines".into(), Value::String(lines.to_string()));
