    if let Some(r) = rule {
        map.insert("ruleId".into(), Value::String(r.id.to_string()));
        map.insert("severity".into(), Value::String(r.severity.to_string()));
        map.insert("note".into(), r.note.map(|n| Value::String(n.to_string())).unwrap_or(Value::Null));
        map.insert("message".into(), Value::String(r.message.to_string()));
        let labels: Vec<Value> = r
            .labels
            .iter()
            .map(|(s, e, style)| {
                json!({
                    "text": &tree.source[*s..*e],
                    "range": range_json_offsets(tree, *s, *e),
                    "style": style,
                })
            })
            .collect();
        map.insert("labels".into(), Value::Array(labels));
        if let Some(md) = &r.metadata {
            map.insert("metadata".into(), md.clone());
        }
    }
    Value::Object(map)
}

pub struct JsonPrinter {
    pub style: JsonStyle,
