}

impl JsonPrinter {
    pub fn new(style: JsonStyle) -> Self {
        JsonPrinter { style, count: 0 }
    }
    pub fn begin(&self, out: &mut String) {
        match self.style {
            JsonStyle::Pretty | JsonStyle::Compact => out.push('['),
            JsonStyle::Stream => {}
        }
    }
    pub fn print(&mut self, out: &mut String, v: &Value) {
        match self.style {
            JsonStyle::Pretty => {
                if self.count > 0 {
                    out.push(',');
                }
                out.push('\n');
                out.push_str(&serde_json::to_string_pretty(v).unwrap());
            }
            JsonStyle::Compact => {
                if self.count > 0 {
                    out.push(',');
                }
                out.push_str(&serde_json::to_string(v).unwrap());
            }
            JsonStyle::Stream => {
                out.push_str(&serde_json::to_string(v).unwrap());
                out.push('\n');
            }
        }
        self.count += 1;
    }
    pub fn end(&self, out: &mut String) {
        match self.style {
            JsonStyle::Pretty => {
                if self.count > 0 {
                    out.push('\n');
                }
                out.push_str("]\n");
            }
            JsonStyle::Compact => out.push_str("]\n"),
            JsonStyle::Stream => {}
        }
    }
}
