//! Minimal re-implementation of codespan-reporting's rich/medium/short renderers.
use crate::tree::Tree;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Severity {
    Error,
    Warning,
    Note,
    Help,
}

impl Severity {
    pub fn name(&self) -> &'static str {
        match self {
            Severity::Error => "error",
            Severity::Warning => "warning",
            Severity::Note => "note",
            Severity::Help => "help",
        }
    }
    fn header_color(&self) -> &'static str {
        match self {
            Severity::Error => "\x1b[0m\x1b[1m\x1b[38;5;9m",
            Severity::Warning => "\x1b[0m\x1b[1m\x1b[38;5;11m",
            Severity::Note => "\x1b[0m\x1b[1m\x1b[38;5;10m",
            Severity::Help => "\x1b[0m\x1b[1m\x1b[38;5;14m",
        }
    }
    fn label_color(&self) -> &'static str {
        match self {
            Severity::Error => "\x1b[0m\x1b[31m",
            Severity::Warning => "\x1b[0m\x1b[33m",
            Severity::Note => "\x1b[0m\x1b[32m",
            Severity::Help => "\x1b[0m\x1b[36m",
        }
    }
}

#[derive(Clone, Debug)]
pub struct Label {
    pub start: usize,
    pub end: usize,
    pub primary: bool,
    pub message: String,
}

pub struct Diagnostic<'a> {
    pub severity: Severity,
    pub code: &'a str,
    pub message: &'a str,
    pub path: &'a str,
    pub labels: Vec<Label>,
    pub notes: Vec<String>,
}

const BORDER: &str = "\x1b[0m\x1b[36m";
const RESET: &str = "\x1b[0m";
const SECONDARY: &str = "\x1b[0m\x1b[34m";

struct W {
    out: String,
    color: bool,
}

impl W {
    fn c(&mut self, color: &str, s: &str) {
        if self.color {
            self.out.push_str(color);
            self.out.push_str(s);
            self.out.push_str(RESET);
        } else {
            self.out.push_str(s);
        }
    }
    fn p(&mut self, s: &str) {
        self.out.push_str(s);
    }
}

fn line_range(tree: &Tree, line: usize) -> (usize, usize) {
    let start = tree.line_start(line);
    let mut end = if line + 1 < tree.line_count() { tree.line_start(line + 1) } else { tree.source.len() };
    if end > start && tree.source.as_bytes()[end - 1] == b'\n' {
        end -= 1;
    }
    if end > start && tree.source.as_bytes()[end - 1] == b'\r' {
        end -= 1;
    }
    (start, end)
}

fn char_col(tree: &Tree, line_start: usize, offset: usize) -> usize {
    tree.source[line_start..offset.max(line_start)].chars().count()
}

pub fn render(d: &Diagnostic, tree: &Tree, style: &str, color: bool) -> String {
    let mut w = W { out: String::new(), color };
    let primary = d.labels.iter().find(|l| l.primary).or(d.labels.first());
    let (pl, pc) = match primary {
        Some(l) => tree.position(l.start),
        None => (0, 0),
    };
    match style {
        "short" | "medium" => {
            w.p(&format!("{}:{}:{}: ", d.path, pl + 1, pc + 1));
            let head = format!("{}[{}]", d.severity.name(), d.code);
            w.c(d.severity.header_color(), &head);
            w.c("\x1b[0m\x1b[1m", &format!(": {}", d.message));
            w.p("\n");
            if style == "medium" {
                for n in &d.notes {
                    w.p(&format!(" = {}\n", n));
                }
            }
            return w.out;
        }
        _ => {}
    }
    // rich
    let head = format!("{}[{}]", d.severity.name(), d.code);
    w.c(d.severity.header_color(), &head);
    w.c("\x1b[0m\x1b[1m", &format!(": {}", d.message));
    w.p("\n");
    if d.labels.is_empty() {
        for n in &d.notes {
            w.p(&format!(" = {}\n", n));
        }
        w.p("\n");
        return w.out;
    }
    // compute lines involved
    struct LabelInfo {
        start_line: usize,
        end_line: usize,
        start: usize,
        end: usize,
        primary: bool,
        message: String,
    }
    let infos: Vec<LabelInfo> = d
        .labels
        .iter()
        .map(|l| {
            let sl = tree.line_of(l.start);
            let end_off = if l.end > l.start { l.end - 1 } else { l.end };
            let el = tree.line_of(end_off).max(sl);
            LabelInfo { start_line: sl, end_line: el, start: l.start, end: l.end, primary: l.primary, message: l.message.clone() }
        })
        .collect();
    let max_line = infos.iter().map(|i| i.end_line).max().unwrap_or(0) + 1;
    let gutter = max_line.to_string().len();
    let pad = " ".repeat(gutter);
    let multi: Vec<&LabelInfo> = infos.iter().filter(|i| i.end_line > i.start_line).collect();
    let multi_count = multi.len();
    let outer = if multi_count > 0 { " ".repeat(multi_count * 2) } else { String::new() };
    // header location
    w.p(&pad);
    w.p(" ");
    w.c(BORDER, "┌─");
    w.p(&format!(" {}:{}:{}\n", d.path, pl + 1, pc + 1));
    w.p(&pad);
    w.p(" ");
    w.c(BORDER, "│");
    if multi_count > 0 {
        w.p(" ");
        w.p(&outer[..outer.len() - 1]);
    }
    w.p("\n");
    // lines to render: all lines from min start to max end that are touched by labels
    let mut lines: Vec<usize> = Vec::new();
    for i in &infos {
        for l in i.start_line..=i.end_line {
            if !lines.contains(&l) {
                lines.push(l);
            }
        }
    }
    lines.sort();
    let mut prev_line: Option<usize> = None;
    for &line in &lines {
        if let Some(p) = prev_line {
            if line > p + 1 {
                // gap
                w.p(&pad);
                w.p(" ");
                w.c(BORDER, "·");
                w.p("\n");
            }
        }
        prev_line = Some(line);
        let (ls, le) = line_range(tree, line);
        let src = &tree.source[ls..le];
        // line number + border
        let num = format!("{:>w$}", line + 1, w = gutter);
        w.c(BORDER, &num);
        w.p(" ");
        w.c(BORDER, "│");
        w.p(" ");
        // multi-line gutter
        let mut multi_marks = String::new();
        for m in &multi {
            let color = if m.primary { d.severity.label_color() } else { SECONDARY };
            if line > m.start_line && line <= m.end_line {
                if color.is_empty() {
                    multi_marks.push('│');
                } else {
                    w.c(color, "│");
                    w.p(" ");
                    continue;
                }
                w.p(" ");
            } else if line == m.start_line {
                // start of multiline label: codespan draws nothing in gutter on start line
                // when the label starts at the beginning? Simplified: blank.
                w.p("  ");
            } else {
                w.p("  ");
            }
        }
        let _ = multi_marks;
        // source with colored label ranges
        let mut pos = ls;
        let mut segs: Vec<(usize, usize, &LabelInfo)> = infos
            .iter()
            .filter(|i| i.start_line <= line && line <= i.end_line)
            .map(|i| (i.start.max(ls), i.end.min(le), i))
            .filter(|(s, e, _)| s <= e)
            .collect();
