}

#[derive(Deserialize, Clone, Debug)]
#[serde(untagged)]
pub enum Transformation {
    Str(String),
    Obj(Trans),
}

/// strip leading sigil(s) from a source var name like `$A`
pub fn var_name(s: &str) -> &str {
    s.trim_start_matches('$')
}

fn split_words(s: &str, seps: &[Separator]) -> Vec<String> {
    let mut words: Vec<String> = Vec::new();
    let mut cur = String::new();
    let chars: Vec<char> = s.chars().collect();
    for (i, &c) in chars.iter().enumerate() {
        let is_sep = (seps.contains(&Separator::Dash) && c == '-')
            || (seps.contains(&Separator::Dot) && c == '.')
            || (seps.contains(&Separator::Slash) && c == '/')
            || (seps.contains(&Separator::Space) && c == ' ')
            || (seps.contains(&Separator::Underscore) && c == '_');
        if is_sep {
            if !cur.is_empty() {
                words.push(std::mem::take(&mut cur));
            }
            continue;
        }
        if seps.contains(&Separator::CaseChange) && !cur.is_empty() {
            let prev = chars[i - 1];
            let next = chars.get(i + 1).copied();
