    let default_seps = vec![Separator::CaseChange, Separator::Dash, Separator::Dot, Separator::Slash, Separator::Space, Separator::Underscore];
    match to {
        StringCase::LowerCase => return text.to_lowercase(),
        StringCase::UpperCase => return text.to_uppercase(),
        StringCase::Capitalize => return capitalize(text),
        _ => {}
    }
    let seps = seps.unwrap_or(&default_seps);
    let words = split_words(text, seps);
    match to {
        StringCase::CamelCase => words
            .iter()
            .enumerate()
            .map(|(i, w)| if i == 0 { w.to_lowercase() } else { capitalize(w) })
            .collect::<Vec<_>>()
