fn parse_str_transform(s: &str) -> Option<Trans> {
    let s = s.trim();
    let open = s.find('(')?;
    let name = &s[..open];
    let inner = s[open + 1..].strip_suffix(')')?;
    let mut parts = inner.split(',').map(|p| p.trim());
    let source = parts.next()?.to_string();
    let mut kv: Vec<(String, String)> = Vec::new();
    for p in parts {
        if let Some((k, v)) = p.split_once('=') {
            kv.push((k.trim().to_string(), v.trim().to_string()));
        }
    }
    let get = |k: &str| kv.iter().find(|(kk, _)| kk == k).map(|(_, v)| v.clone());
    match name {
        "substring" => Some(Trans::Substring(Substring {
            source,
            start_char: get("startChar").and_then(|v| v.parse().ok()),
            end_char: get("endChar").and_then(|v| v.parse().ok()),
        })),
        "replace" => Some(Trans::Replace(Replace { source, replace: get("replace")?, by: get("by")? })),
        "convert" => {
            let to = get("toCase")?;
            let to_case = serde_yaml::from_str::<StringCase>(&to).ok()?;
            let seps = get("separatedBy").map(|v| {
                v.split('|').filter_map(|x| serde_yaml::from_str::<Separator>(x.trim()).ok()).collect::<Vec<_>>()
            });
            Some(Trans::Convert(Convert { source, to_case, separated_by: seps }))
        }
        "rewrite" => Some(Trans::Rewrite(Rewrite {
            source,
            rewriters: get("rewriters").map(|v| v.split('|').map(|x| x.trim().to_string()).collect()).unwrap_or_default(),
            join_by: get("joinBy"),
        })),
        _ => None,
    }
}

pub fn apply_transform<'t>(
    t: &Transformation,
    env: &mut MetaVarEnv<'t>,
    rewrite_fn: &dyn Fn(&Rewrite, &MetaVarEnv<'t>) -> Option<String>,
) -> Option<String> {
    let trans = match t {
        Transformation::Str(s) => parse_str_transform(s)?,
        Transformation::Obj(o) => o.clone(),
    };
    match &trans {
        Trans::Substring(sub) => {
            let text = env.get_text(var_name(&sub.source))?;
            let chars: Vec<char> = text.chars().collect();
            let len = chars.len() as i64;
            let norm = |i: i64| -> usize {
                let v = if i < 0 { len + i } else { i };
                v.clamp(0, len) as usize
            };
            let start = sub.start_char.map(norm).unwrap_or(0);
            let end = sub.end_char.map(norm).unwrap_or(len as usize);
            if start > end {
                return Some(String::new());
            }
            Some(chars[start..end].iter().collect())
        }
        Trans::Replace(rep) => {
            let text = env.get_text(var_name(&rep.source))?;
            let re = regex::Regex::new(&rep.replace).ok()?;
            Some(re.replace_all(&text, rep.by.as_str()).to_string())
        }
        Trans::Convert(conv) => {
            let text = env.get_text(var_name(&conv.source))?;
            Some(convert_case(&text, conv.to_case, conv.separated_by.as_ref()))
        }
        Trans::Rewrite(rw) => rewrite_fn(rw, env),
    }
}
