//! Fix template expansion with indentation handling.
use crate::meta_var::MetaVarEnv;

/// Count leading spaces of the line containing `offset` (spaces only, reset by other chars).
pub fn indent_at_offset(src: &str, offset: usize) -> usize {
    let bytes = src.as_bytes();
    let mut indent = 0;
    let mut i = offset;
    while i > 0 {
        i -= 1;
        let c = bytes[i];
        if c == b'\n' {
            break;
        }
        if c == b' ' {
            indent += 1;
        } else {
            indent = 0;
        }
    }
    indent
}

fn leading_spaces(line: &str) -> usize {
    line.bytes().take_while(|&b| b == b' ').count()
}

/// Re-indent a multi-line text: remove `original` spaces from subsequent lines (if present), add `target`.
fn reindent(text: &str, original: usize, target: usize) -> String {
    if !text.contains('\n') {
        return text.to_string();
    }
    let mut out = String::new();
    for (i, line) in text.split('\n').enumerate() {
        if i > 0 {
            out.push('\n');
            let ls = leading_spaces(line);
            let rest = if ls >= original { &line[original..] } else { line };
            if !rest.is_empty() || true {
                out.push_str(&" ".repeat(target));
            }
            out.push_str(rest);
        } else {
            out.push_str(line);
        }
    }
    out
}

/// Expand template using env, handling indentation. `match_indent` is the indentation
/// of the matched node's line in the source.
pub fn expand_fix(template: &str, env: &MetaVarEnv, sigil: char, match_indent: usize) -> String {
    let mut out = String::new();
    let chars: Vec<char> = template.chars().collect();
    let mut i = 0;
    // track current template line indent
    let mut line_start = 0usize; // index in chars of current line start
    while i < chars.len() {
        if chars[i] == '\n' {
            out.push('\n');
            i += 1;
            line_start = i;
            continue;
        }
        if chars[i] == sigil {
            let mut j = i;
            while j < chars.len() && chars[j] == sigil && j - i < 3 {
                j += 1;
            }
            let mut k = j;
            while k < chars.len() && (chars[k].is_ascii_uppercase() || chars[k].is_ascii_digit() || chars[k] == '_') {
                k += 1;
            }
            let name: String = chars[j..k].iter().collect();
            if !name.is_empty() {
                let found = if let Some(n) = env.single.get(&name) {
                    let text = n.text();
                    let orig = indent_at_offset(&n.tree.source, n.start());
                    Some((text.to_string(), orig))
                } else if let Some(nodes) = env.multi.get(&name) {
                    if nodes.is_empty() {
                        Some((String::new(), 0))
                    } else {
                        let first = nodes.first().unwrap();
                        let last = nodes.last().unwrap();
                        let text = first.tree.source[first.start()..last.end()].to_string();
                        let orig = indent_at_offset(&first.tree.source, first.start());
                        Some((text, orig))
                    }
                } else if let Some(t) = env.transformed.get(&name) {
                    Some((t.clone(), 0))
                } else {
                    None
                };
                if let Some((text, orig)) = found {
                    let tmpl_indent = chars[line_start..].iter().take_while(|&&c| c == ' ').count();
                    out.push_str(&reindent(&text, orig, tmpl_indent));
                    i = k;
                    continue;
                }
            }
            out.push(chars[i]);
            i += 1;
            continue;
        }
        out.push(chars[i]);
        i += 1;
    }
    if match_indent > 0 && out.contains('\n') {
        let mut res = String::new();
        for (i, line) in out.split('\n').enumerate() {
            if i > 0 {
                res.push('\n');
                res.push_str(&" ".repeat(match_indent));
            }
            res.push_str(line);
        }
        return res;
    }
    out
}
