fn parse_pattern_style(p: &PatternStyle, lang: Language, kind_check: &dyn Fn(&str) -> bool) -> Result<Pattern, RuleError> {
    let res = match p {
        PatternStyle::Str(s) => Pattern::new(s, lang),
        PatternStyle::Obj(o) => {
            let strictness = match &o.strictness {
                Some(s) => Strictness::parse(s).ok_or_else(|| RuleError::new(vec!["Rule contains invalid pattern matcher.", "Invalid strictness"]))?,
                None => Strictness::Smart,
            };
            match &o.selector {
                Some(sel) => {
                    if !kind_check(sel) {
                        return Err(RuleError { causes: vec!["Rule contains invalid pattern matcher.".into(), "Invalid Kind".into(), format!("Kind `{}` is invalid.", sel)] });
                    }
                    Pattern::contextual(&o.context, sel, lang, strictness)
                }
                None => Pattern::with_strictness(&o.context, lang, strictness),
            }
        }
    };
    res.map_err(|e| RuleError { causes: vec!["Rule contains invalid pattern matcher.".to_string(), e.to_string()] })
}

fn parse_nth_simple(s: &NthChildSimple) -> Result<(i64, i64), RuleError> {
    match s {
        NthChildSimple::Num(n) => Ok((0, *n)),
        NthChildSimple::Str(st) => {
            let t: String = st.chars().filter(|c| !c.is_whitespace()).collect();
            if let Ok(n) = t.parse::<i64>() {
                return Ok((0, n));
            }
            if let Some(idx) = t.find('n') {
                let a_str = &t[..idx];
                let b_str = &t[idx + 1..];
                let a = match a_str {
                    "" | "+" => 1,
                    "-" => -1,
                    _ => a_str.parse::<i64>().map_err(|_| RuleError::new(vec!["Rule contains invalid nthChild matcher.", "Invalid nth child syntax"]))?,
                };
                let b = if b_str.is_empty() { 0 } else { b_str.parse::<i64>().map_err(|_| RuleError::new(vec!["Rule contains invalid nthChild matcher.", "Invalid nth child syntax"]))? };
                return Ok((a, b));
            }
            Err(RuleError::new(vec!["Rule contains invalid nthChild matcher.", "Invalid nth child syntax"]))
        }
    }
}

pub struct RuleCompiler<'a> {
    pub lang: Language,
    pub kind_check: &'a dyn Fn(&str) -> bool,
}

impl<'a> RuleCompiler<'a> {
    pub fn compile(&self, r: &SerializableRule) -> Result<Rule, RuleError> {
        let mut rules = Vec::new();
        if let Some(p) = &r.pattern {
            rules.push(Rule::Pattern(parse_pattern_style(p, self.lang, self.kind_check)?));
        }
        if let Some(k) = &r.kind {
            if !(self.kind_check)(k) {
                return Err(RuleError { causes: vec!["Rule contains invalid kind matcher.".into(), "Invalid Kind".into(), format!("Kind `{}` is invalid.", k)] });
            }
            rules.push(Rule::Kind(k.clone()));
        }
        if let Some(re) = &r.regex {
            let compiled = Regex::new(re).map_err(|e| RuleError { causes: vec!["Rule contains invalid regex matcher.".into(), "Parsing text matcher fails.".into(), e.to_string()] })?;
            rules.push(Rule::Regex(compiled));
        }
        if let Some(n) = &r.nth_child {
            let (step, offset, of_rule, reverse) = match n {
                SerializableNthChild::Simple(s) => {
                    let (a, b) = parse_nth_simple(s)?;
                    (a, b, None, false)
                }
                SerializableNthChild::Obj(o) => {
                    let (a, b) = parse_nth_simple(&o.position)?;
                    let of = match &o.of_rule {
                        Some(r) => Some(Box::new(self.compile(r)?)),
                        None => None,
                    };
                    (a, b, of, o.reverse)
                }
            };
            rules.push(Rule::NthChild(NthChild { step, offset, of_rule, reverse }));
        }
        if let Some(rg) = &r.range {
            rules.push(Rule::Range(rg.clone()));
        }
        if let Some(rel) = &r.inside {
            rules.push(Rule::Inside(self.compile_relation(rel)?));
        }
        if let Some(rel) = &r.has {
            rules.push(Rule::Has(self.compile_relation(rel)?));
        }
        if let Some(rel) = &r.precedes {
            rules.push(Rule::Precedes(self.compile_relation(rel)?));
        }
        if let Some(rel) = &r.follows {
            rules.push(Rule::Follows(self.compile_relation(rel)?));
        }
        if let Some(all) = &r.all {
            let mut v = Vec::new();
            for sub in all {
                v.push(self.compile(sub)?);
            }
            rules.push(Rule::All(v));
        }
        if let Some(any) = &r.any {
            let mut v = Vec::new();
            for sub in any {
                v.push(self.compile(sub)?);
            }
            rules.push(Rule::Any(v));
        }
        if let Some(not) = &r.not {
            rules.push(Rule::Not(Box::new(self.compile(not)?)));
        }
        if let Some(m) = &r.matches {
            match m {
                SerializableMatches::Id(id) => rules.push(Rule::Matches(id.clone())),
                SerializableMatches::Call(map) => {
                    for (id, _) in map {
                        rules.push(Rule::Matches(id.clone()));
                    }
                }
            }
        }
        if rules.is_empty() {
            return Err(RuleError::new(vec!["Rule must have one positive matcher."]));
        }
        if rules.len() == 1 {
            Ok(rules.pop().unwrap())
        } else {
            Ok(Rule::All(rules))
        }
    }

    fn compile_relation(&self, rel: &Relation) -> Result<Relational, RuleError> {
        let inner = self.compile(&rel.to_rule())?;
        let stop_by = match &rel.stop_by {
            None => StopByKind::Neighbor,
            Some(SerializableStopBy::Str(s)) => match s.as_str() {
                "neighbor" => StopByKind::Neighbor,
                "end" => StopByKind::End,
                _ => return Err(RuleError::new(vec!["Rule contains invalid relational matcher.", "Invalid stopBy"])),
            },
            Some(SerializableStopBy::Rule(r)) => StopByKind::Rule(Box::new(self.compile(r)?)),
        };
        Ok(Relational { rule: Box::new(inner), stop_by, field: rel.field.clone() })
    }
}

impl Rule {
    /// Whether the rule has a "positive" matcher that restricts kinds.
    pub fn potential_kinds(&self) -> Option<Vec<&'static str>> {
        match self {
            Rule::Pattern(p) => {
                if p.is_meta_var_root() {
                    return None;
                }
                let k = p.root_kind()?;
                if k == "ERROR" {
                    return None;
                }
                Some(vec![k])
            }
            Rule::Kind(k) => Some(vec![crate::parsers::js::static_str(k)]),
            Rule::All(rs) => {
                let mut res: Option<Vec<&'static str>> = None;
                for r in rs {
                    if let Some(k) = r.potential_kinds() {
                        res = Some(match res {
                            None => k,
                            Some(prev) => prev.into_iter().filter(|x| k.contains(x)).collect(),
                        });
                    }
                }
                res
            }
            Rule::Any(rs) => {
                let mut res = Vec::new();
                for r in rs {
                    let k = r.potential_kinds()?;
                    for x in k {
                        if !res.contains(&x) {
                            res.push(x);
                        }
                    }
                }
                Some(res)
            }
            Rule::Matches(_) => Some(vec![]), // unknown; treat as present
            _ => None,
        }
    }

    pub fn has_positive(&self, utils: &Utils) -> bool {
        match self {
            Rule::Pattern(p) => !p.is_meta_var_root() && p.root_kind() != Some("ERROR"),
            Rule::Kind(_) => true,
            Rule::All(rs) => rs.iter().any(|r| r.has_positive(utils)),
            Rule::Any(rs) => rs.iter().all(|r| r.has_positive(utils)),
            Rule::Matches(id) => utils.get(id).map(|r| r.has_positive(utils)).unwrap_or(false),
            _ => false,
        }
    }

    pub fn defined_vars(&self) -> Vec<String> {
        let mut out = Vec::new();
        self.collect_vars(&mut out);
        out
    }

    fn collect_vars(&self, out: &mut Vec<String>) {
        match self {
            Rule::Pattern(p) => {
                for v in p.defined_vars() {
                    if !out.contains(&v) {
                        out.push(v);
                    }
                }
            }
            Rule::Inside(r) | Rule::Has(r) | Rule::Precedes(r) | Rule::Follows(r) => r.rule.collect_vars(out),
            Rule::All(rs) | Rule::Any(rs) => rs.iter().for_each(|r| r.collect_vars(out)),
            Rule::Not(r) => r.collect_vars(out),
            _ => {}
        }
    }
}

pub struct MatchContext<'u> {
    pub utils: &'u Utils,
    pub depth: std::cell::Cell<usize>,
}

pub fn match_rule<'t>(rule: &Rule, node: Node<'t>, env: &mut MetaVarEnv<'t>, ctx: &MatchContext) -> bool {
    match rule {
        Rule::Pattern(p) => p.match_node_with_env(node, env),
        Rule::Kind(k) => node.kind() == k,
        Rule::Regex(re) => re.is_match(node.text()),
        Rule::NthChild(n) => match_nth_child(n, node, env, ctx),
        Rule::Range(r) => {
            let (sl, sc) = node.start_pos();
            let (el, ec) = node.end_pos();
            let start_ok = sl > r.start.line || (sl == r.start.line && r.start.column.map(|c| sc >= c).unwrap_or(true));
            let end_ok = el < r.end.line || (el == r.end.line && r.end.column.map(|c| ec <= c).unwrap_or(true));
            start_ok && end_ok
        }
        Rule::Inside(rel) => {
            if let Some(f) = &rel.field {
                let Some(parent) = node.parent() else { return false };
                let Some(child) = parent.child_by_field(f) else { return false };
                if child != node {
                    return false;
                }
            }
            let mut cur = node.parent();
            while let Some(p) = cur {
                let mut trial = env.clone();
                if match_rule(&rel.rule, p, &mut trial, ctx) {
                    *env = trial;
                    return true;
                }
                match &rel.stop_by {
                    StopByKind::Neighbor => return false,
                    StopByKind::End => {}
                    StopByKind::Rule(r) => {
                        let mut t2 = env.clone();
                        if match_rule(r, p, &mut t2, ctx) {
                            return false;
                        }
                    }
                }
                cur = p.parent();
            }
            false
        }
        Rule::Has(rel) => {
            if let Some(f) = &rel.field {
                let Some(child) = node.child_by_field(f) else { return false };
                let mut trial = env.clone();
                if match_rule(&rel.rule, child, &mut trial, ctx) {
                    *env = trial;
                    return true;
                }
                return false;
            }
            match &rel.stop_by {
                StopByKind::Neighbor => {
                    for c in node.children() {
                        let mut trial = env.clone();
                        if match_rule(&rel.rule, c, &mut trial, ctx) {
                            *env = trial;
                            return true;
                        }
                    }
                    false
                }
                StopByKind::End => {
                    for c in node.dfs().into_iter().skip(1) {
                        let mut trial = env.clone();
                        if match_rule(&rel.rule, c, &mut trial, ctx) {
                            *env = trial;
                            return true;
                        }
                    }
                    false
                }
                StopByKind::Rule(stop) => {
                    fn search<'t>(n: Node<'t>, rel: &Relational, stop: &Rule, env: &mut MetaVarEnv<'t>, ctx: &MatchContext) -> bool {
                        for c in n.children() {
                            let mut trial = env.clone();
                            if match_rule(&rel.rule, c, &mut trial, ctx) {
                                *env = trial;
                                return true;
                            }
                            let mut t2 = env.clone();
                            if match_rule(stop, c, &mut t2, ctx) {
                                continue;
                            }
                            if search(c, rel, stop, env, ctx) {
                                return true;
                            }
                        }
                        false
                    }
                    search(node, rel, stop, env, ctx)
                }
            }
        }
        Rule::Precedes(rel) => {
            let mut cur = node.next_sibling();
            while let Some(s) = cur {
                let mut trial = env.clone();
                if match_rule(&rel.rule, s, &mut trial, ctx) {
                    *env = trial;
                    return true;
                }
                match &rel.stop_by {
                    StopByKind::Neighbor => return false,
                    StopByKind::End => {}
                    StopByKind::Rule(r) => {
                        let mut t2 = env.clone();
                        if match_rule(r, s, &mut t2, ctx) {
                            return false;
                        }
                    }
                }
                cur = s.next_sibling();
            }
            false
        }
        Rule::Follows(rel) => {
            let mut cur = node.prev_sibling();
            while let Some(s) = cur {
                let mut trial = env.clone();
                if match_rule(&rel.rule, s, &mut trial, ctx) {
                    *env = trial;
                    return true;
                }
                match &rel.stop_by {
                    StopByKind::Neighbor => return false,
                    StopByKind::End => {}
                    StopByKind::Rule(r) => {
                        let mut t2 = env.clone();
                        if match_rule(r, s, &mut t2, ctx) {
                            return false;
                        }
                    }
                }
                cur = s.prev_sibling();
            }
            false
        }
        Rule::All(rs) => {
            let mut trial = env.clone();
            for r in rs {
                if !match_rule(r, node, &mut trial, ctx) {
                    return false;
                }
            }
            *env = trial;
            true
        }
        Rule::Any(rs) => {
            for r in rs {
                let mut trial = env.clone();
                if match_rule(r, node, &mut trial, ctx) {
                    *env = trial;
                    return true;
                }
            }
            false
        }
        Rule::Not(r) => {
            let mut trial = env.clone();
            !match_rule(r, node, &mut trial, ctx)
        }
        Rule::Matches(id) => {
            let Some(r) = ctx.utils.get(id) else { return false };
            let d = ctx.depth.get();
            if d > 64 {
                return false;
            }
            ctx.depth.set(d + 1);
            let res = match_rule(r, node, env, ctx);
            ctx.depth.set(d);
            res
        }
    }
}

fn match_nth_child<'t>(n: &NthChild, node: Node<'t>, env: &mut MetaVarEnv<'t>, ctx: &MatchContext) -> bool {
    let Some(parent) = node.parent() else { return false };
    let siblings: Vec<Node<'t>> = parent
        .children()
        .filter(|c| c.is_named())
        .filter(|c| match &n.of_rule {
            Some(r) => {
                let mut trial = env.clone();
                match_rule(r, *c, &mut trial, ctx)
            }
            None => true,
        })
        .collect();
    let Some(mut idx) = siblings.iter().position(|c| *c == node) else { return false };
    if n.reverse {
        idx = siblings.len() - 1 - idx;
    }
    let pos = idx as i64 + 1; // 1-based
    if n.step == 0 {
        pos == n.offset
    } else {
        let diff = pos - n.offset;
        diff % n.step == 0 && diff / n.step >= 0
    }
}

