}

#[derive(Debug, Clone)]
pub enum StopByKind {
    Neighbor,
    End,
    Rule(Box<Rule>),
}

#[derive(Debug, Clone)]
pub struct Relational {
    pub rule: Box<Rule>,
    pub stop_by: StopByKind,
    pub field: Option<String>,
}

#[derive(Debug, Clone)]
pub struct NthChild {
    pub step: i64,
    pub offset: i64,
    pub of_rule: Option<Box<Rule>>,
    pub reverse: bool,
}

#[derive(Debug, Clone)]
pub enum Rule {
    Pattern(Pattern),
    Kind(String),
    Regex(Regex),
    NthChild(NthChild),
    Range(SerializableRange),
    Inside(Relational),
    Has(Relational),
    Precedes(Relational),
    Follows(Relational),
    All(Vec<Rule>),
    Any(Vec<Rule>),
    Not(Box<Rule>),
    Matches(String),
}

#[derive(Debug)]
pub struct RuleError {
    pub causes: Vec<String>,
}

impl RuleError {
    fn new(causes: Vec<&str>) -> RuleError {
        RuleError { causes: causes.into_iter().map(|s| s.to_string()).collect() }
    }
}

pub struct Utils {
    pub local: HashMap<String, Rule>,
    pub global: HashMap<String, Rule>,
}

impl Utils {
    pub fn empty() -> Utils {
        Utils { local: HashMap::new(), global: HashMap::new() }
    }
    pub fn get(&self, id: &str) -> Option<&Rule> {
        self.local.get(id).or_else(|| self.global.get(id))
    }
}

fn parse_pattern_style(p: &PatternStyle, lang: Language, kind_check: &dyn Fn(&str) -> bool) -> Result<Pattern, RuleError> {
    let res = match p {
        PatternStyle::Str(s) => Pattern::new(s, lang),
        PatternStyle::Obj(o) => {
            let strictness = match &o.strictness {
                Some(s) => Strictness::parse(s).ok_or_else(|| RuleError::new(vec!["Rule contains invalid pattern matcher.", "Invalid strictness"]))?,
                None => Strictness::Smart,
            };
            match &o.selector {
                Some(sel) => {
                    if !kind_check(sel) {
                        return Err(RuleError { causes: vec!["Rule contains invalid pattern matcher.".into(), "Invalid Kind".into(), format!("Kind `{}` is invalid.", sel)] });
                    }
                    Pattern::contextual(&o.context, sel, lang, strictness)
                }
                None => Pattern::with_strictness(&o.context, lang, strictness),
            }
        }
    };
    res.map_err(|e| RuleError { causes: vec!["Rule contains invalid pattern matcher.".to_string(), e.to_string()] })
}

fn parse_nth_simple(s: &NthChildSimple) -> Result<(i64, i64), RuleError> {
    match s {
        NthChildSimple::Num(n) => Ok((0, *n)),
        NthChildSimple::Str(st) => {
            let t: String = st.chars().filter(|c| !c.is_whitespace()).collect();
            if let Ok(n) = t.parse::<i64>() {
                return Ok((0, n));
            }
            if let Some(idx) = t.find('n') {
                let a_str = &t[..idx];
                let b_str = &t[idx + 1..];
                let a = match a_str {
                    "" | "+" => 1,
                    "-" => -1,
                    _ => a_str.parse::<i64>().map_err(|_| RuleError::new(vec!["Rule contains invalid nthChild matcher.", "Invalid nth child syntax"]))?,
                };
                let b = if b_str.is_empty() { 0 } else { b_str.parse::<i64>().map_err(|_| RuleError::new(vec!["Rule contains invalid nthChild matcher.", "Invalid nth child syntax"]))? };
                return Ok((a, b));
            }
            Err(RuleError::new(vec!["Rule contains invalid nthChild matcher.", "Invalid nth child syntax"]))
        }
    }
}

pub struct RuleCompiler<'a> {
    pub lang: Language,
    pub kind_check: &'a dyn Fn(&str) -> bool,
}

impl<'a> RuleCompiler<'a> {
    pub fn compile(&self, r: &SerializableRule) -> Result<Rule, RuleError> {
        let mut rules = Vec::new();
        if let Some(p) = &r.pattern {
            rules.push(Rule::Pattern(parse_pattern_style(p, self.lang, self.kind_check)?));
        }
        if let Some(k) = &r.kind {
            if !(self.kind_check)(k) {
                return Err(RuleError { causes: vec!["Rule contains invalid kind matcher.".into(), "Invalid Kind".into(), format!("Kind `{}` is invalid.", k)] });
            }
            rules.push(Rule::Kind(k.clone()));
        }
        if let Some(re) = &r.regex {
            let compiled = Regex::new(re).map_err(|e| RuleError { causes: vec!["Rule contains invalid regex matcher.".into(), "Parsing text matcher fails.".into(), e.to_string()] })?;
            rules.push(Rule::Regex(compiled));
        }
        if let Some(n) = &r.nth_child {
            let (step, offset, of_rule, reverse) = match n {
                SerializableNthChild::Simple(s) => {
                    let (a, b) = parse_nth_simple(s)?;
                    (a, b, None, false)
                }
                SerializableNthChild::Obj(o) => {
                    let (a, b) = parse_nth_simple(&o.position)?;
                    let of = match &o.of_rule {
                        Some(r) => Some(Box::new(self.compile(r)?)),
                        None => None,
                    };
                    (a, b, of, o.reverse)
                }
            };
            rules.push(Rule::NthChild(NthChild { step, offset, of_rule, reverse }));
        }
        if let Some(rg) = &r.range {
            rules.push(Rule::Range(rg.clone()));
        }
        if let Some(rel) = &r.inside {
            rules.push(Rule::Inside(self.compile_relation(rel)?));
        }
        if let Some(rel) = &r.has {
            rules.push(Rule::Has(self.compile_relation(rel)?));
        }
        if let Some(rel) = &r.precedes {
            rules.push(Rule::Precedes(self.compile_relation(rel)?));
        }
        if let Some(rel) = &r.follows {
            rules.push(Rule::Follows(self.compile_relation(rel)?));
        }
        if let Some(all) = &r.all {
            let mut v = Vec::new();
            for sub in all {
                v.push(self.compile(sub)?);
            }
            rules.push(Rule::All(v));
        }
        if let Some(any) = &r.any {
            let mut v = Vec::new();
            for sub in any {
                v.push(self.compile(sub)?);
            }
            rules.push(Rule::Any(v));
        }
        if let Some(not) = &r.not {
            rules.push(Rule::Not(Box::new(self.compile(not)?)));
        }
        if let Some(m) = &r.matches {
            match m {
                SerializableMatches::Id(id) => rules.push(Rule::Matches(id.clone())),
                SerializableMatches::Call(map) => {
                    for (id, _) in map {
                        rules.push(Rule::Matches(id.clone()));
                    }
                }
            }
        }
        if rules.is_empty() {
            return Err(RuleError::new(vec!["Rule must have one positive matcher."]));
        }
        if rules.len() == 1 {
            Ok(rules.pop().unwrap())
        } else {
            Ok(Rule::All(rules))
        }
    }

    fn compile_relation(&self, rel: &Relation) -> Result<Relational, RuleError> {
        let inner = self.compile(&rel.to_rule())?;
        let stop_by = match &rel.stop_by {
            None => StopByKind::Neighbor,
            Some(SerializableStopBy::Str(s)) => match s.as_str() {
                "neighbor" => StopByKind::Neighbor,
                "end" => StopByKind::End,
                _ => return Err(RuleError::new(vec!["Rule contains invalid relational matcher.", "Invalid stopBy"])),
            },
            Some(SerializableStopBy::Rule(r)) => StopByKind::Rule(Box::new(self.compile(r)?)),
        };
        Ok(Relational { rule: Box::new(inner), stop_by, field: rel.field.clone() })
    }
}

impl Rule {
    /// Whether the rule has a "positive" matcher that restricts kinds.
    pub fn potential_kinds(&self) -> Option<Vec<&'static str>> {
        match self {
            Rule::Pattern(p) => {
                if p.is_meta_var_root() {
                    return None;
                }
                let k = p.root_kind()?;
                if k == "ERROR" {
                    return None;
                }
                Some(vec![k])
            }
            Rule::Kind(k) => Some(vec![crate::parsers::js::static_str(k)]),
            Rule::All(rs) => {
                let mut res: Option<Vec<&'static str>> = None;
                for r in rs {
                    if let Some(k) = r.potential_kinds() {
                        res = Some(match res {
                            None => k,
                            Some(prev) => prev.into_iter().filter(|x| k.contains(x)).collect(),
                        });
                    }
                }
                res
            }
            Rule::Any(rs) => {
                let mut res = Vec::new();
                for r in rs {
                    let k = r.potential_kinds()?;
                    for x in k {
                        if !res.contains(&x) {
                            res.push(x);
                        }
                    }
                }
                Some(res)
            }
            Rule::Matches(_) => Some(vec![]), // unknown; treat as present
            _ => None,
        }
    }

    pub fn has_positive(&self, utils: &Utils) -> bool {
        match self {
            Rule::Pattern(p) => !p.is_meta_var_root() && p.root_kind() != Some("ERROR"),
            Rule::Kind(_) => true,
            Rule::All(rs) => rs.iter().any(|r| r.has_positive(utils)),
            Rule::Any(rs) => rs.iter().all(|r| r.has_positive(utils)),
            Rule::Matches(id) => utils.get(id).map(|r| r.has_positive(utils)).unwrap_or(false),
            _ => false,
        }
    }

    pub fn defined_vars(&self) -> Vec<String> {
        let mut out = Vec::new();
        self.collect_vars(&mut out);
        out
    }

    fn collect_vars(&self, out: &mut Vec<String>) {
        match self {
            Rule::Pattern(p) => {
                for v in p.defined_vars() {
                    if !out.contains(&v) {
                        out.push(v);
                    }
                }
            }
            Rule::Inside(r) | Rule::Has(r) | Rule::Precedes(r) | Rule::Follows(r) => r.rule.collect_vars(out),
            Rule::All(rs) | Rule::Any(rs) => rs.iter().for_each(|r| r.collect_vars(out)),
            Rule::Not(r) => r.collect_vars(out),
            _ => {}
        }
    }
}

pub struct MatchContext<'u> {
    pub utils: &'u Utils,
    pub depth: std::cell::Cell<usize>,
}

pub fn match_rule<'t>(rule: &Rule, node: Node<'t>, env: &mut MetaVarEnv<'t>, ctx: &MatchContext) -> bool {
    match rule {
        Rule::Pattern(p) => p.match_node_with_env(node, env),
        Rule::Kind(k) => node.kind() == k,
        Rule::Regex(re) => re.is_match(node.text()),
        Rule::NthChild(n) => match_nth_child(n, node, env, ctx),
        Rule::Range(r) => {
            let (sl, sc) = node.start_pos();
            let (el, ec) = node.end_pos();
            let start_ok = sl > r.start.line || (sl == r.start.line && r.start.column.map(|c| sc >= c).unwrap_or(true));
            let end_ok = el < r.end.line || (el == r.end.line && r.end.column.map(|c| ec <= c).unwrap_or(true));
            start_ok && end_ok
        }
        Rule::Inside(rel) => {
            if let Some(f) = &rel.field {
                let Some(parent) = node.parent() else { return false };
                let Some(child) = parent.child_by_field(f) else { return false };
                if child != node {
                    return false;
                }
            }
            let mut cur = node.parent();
            while let Some(p) = cur {
                let mut trial = env.clone();
                if match_rule(&rel.rule, p, &mut trial, ctx) {
                    *env = trial;
                    return true;
                }
                match &rel.stop_by {
                    StopByKind::Neighbor => return false,
                    StopByKind::End => {}
                    StopByKind::Rule(r) => {
                        let mut t2 = env.clone();
                        if match_rule(r, p, &mut t2, ctx) {
                            return false;
                        }
                    }
                }
                cur = p.parent();
            }
            false
        }
        Rule::Has(rel) => {
            if let Some(f) = &rel.field {
                let Some(child) = node.child_by_field(f) else { return false };
                let mut trial = env.clone();
                if match_rule(&rel.rule, child, &mut trial, ctx) {
                    *env = trial;
                    return true;
                }
                return false;
            }
            match &rel.stop_by {
                StopByKind::Neighbor => {
                    for c in node.children() {
                        let mut trial = env.clone();
                        if match_rule(&rel.rule, c, &mut trial, ctx) {
                            *env = trial;
                            return true;
                        }
                    }
                    false
                }
                StopByKind::End => {
                    for c in node.dfs().into_iter().skip(1) {
                        let mut trial = env.clone();
                        if match_rule(&rel.rule, c, &mut trial, ctx) {
                            *env = trial;
                            return true;
                        }
                    }
                    false
                }
                StopByKind::Rule(stop) => {
                    fn search<'t>(n: Node<'t>, rel: &Relational, stop: &Rule, env: &mut MetaVarEnv<'t>, ctx: &MatchContext) -> bool {
                        for c in n.children() {
                            let mut trial = env.clone();
                            if match_rule(&rel.rule, c, &mut trial, ctx) {
                                *env = trial;
                                return true;
                            }
                            let mut t2 = env.clone();
                            if match_rule(stop, c, &mut t2, ctx) {
                                continue;
                            }
                            if search(c, rel, stop, env, ctx) {
                                return true;
                            }
                        }
                        false
                    }
                    search(node, rel, stop, env, ctx)
                }
            }
        }
        Rule::Precedes(rel) => {
            let mut cur = node.next_sibling();
            while let Some(s) = cur {
                let mut trial = env.clone();
                if match_rule(&rel.rule, s, &mut trial, ctx) {
                    *env = trial;
                    return true;
                }
                match &rel.stop_by {
                    StopByKind::Neighbor => return false,
                    StopByKind::End => {}
                    StopByKind::Rule(r) => {
                        let mut t2 = env.clone();
                        if match_rule(r, s, &mut t2, ctx) {
                            return false;
                        }
                    }
                }
                cur = s.next_sibling();
            }
            false
        }
        Rule::Follows(rel) => {
            let mut cur = node.prev_sibling();
            while let Some(s) = cur {
                let mut trial = env.clone();
                if match_rule(&rel.rule, s, &mut trial, ctx) {
                    *env = trial;
                    return true;
                }
                match &rel.stop_by {
                    StopByKind::Neighbor => return false,
                    StopByKind::End => {}
                    StopByKind::Rule(r) => {
                        let mut t2 = env.clone();
                        if match_rule(r, s, &mut t2, ctx) {
                            return false;
                        }
                    }
                }
                cur = s.prev_sibling();
            }
            false
        }
        Rule::All(rs) => {
            let mut trial = env.clone();
            for r in rs {
                if !match_rule(r, node, &mut trial, ctx) {
                    return false;
                }
            }
            *env = trial;
            true
        }
        Rule::Any(rs) => {
            for r in rs {
                let mut trial = env.clone();
                if match_rule(r, node, &mut trial, ctx) {
                    *env = trial;
                    return true;
                }
            }
            false
        }
        Rule::Not(r) => {
            let mut trial = env.clone();
            !match_rule(r, node, &mut trial, ctx)
        }
        Rule::Matches(id) => {
            let Some(r) = ctx.utils.get(id) else { return false };
            let d = ctx.depth.get();
            if d > 64 {
                return false;
            }
            ctx.depth.set(d + 1);
            let res = match_rule(r, node, env, ctx);
            ctx.depth.set(d);
            res
        }
    }
}

fn match_nth_child<'t>(n: &NthChild, node: Node<'t>, env: &mut MetaVarEnv<'t>, ctx: &MatchContext) -> bool {
    let Some(parent) = node.parent() else { return false };
    let siblings: Vec<Node<'t>> = parent
        .children()
        .filter(|c| c.is_named())
        .filter(|c| match &n.of_rule {
            Some(r) => {
                let mut trial = env.clone();
                match_rule(r, *c, &mut trial, ctx)
            }
            None => true,
        })
        .collect();
    let Some(mut idx) = siblings.iter().position(|c| *c == node) else { return false };
    if n.reverse {
        idx = siblings.len() - 1 - idx;
    }
    let pos = idx as i64 + 1; // 1-based
    if n.step == 0 {
        pos == n.offset
    } else {
        let diff = pos - n.offset;
        diff % n.step == 0 && diff / n.step >= 0
    }
}

#[derive(Debug, Clone)]
pub struct Fixer {
    pub template: String,
    pub expand_start: Option<Relational>,
    pub expand_end: Option<Relational>,
    pub title: Option<String>,
}

pub struct RuleConfig {
    pub id: String,
    pub language: Language,
    pub rule: Rule,
    pub constraints: Vec<(String, Rule)>,
    pub utils: Utils,
    pub transform: Vec<(String, Transformation)>,
    pub fixers: Vec<Fixer>,
    pub message: String,
    pub note: Option<String>,
    pub severity: Severity,
    pub labels: Option<HashMap<String, LabelConfig>>,
    pub files: Option<globset::GlobSet>,
    pub ignores: Option<globset::GlobSet>,
    pub url: Option<String>,
    pub metadata: Option<Yaml>,
    pub rewriters: Vec<Rewriter>,
}

pub struct Rewriter {
    pub id: String,
    pub rule: Rule,
    pub constraints: Vec<(String, Rule)>,
    pub transform: Vec<(String, Transformation)>,
    pub fixers: Vec<Fixer>,
}

pub fn language_kind_check(lang: Language) -> Box<dyn Fn(&str) -> bool> {
    match lang {
        Language::JavaScript | Language::TypeScript | Language::Tsx => Box::new(|k: &str| crate::parsers::js::is_known_kind(k)),
        _ => Box::new(|_k: &str| true),
    }
}

fn build_globset(globs: &[RuleFileGlob]) -> Option<globset::GlobSet> {
    let mut b = globset::GlobSetBuilder::new();
    for g in globs {
        match g {
            RuleFileGlob::Str(s) => {
                if let Ok(gl) = globset::GlobBuilder::new(s).literal_separator(false).build() {
                    b.add(gl);
                }
            }
            RuleFileGlob::Obj { glob, case_insensitive } => {
                if let Ok(gl) = globset::GlobBuilder::new(glob).case_insensitive(*case_insensitive).build() {
                    b.add(gl);
                }
            }
        }
    }
    b.build().ok()
}

fn compile_fixer(f: &SerializableFixer, compiler: &RuleCompiler) -> Result<Vec<Fixer>, RuleError> {
    let mk = |template: &str, cfg: Option<&FixConfig>| -> Result<Fixer, RuleError> {
        let (es, ee, title) = match cfg {
            Some(c) => (
                match &c.expand_start {
                    Some(r) => Some(compiler.compile_relation(r)?),
                    None => None,
                },
                match &c.expand_end {
                    Some(r) => Some(compiler.compile_relation(r)?),
                    None => None,
                },
                c.title.clone(),
            ),
            None => (None, None, None),
        };
        Ok(Fixer { template: template.to_string(), expand_start: es, expand_end: ee, title })
    };
    Ok(match f {
        SerializableFixer::Str(s) => vec![mk(s, None)?],
        SerializableFixer::Config(c) => vec![mk(&c.template, Some(c))?],
        SerializableFixer::List(items) => {
            let mut v = Vec::new();
            for it in items {
                v.push(match it {
                    FixItem::Str(s) => mk(s, None)?,
                    FixItem::Config(c) => mk(&c.template, Some(c))?,
                });
            }
            v
        }
    })
}

fn transform_list(m: &Option<serde_yaml::Mapping>) -> Result<Vec<(String, Transformation)>, RuleError> {
    let mut out = Vec::new();
    if let Some(map) = m {
        for (k, v) in map {
            let key = k.as_str().ok_or_else(|| RuleError::new(vec!["Fail to parse yaml as RuleConfig", "transform key must be string"]))?;
            let t: Transformation = serde_yaml::from_value(v.clone()).map_err(|e| RuleError { causes: vec!["Fail to parse yaml as RuleConfig".into(), e.to_string()] })?;
            out.push((key.to_string(), t));
        }
    }
    Ok(out)
}

impl RuleConfig {
    pub fn from_serializable(cfg: SerializableRuleConfig, default_id: Option<String>, global_utils: &HashMap<String, SerializableRule>) -> Result<RuleConfig, RuleError> {
        let id = cfg.id.clone().or(default_id).unwrap_or_default();
        let lang = cfg.language.ok_or_else(|| RuleError::new(vec!["Fail to parse yaml as RuleConfig", "missing field `language`"]))?;
        let kind_check = language_kind_check(lang);
        let compiler = RuleCompiler { lang, kind_check: &*kind_check };
        let rule = compiler.compile(&cfg.rule).map_err(|mut e| {
            let mut causes = vec!["Fail to parse yaml as Rule.".to_string(), "`rule` is not configured correctly.".to_string()];
            causes.append(&mut e.causes);
            RuleError { causes }
        })?;
        let mut utils = Utils::empty();
        if let Some(u) = &cfg.utils {
            let mut keys: Vec<&String> = u.keys().collect();
            keys.sort();
            for k in keys {
                let r = compiler.compile(&u[k]).map_err(|mut e| {
                    let mut causes = vec!["Fail to parse yaml as Rule.".to_string(), "`utils` is not configured correctly.".to_string()];
                    causes.append(&mut e.causes);
                    RuleError { causes }
                })?;
                utils.local.insert(k.clone(), r);
            }
        }
        for (k, v) in global_utils {
            if let Ok(r) = compiler.compile(v) {
                utils.global.insert(k.clone(), r);
            }
        }
        if !rule.has_positive(&utils) {
            return Err(RuleError::new(vec!["Rule must specify a set of AST kinds to match. Try adding `kind` rule."]));
        }
        let mut constraints = Vec::new();
        if let Some(c) = &cfg.constraints {
            let mut keys: Vec<&String> = c.keys().collect();
            keys.sort();
            for k in keys {
                let r = compiler.compile(&c[k]).map_err(|mut e| {
                    let mut causes = vec!["Fail to parse yaml as Rule.".to_string(), "`constraints` is not configured correctly.".to_string()];
                    causes.append(&mut e.causes);
                    RuleError { causes }
                })?;
                constraints.push((k.clone(), r));
            }
        }
        let transform = transform_list(&cfg.transform)?;
        let fixers = match &cfg.fix {
            Some(f) => compile_fixer(f, &compiler)?,
            None => vec![],
        };
        let mut rewriters = Vec::new();
        if let Some(rws) = &cfg.rewriters {
            for rw in rws {
                let rule = compiler.compile(&rw.rule).map_err(|mut e| {
                    let mut causes = vec!["Fail to parse yaml as Rule.".to_string(), "`rewriters` is not configured correctly.".to_string()];
                    causes.append(&mut e.causes);
                    RuleError { causes }
                })?;
                let mut cs = Vec::new();
                if let Some(c) = &rw.constraints {
                    for (k, v) in c {
                        cs.push((k.clone(), compiler.compile(v)?));
                    }
                }
                let fixers = match &rw.fix {
                    Some(f) => compile_fixer(f, &compiler)?,
                    None => vec![],
                };
                rewriters.push(Rewriter { id: rw.id.clone(), rule, constraints: cs, transform: transform_list(&rw.transform)?, fixers });
            }
        }
        Ok(RuleConfig {
            id,
            language: lang,
            rule,
            constraints,
            utils,
            transform,
            fixers,
            message: cfg.message,
            note: cfg.note,
            severity: cfg.severity,
            labels: cfg.labels,
            files: cfg.files.as_ref().and_then(|f| build_globset(f)),
            ignores: cfg.ignores.as_ref().and_then(|f| build_globset(f)),
            url: cfg.url,
            metadata: cfg.metadata,
            rewriters,
        })
    }

    pub fn applies_to(&self, path: &std::path::Path) -> bool {
        if let Some(ig) = &self.ignores {
            if ig.is_match(path) {
                return false;
            }
        }
        if let Some(f) = &self.files {
            if !f.is_match(path) {
                return false;
            }
        }
        true
    }

    /// Match the rule against a node, applying constraints and transforms.
    pub fn match_node<'t>(&self, node: Node<'t>) -> Option<MetaVarEnv<'t>> {
        let mut env = MetaVarEnv::new();
        let ctx = MatchContext { utils: &self.utils, depth: std::cell::Cell::new(0) };
        if !match_rule(&self.rule, node, &mut env, &ctx) {
            return None;
        }
        for (var, rule) in &self.constraints {
            let Some(n) = env.get_single(var) else {
                // multi var constraints: ast-grep checks each? treat as fail if absent
                if env.get_multi(var).is_some() {
                    continue;
                }
                return None;
            };
            let mut trial = env.clone();
            if !match_rule(rule, n, &mut trial, &ctx) {
                return None;
            }
            env = trial;
        }
        self.apply_transforms(&self.transform, &mut env, &self.rewriters);
        Some(env)
    }

    pub fn apply_transforms<'t>(&self, transforms: &[(String, Transformation)], env: &mut MetaVarEnv<'t>, rewriters: &[Rewriter]) {
        for (name, t) in transforms {
            let rewrite_fn = |rw: &crate::transform::Rewrite, env: &MetaVarEnv<'t>| -> Option<String> {
                let src = crate::transform::var_name(&rw.source);
                let nodes: Vec<Node<'t>> = if let Some(n) = env.get_single(src) {
                    vec![n]
                } else if let Some(ns) = env.get_multi(src) {
                    ns.clone()
                } else {
                    return None;
                };
                let selected: Vec<&Rewriter> = rewriters.iter().filter(|r| rw.rewriters.contains(&r.id)).collect();
                let mut pieces = Vec::new();
                for n in &nodes {
                    pieces.push(self.rewrite_node(*n, &selected, rewriters));
                }
                Some(match &rw.join_by {
                    Some(j) => pieces.join(j),
                    None => {
                        // keep original spacing between nodes
                        if nodes.len() <= 1 {
                            pieces.join("")
                        } else {
                            let mut out = String::new();
                            for (i, n) in nodes.iter().enumerate() {
                                if i > 0 {
                                    let prev = nodes[i - 1];
                                    out.push_str(&n.tree.source[prev.end()..n.start()]);
                                }
                                out.push_str(&pieces[i]);
                            }
                            out
                        }
                    }
                })
            };
            if let Some(v) = crate::transform::apply_transform(t, env, &rewrite_fn) {
                env.transformed.insert(name.clone(), v);
            }
        }
    }

    /// Apply rewriters to all descendants of node, returning rewritten text.
    fn rewrite_node<'t>(&self, node: Node<'t>, selected: &[&Rewriter], all: &[Rewriter]) -> String {
        let mut edits: Vec<crate::print::Edit> = Vec::new();
        let ctx = MatchContext { utils: &self.utils, depth: std::cell::Cell::new(0) };
        let mut stack = vec![node];
        while let Some(n) = stack.pop() {
            let mut matched = false;
            for rw in selected {
                let mut env = MetaVarEnv::new();
                if match_rule(&rw.rule, n, &mut env, &ctx) {
                    let mut ok = true;
                    for (var, rule) in &rw.constraints {
                        if let Some(vn) = env.get_single(var) {
                            let mut trial = env.clone();
                            if !match_rule(rule, vn, &mut trial, &ctx) {
                                ok = false;
                                break;
                            }
                            env = trial;
                        }
                    }
                    if !ok {
                        continue;
                    }
                    self.apply_transforms(&rw.transform, &mut env, all);
                    if let Some(f) = rw.fixers.first() {
                        let indent = crate::fix::indent_at_offset(&n.tree.source, n.start());
                        let text = crate::fix::expand_fix(&f.template, &env, self.language.meta_var_char(), indent);
                        edits.push(crate::print::Edit { start: n.start(), end: n.end(), inserted: text });
                        matched = true;
                        break;
                    }
                }
            }
            if !matched {
                let mut ch: Vec<Node<'t>> = n.children().collect();
                ch.reverse();
                stack.extend(ch);
            }
        }
        edits.sort_by_key(|e| e.start);
        let src = &node.tree.source[node.start()..node.end()];
        let mut out = String::new();
        let mut pos = node.start();
        for e in edits {
            if e.start < pos {
                continue;
            }
            out.push_str(&node.tree.source[pos..e.start]);
            out.push_str(&e.inserted);
            pos = e.end;
        }
        out.push_str(&node.tree.source[pos..node.end()]);
        let _ = src;
        out
    }

    /// Compute the fix edit for a match.
    pub fn fix_edit<'t>(&self, node: Node<'t>, env: &MetaVarEnv<'t>) -> Option<crate::print::Edit> {
        let f = self.fixers.first()?;
        let ctx = MatchContext { utils: &self.utils, depth: std::cell::Cell::new(0) };
        let mut start = node.start();
        let mut end = node.end();
        if let Some(es) = &f.expand_start {
            let mut cur = node.prev_sibling();
            while let Some(s) = cur {
                let mut trial = env.clone();
                if match_rule(&es.rule, s, &mut trial, &ctx) {
                    start = s.start();
                    if matches!(es.stop_by, StopByKind::Neighbor) {
                        break;
                    }
                } else if matches!(es.stop_by, StopByKind::Neighbor) {
                    break;
                } else if let StopByKind::Rule(r) = &es.stop_by {
                    let mut t2 = env.clone();
                    if match_rule(r, s, &mut t2, &ctx) {
                        break;
                    }
                }
                cur = s.prev_sibling();
            }
        }
        if let Some(ee) = &f.expand_end {
            let mut cur = node.next_sibling();
            while let Some(s) = cur {
                let mut trial = env.clone();
                if match_rule(&ee.rule, s, &mut trial, &ctx) {
                    end = s.end();
                    if matches!(ee.stop_by, StopByKind::Neighbor) {
                        break;
                    }
                } else if matches!(ee.stop_by, StopByKind::Neighbor) {
                    break;
                } else if let StopByKind::Rule(r) = &ee.stop_by {
                    let mut t2 = env.clone();
                    if match_rule(r, s, &mut t2, &ctx) {
                        break;
                    }
                }
                cur = s.next_sibling();
            }
        }
        let indent = crate::fix::indent_at_offset(&node.tree.source, start);
        let text = crate::fix::expand_fix(&f.template, env, self.language.meta_var_char(), indent);
        Some(crate::print::Edit { start, end, inserted: text })
    }

    /// Find all matches in a tree.
    pub fn find_all<'t>(&self, root: Node<'t>) -> Vec<crate::print::NodeMatch<'t>> {
        let kinds = self.rule.potential_kinds();
        let mut out = Vec::new();
        for n in root.dfs() {
            if let Some(ks) = &kinds {
                if !ks.is_empty() && !ks.contains(&n.kind()) {
                    continue;
                }
            }
            if let Some(env) = self.match_node(n) {
                out.push(crate::print::NodeMatch { node: n, env });
            }
        }
        out
    }
}
