}

fn yaml_docs(text: &str) -> Vec<String> {
    // split on document separators
    let mut docs = Vec::new();
    let mut cur = String::new();
    for line in text.lines() {
        if line.trim_end() == "---" {
            docs.push(std::mem::take(&mut cur));
            continue;
        }
        cur.push_str(line);
        cur.push('\n');
    }
    docs.push(cur);
    docs.into_iter().filter(|d| !d.trim().is_empty()).collect()
}

pub fn parse_rule_text(text: &str, default_id: Option<String>, global_utils: &HashMap<String, SerializableRule>) -> Result<Vec<RuleConfig>, Vec<String>> {
    let mut out = Vec::new();
    for doc in yaml_docs(text) {
        let ser: SerializableRuleConfig = serde_yaml::from_str(&doc).map_err(|e| vec!["Fail to parse yaml as RuleConfig".to_string(), e.to_string()])?;
        let rc = RuleConfig::from_serializable(ser, default_id.clone(), global_utils).map_err(|e| e.causes)?;
        out.push(rc);
    }
    Ok(out)
}

fn walk_yaml_files(dir: &Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    let walker = ignore::WalkBuilder::new(dir).hidden(false).git_ignore(false).require_git(false).sort_by_file_name(|a, b| a.cmp(b)).build();
    for e in walker.flatten() {
        let p = e.path();
        if p.is_file() {
            if let Some(ext) = p.extension().and_then(|e| e.to_str()) {
                if ext == "yml" || ext == "yaml" {
                    out.push(p.to_path_buf());
                }
            }
        }
    }
    out
}

pub fn load_global_utils(project: &Project) -> SgResult<HashMap<String, SerializableRule>> {
    let mut utils = HashMap::new();
    if let Some(dirs) = &project.config.util_dirs {
        for d in dirs {
            let dir = project.dir.join(d);
            for f in walk_yaml_files(&dir) {
                let text = std::fs::read_to_string(&f).map_err(|e| glob_util_error(vec![e.to_string()]))?;
                #[derive(Deserialize)]
                #[serde(rename_all = "camelCase")]
                struct GlobalUtil {
                    id: Option<String>,
                    language: Option<crate::lang::Language>,
                    rule: SerializableRule,
                }
                for doc in yaml_docs(&text) {
                    let u: GlobalUtil = serde_yaml::from_str(&doc).map_err(|e| glob_util_error(vec!["Fail to parse yaml as RuleConfig".into(), e.to_string()]))?;
                    let id = u.id.clone().unwrap_or_else(|| f.file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default());
