                    if let Some(lang) = u.language {
                        let kc = crate::rule::language_kind_check(lang);
                        let compiler = crate::rule::RuleCompiler { lang, kind_check: &*kc };
                        compiler.compile(&u.rule).map_err(|e| {
                            let mut causes = vec!["`rule` is not configured correctly.".to_string()];
                            causes.extend(e.causes);
                            glob_util_error(causes)
                        })?;
                    }
                    utils.insert(id, u.rule);
                }
            }
        }
    }
    Ok(utils)
}

pub struct LoadedRules {
    pub rules: Vec<RuleConfig>,
}

pub fn load_project_rules(project: &Project) -> SgResult<LoadedRules> {
    let global_utils = load_global_utils(project)?;
    let mut rules = Vec::new();
    for d in &project.config.rule_dirs {
        let dir = project.dir.join(d);
        for f in walk_yaml_files(&dir) {
            let text = std::fs::read_to_string(&f).map_err(|e| read_rule_error(&f.display().to_string(), e.to_string()))?;
            let stem = f.file_stem().map(|s| s.to_string_lossy().to_string());
            let rs = parse_rule_text(&text, stem, &global_utils).map_err(|causes| parse_rule_error(&crate::walk::display_path(&f), causes))?;
            rules.extend(rs);
        }
    }
    Ok(LoadedRules { rules })
}

pub fn load_rule_file(path: &str, global_utils: &HashMap<String, SerializableRule>) -> SgResult<Vec<RuleConfig>> {
    let text = std::fs::read_to_string(path).map_err(|e| read_rule_error(path, e.to_string()))?;
    let stem = Path::new(path).file_stem().map(|s| s.to_string_lossy().to_string());
    parse_rule_text(&text, stem, global_utils).map_err(|causes| parse_rule_error(path, causes))
}
