//! `run` command implementation.
use crate::error::*;
use crate::lang::Language;
use crate::pattern::{Pattern, Strictness};
use crate::print::colored::ColoredPrinter;
use crate::print::json::{match_json, JsonPrinter, JsonStyle};
use crate::print::{apply_edits, ColorMode, Edit, NodeMatch, Styles};
use crate::walk::{display_path, walk, LangGlobs, NoIgnore, WalkOptions};
use clap::ArgMatches;
use std::collections::HashMap;
use std::io::{Read, Write};
use std::path::PathBuf;

pub struct RunArgs {
    pub pattern: String,
    pub selector: Option<String>,
    pub rewrite: Option<String>,
    pub lang: Option<Language>,
    pub debug_query: Option<String>,
    pub strictness: Strictness,
    pub config: Option<String>,
    pub paths: Vec<PathBuf>,
    pub follow: bool,
    pub no_ignore: NoIgnore,
    pub stdin: bool,
    pub globs: Vec<String>,
    pub threads: usize,
    pub interactive: bool,
    pub update_all: bool,
    pub files_with_matches: bool,
    pub json: Option<JsonStyle>,
    pub color: ColorMode,
    pub inspect: String,
    pub before: usize,
    pub after: usize,
    pub heading: String,
}

pub fn args_from_matches(m: &ArgMatches, config: Option<String>) -> RunArgs {
    let ctx = *m.get_one::<u16>("context").unwrap_or(&0) as usize;
    let before = *m.get_one::<u16>("before").unwrap_or(&0) as usize;
    let after = *m.get_one::<u16>("after").unwrap_or(&0) as usize;
    RunArgs {
        pattern: m.get_one::<String>("pattern").cloned().unwrap_or_default(),
        selector: m.get_one::<String>("selector").cloned(),
        rewrite: m.get_one::<String>("rewrite").cloned(),
        lang: m.get_one::<Language>("lang").copied(),
        debug_query: m.get_one::<String>("debug_query").cloned(),
        strictness: m.get_one::<String>("strictness").and_then(|s| Strictness::parse(s)).unwrap_or_default(),
        config,
        paths: m.get_many::<String>("paths").map(|v| v.map(PathBuf::from).collect()).unwrap_or_else(|| vec![PathBuf::from(".")]),
        follow: m.get_flag("follow"),
        no_ignore: NoIgnore::from_values(&m.get_many::<String>("no_ignore").map(|v| v.cloned().collect::<Vec<_>>()).unwrap_or_default()),
        stdin: m.get_flag("stdin"),
        globs: m.get_many::<String>("globs").map(|v| v.cloned().collect()).unwrap_or_default(),
        threads: *m.get_one::<usize>("threads").unwrap_or(&0),
        interactive: m.get_flag("interactive"),
        update_all: m.get_flag("update_all"),
        files_with_matches: m.get_flag("files_with_matches"),
        json: m.get_one::<String>("json").map(|s| JsonStyle::parse(s)),
        color: ColorMode::parse(m.get_one::<String>("color").map(|s| s.as_str()).unwrap_or("auto")),
        inspect: m.get_one::<String>("inspect").cloned().unwrap_or_else(|| "nothing".into()),
        before: if ctx > 0 { ctx } else { before },
        after: if ctx > 0 { ctx } else { after },
        heading: m.get_one::<String>("heading").cloned().unwrap_or_else(|| "auto".into()),
    }
}

fn build_pattern(args: &RunArgs, lang: Language) -> Result<Pattern, crate::pattern::PatternError> {
    match &args.selector {
        Some(sel) => Pattern::contextual(&args.pattern, sel, lang, args.strictness),
        None => Pattern::with_strictness(&args.pattern, lang, args.strictness),
    }
}

pub struct Output {
    pub buf: String,
}

pub fn run(args: RunArgs) -> SgResult<i32> {
    let is_tty = crate::print::stdout_is_tty();
    let color = args.color.should_color(is_tty);
    let heading = match args.heading.as_str() {
        "always" => true,
        "never" => false,
        _ => is_tty,
    };
    let styles = Styles { color };
    let printer = ColoredPrinter { styles, heading, before: args.before, after: args.after };
    let mut out = String::new();
    let mut json_printer = args.json.map(JsonPrinter::new);
    let mut pattern_cache: HashMap<Language, Option<Pattern>> = HashMap::new();
    let mut has_match = false;
    let mut pattern_has_error = false;

    // debug query
    if let Some(fmt) = &args.debug_query {
        let lang = args.lang.ok_or_else(stdin_lang_error)?;
        let pat = build_pattern(&args, lang).map_err(|e| pattern_error(e.to_string()))?;
        let mut dbg = String::new();
        match fmt.as_str() {
            "ast" | "cst" => {
                let tree = crate::pattern::parse_pattern_tree(lang, &args.pattern);
                let mut s = String::new();
                tree.root().dump(fmt == "ast", 0, &mut s);
                dbg.push_str(&format!("Debug {}:\n{}\n", if fmt == "ast" { "AST" } else { "CST" }, s));
            }
            "sexp" => {
                let tree = crate::pattern::parse_pattern_tree(lang, &args.pattern);
                dbg.push_str(&format!("Debug Sexp:\n{}\n", tree.root().to_sexp()));
            }
            _ => {
                dbg.push_str(&format!("Debug Pattern:\n{}\n", pat.debug_string()));
            }
        }
        eprint!("{}", dbg);
        pattern_has_error = pat.has_error;
    }

    let project = crate::config::load_project(args.config.as_deref()).ok().flatten();
    let lang_globs = project
        .as_ref()
        .and_then(|p| p.config.language_globs.as_ref())
        .map(LangGlobs::from_map)
        .unwrap_or_default();
    let inspect = args.inspect.as_str();
    if inspect != "nothing" {
        match &project {
            Some(p) => {
                let dir = std::fs::canonicalize(&p.dir).unwrap_or_else(|_| p.dir.clone());
                eprintln!("sg: summary|project: isProject=true,projectDir={}", dir.display());
            }
            None => eprintln!("sg: summary|project: isProject=false"),
        }
    }

    if let Some(jp) = &mut json_printer {
        jp.begin(&mut out);
    }

    let mut scanned = 0usize;
    let mut skipped = 0usize;

    if args.stdin {
        let lang = args.lang.ok_or_else(stdin_lang_error)?;
        let mut src = String::new();
        std::io::stdin().read_to_string(&mut src).ok();
        let pat = build_pattern(&args, lang).map_err(|e| pattern_error(e.to_string()))?;
        pattern_has_error = pat.has_error;
        let tree = crate::parsers::parse(lang, &src);
        let matches = find_matches(&pat, &tree);
        if !matches.is_empty() {
            has_match = true;
            emit(&args, &printer, &mut json_printer, &mut out, "STDIN", &tree, &matches);
        }
    } else {
        // explicit lang: validate pattern early
        if let Some(lang) = args.lang {
            let pat = build_pattern(&args, lang).map_err(|e| pattern_error(e.to_string()))?;
            pattern_has_error = pat.has_error;
            pattern_cache.insert(lang, Some(pat));
        }
        let wr = walk(&WalkOptions { paths: args.paths.clone(), follow: args.follow, no_ignore: args.no_ignore.clone(), globs: args.globs.clone(), threads: args.threads });
        let mut exit_err = false;
        for e in &wr.errors {
            eprintln!("ERROR: {}", e);
            exit_err = true;
        }
        for file in &wr.files {
            scanned += 1;
            let lang = match args.lang {
                Some(l) => {
                    // only files of that language
                    match lang_globs.detect(file) {
                        Some(fl) if fl == l => l,
                        _ => {
                            skipped += 1;
                            continue;
                        }
                    }
                }
                None => match lang_globs.detect(file) {
                    Some(l) => l,
                    None => {
                        continue;
                    }
                },
            };
            let display = display_path(file);
            if inspect == "entity" {
                eprintln!("sg: entity|file|{}: language={}", display, lang.name());
            }
            let pat = pattern_cache.entry(lang).or_insert_with(|| build_pattern(&args, lang).ok());
            let Some(pat) = pat else { continue };
            let Ok(src) = std::fs::read_to_string(file) else { continue };
            let tree = crate::parsers::parse(lang, &src);
            let matches = find_matches(pat, &tree);
            if matches.is_empty() {
                continue;
            }
            has_match = true;
            if args.update_all && args.rewrite.is_some() {
                let edits = compute_edits(&args, lang, &matches);
                let new_src = apply_edits(&src, &edits);
                let _ = std::fs::write(file, new_src);
                continue;
            }
            emit(&args, &printer, &mut json_printer, &mut out, &display, &tree, &matches);
        }
        if inspect != "nothing" {
            eprintln!("sg: summary|file: scannedFileCount={},skippedFileCount={}", scanned, skipped);
        }
        if exit_err && !has_match {
            if let Some(jp) = &mut json_printer {
                jp.end(&mut out);
            }
            print!("{}", out);
            return Ok(1);
        }
    }
    if let Some(jp) = &mut json_printer {
        jp.end(&mut out);
    }
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(out.as_bytes());
    let _ = lock.flush();
    if pattern_has_error {
        eprintln!("Warning: Pattern contains an ERROR node and may cause unexpected results.\nHelp: ast-grep parsed the pattern but it matched nothing in this run. Try using playground to refine the pattern.\nSee also: https://ast-grep.github.io/playground.html\n");
        return Ok(0);
    }
    Ok(if has_match { 0 } else { 1 })
}

pub fn find_matches<'t>(pat: &Pattern, tree: &'t crate::tree::Tree) -> Vec<NodeMatch<'t>> {
    let root = tree.root();
    let kind = if pat.is_meta_var_root() { None } else { pat.root_kind() };
    let mut out = Vec::new();
    for n in root.dfs() {
        if let Some(k) = kind {
            if n.kind() != k && pat.strictness != Strictness::Template {
                continue;
            }
        }
        if let Some(env) = pat.match_node(n) {
            out.push(NodeMatch { node: n, env });
        }
    }
    out
}

fn compute_edits(args: &RunArgs, lang: Language, matches: &[NodeMatch]) -> Vec<Edit> {
    let Some(rw) = &args.rewrite else { return vec![] };
    let mut edits: Vec<Edit> = Vec::new();
    let mut last_end = 0;
    for m in matches {
        if m.node.start() < last_end {
            continue; // nested in previous edit
        }
        let indent = crate::fix::indent_at_offset(&m.node.tree.source, m.node.start());
        let text = crate::fix::expand_fix(rw, &m.env, lang.meta_var_char(), indent);
        edits.push(Edit { start: m.node.start(), end: m.node.end(), inserted: text });
        last_end = m.node.end();
    }
    edits
}

fn emit(args: &RunArgs, printer: &ColoredPrinter, json: &mut Option<JsonPrinter>, out: &mut String, path: &str, tree: &crate::tree::Tree, matches: &[NodeMatch]) {
    if let Some(jp) = json {
        for m in matches {
            let rep = args.rewrite.as_ref().map(|rw| {
                let indent = crate::fix::indent_at_offset(&tree.source, m.node.start());
                let text = crate::fix::expand_fix(rw, &m.env, tree.lang.meta_var_char(), indent);
                (text, m.node.start(), m.node.end())
            });
            let v = match_json(m, path, rep.as_ref(), None);
            jp.print(out, &v);
        }
        return;
    }
    if args.files_with_matches {
        out.push_str(path);
        out.push('\n');
        return;
    }
    if args.rewrite.is_some() {
        let edits = compute_edits(args, tree.lang, matches);
        printer.print_diffs(out, path, &tree.source, &edits);
        return;
    }
    printer.print_matches(out, path, tree, matches);
}
