        let mut i = 0;
        let mut indent_stack: Vec<usize> = vec![0];
        let mut depth = 0i32;
        let mut at_line_start = true;
        let mut last_sig_end = 0usize;
        while i < bytes.len() {
            if at_line_start && depth == 0 {
                // measure indentation
                let mut j = i;
                let mut col = 0;
                while j < bytes.len() && (bytes[j] == b' ' || bytes[j] == b'\t') {
                    col += if bytes[j] == b'\t' { 8 - (col % 8) } else { 1 };
                    j += 1;
                }
                // blank line or comment-only line: skip without indentation change
                if j >= bytes.len() {
                    i = j;
                    break;
                }
                if bytes[j] == b'\n' || bytes[j] == b'\r' {
                    i = j + 1;
                    continue;
                }
                if bytes[j] == b'#' {
                    let end = src[j..].find('\n').map(|x| j + x).unwrap_or(bytes.len());
                    self.comments.push((j, end));
                    i = end;
                    continue;
                }
                if bytes[j] == b'\\' && j + 1 < bytes.len() && bytes[j + 1] == b'\n' {
                    i = j + 2;
                    continue;
                }
                let cur = *indent_stack.last().unwrap();
                if col > cur {
                    indent_stack.push(col);
                    self.toks.push(Tok { kind: TK::Indent, start: j, end: j });
                } else {
                    while col < *indent_stack.last().unwrap() && indent_stack.len() > 1 {
                        indent_stack.pop();
                        self.toks.push(Tok { kind: TK::Dedent, start: last_sig_end, end: last_sig_end });
                    }
                }
                at_line_start = false;
                i = j;
                continue;
            }
            let b = bytes[i];
            match b {
                b' ' | b'\t' | b'\x0c' => {
                    i += 1;
                }
                b'\r' => i += 1,
                b'\n' => {
                    if depth == 0 {
                        // emit NEWLINE if last token isn't already a newline/indent
                        if let Some(last) = self.toks.last() {
                            if last.kind != TK::Newline && last.kind != TK::Indent && last.kind != TK::Dedent {
                                self.toks.push(Tok { kind: TK::Newline, start: last_sig_end, end: last_sig_end });
                            }
                        }
                        at_line_start = true;
                    }
                    i += 1;
                }
                b'\\' if i + 1 < bytes.len() && bytes[i + 1] == b'\n' => {
                    i += 2;
                }
                b'#' => {
                    let end = src[i..].find('\n').map(|x| i + x).unwrap_or(bytes.len());
                    self.comments.push((i, end));
                    i = end;
                }
                _ => {
                    if let Some(prefix) = string_prefix_len(src, i) {
                        let (end, _) = scan_py_string(src, i, prefix);
                        self.toks.push(Tok { kind: TK::Str, start: i, end });
                        last_sig_end = end;
                        i = end;
                        continue;
                    }
                    let c = char_at(src, i).unwrap();
                    if is_ident_start(c) {
                        let e = ident_end(src, i);
                        self.toks.push(Tok { kind: TK::Ident, start: i, end: e });
                        last_sig_end = e;
                        i = e;
                        continue;
                    }
                    if c.is_ascii_digit() || (c == '.' && i + 1 < bytes.len() && bytes[i + 1].is_ascii_digit()) {
                        let mut e = scan_number(src, i);
                        // python complex suffix j handled by scan_number letters
                        if e == i {
                            e = i + 1;
                        }
                        self.toks.push(Tok { kind: TK::Number, start: i, end: e });
                        last_sig_end = e;
                        i = e;
                        continue;
                    }
                    let mut len = c.len_utf8();
                    for p in PUNCTS {
                        if src[i..].starts_with(p) {
                            len = p.len();
                            break;
                        }
                    }
                    match &src[i..i + len] {
                        "(" | "[" | "{" => depth += 1,
                        ")" | "]" | "}" => depth = (depth - 1).max(0),
                        _ => {}
                    }
                    self.toks.push(Tok { kind: TK::Punct, start: i, end: i + len });
                    last_sig_end = i + len;
                    i += len;
                }
            }
        }
        if let Some(last) = self.toks.last() {
            if last.kind != TK::Newline && last.kind != TK::Indent && last.kind != TK::Dedent {
                self.toks.push(Tok { kind: TK::Newline, start: last_sig_end, end: last_sig_end });
            }
        }
        while indent_stack.len() > 1 {
            indent_stack.pop();
            self.toks.push(Tok { kind: TK::Dedent, start: last_sig_end, end: last_sig_end });
        }
        self.toks.push(Tok { kind: TK::Eof, start: bytes.len(), end: bytes.len() });
    }
}

type P = NodeId;

struct Parser<'s> {
    src: &'s str,
    toks: Vec<Tok>,
    pos: usize,
    b: TreeBuilder,
}

impl<'s> Parser<'s> {
    fn peek(&self) -> Tok {
        self.toks[self.pos.min(self.toks.len() - 1)]
    }
    fn peek_at(&self, n: usize) -> Tok {
        self.toks[(self.pos + n).min(self.toks.len() - 1)]
    }
    fn text(&self, t: Tok) -> &'s str {
        &self.src[t.start..t.end]
    }
    fn peek_text(&self) -> &'s str {
        let t = self.peek();
        self.text(t)
    }
    fn advance(&mut self) -> Tok {
        let t = self.peek();
        if self.pos < self.toks.len() - 1 {
            self.pos += 1;
        }
        t
    }
    fn at(&self, s: &str) -> bool {
        let t = self.peek();
        (t.kind == TK::Punct || t.kind == TK::Ident) && self.text(t) == s
    }
    fn at_kw(&self, s: &str) -> bool {
        let t = self.peek();
        t.kind == TK::Ident && self.text(t) == s
    }
    fn tok(&mut self, kind: &'static str) -> P {
        let t = self.advance();
        if t.end == t.start {
            return self.b.missing(kind, t.start);
        }
        self.b.token(kind, t.start, t.end)
    }
    fn expect(&mut self, s: &'static str) -> P {
        if self.at(s) {
            self.tok(s)
        } else {
            let t = self.peek();
            self.b.missing(s, t.start)
        }
    }
    fn eat(&mut self, s: &'static str, ch: &mut Vec<P>) -> bool {
        if self.at(s) {
            let n = self.tok(s);
            ch.push(n);
            true
        } else {
            false
        }
    }
    fn named_leaf(&mut self, kind: &'static str) -> P {
        let t = self.advance();
        self.b.leaf(kind, true, t.start, t.end)
    }
    fn field(&mut self, id: P, f: &'static str) -> P {
        self.b.set_field(id, f)
    }
    fn node(&mut self, kind: &'static str, ch: Vec<P>) -> P {
        self.b.node(kind, ch)
    }
    fn error_tok(&mut self) -> P {
        let t = self.advance();
        if t.end == t.start {
            return self.b.missing("ERROR", t.start);
        }
        match t.kind {
            TK::Ident => self.b.leaf("identifier", true, t.start, t.end),
            TK::Number => self.b.leaf("integer", true, t.start, t.end),
            _ => {
                let k = static_str(self.text(t));
                self.b.token(k, t.start, t.end)
            }
        }
    }
    fn skip_newlines(&mut self) {
        while matches!(self.peek().kind, TK::Newline) {
            self.advance();
        }
    }

    // ---------- module / statements ----------
    fn parse_module(&mut self) -> P {
        let mut ch = Vec::new();
        loop {
            self.skip_newlines();
            let t = self.peek();
            if t.kind == TK::Eof {
                break;
            }
            if t.kind == TK::Indent || t.kind == TK::Dedent {
                // unexpected indent: tree-sitter wraps in ERROR; we just skip
                self.advance();
                continue;
            }
            let before = self.pos;
            self.parse_statement(&mut ch);
            if self.pos == before {
                let e = self.error_tok();
                let err = self.node("ERROR", vec![e]);
                ch.push(err);
            }
        }
        let start = ch.iter().map(|&c| self.b.start(c)).min().unwrap_or(0);
        let end = ch.iter().map(|&c| self.b.end(c)).max().unwrap_or(start);
        self.b.node_with_range("module", ch, start, end)
    }

    /// Parse a block after ':' — either simple statements on the same line or an indented block.
    fn parse_block(&mut self) -> P {
        let mut ch = Vec::new();
        if self.peek().kind == TK::Newline {
            self.advance();
            if self.peek().kind == TK::Indent {
                self.advance();
                loop {
                    self.skip_newlines();
                    let t = self.peek();
                    if t.kind == TK::Dedent {
                        self.advance();
                        break;
                    }
                    if t.kind == TK::Eof {
                        break;
                    }
                    if t.kind == TK::Indent {
                        self.advance();
                        continue;
                    }
                    let before = self.pos;
                    self.parse_statement(&mut ch);
                    if self.pos == before {
                        let e = self.error_tok();
                        let err = self.node("ERROR", vec![e]);
                        ch.push(err);
                    }
                }
            } else {
                let t = self.peek();
                let m = self.b.missing("block", t.start);
                return m;
            }
        } else {
            // simple statements on same line
            self.parse_simple_statements(&mut ch);
        }
        if ch.is_empty() {
            let t = self.peek();
            return self.b.missing("block", t.start);
        }
        self.node("block", ch)
    }

    fn parse_statement(&mut self, out: &mut Vec<P>) {
        let t = self.peek();
        if t.kind == TK::Ident {
            match self.text(t) {
                "if" => {
                    let n = self.parse_if();
                    out.push(n);
                    return;
                }
                "for" => {
                    let n = self.parse_for(vec![]);
                    out.push(n);
                    return;
                }
                "while" => {
                    let n = self.parse_while();
                    out.push(n);
                    return;
                }
                "try" => {
                    let n = self.parse_try();
                    out.push(n);
                    return;
                }
                "with" => {
                    let n = self.parse_with(vec![]);
                    out.push(n);
                    return;
                }
                "def" => {
                    let n = self.parse_def(vec![]);
                    out.push(n);
                    return;
                }
                "class" => {
                    let n = self.parse_class();
                    out.push(n);
                    return;
                }
                "async" => {
                    let t2 = self.peek_at(1);
                    let t2t = self.text(t2);
                    if t2.kind == TK::Ident && matches!(t2t, "def" | "for" | "with") {
                        let a = self.tok("async");
                        let n = match t2t {
                            "def" => self.parse_def(vec![a]),
                            "for" => self.parse_for(vec![a]),
                            _ => self.parse_with(vec![a]),
                        };
                        out.push(n);
                        return;
                    }
                }
                "match" => {
                    // match statement: `match x:` followed by newline+indent
                    if self.looks_like_match_stmt() {
                        let n = self.parse_match();
                        out.push(n);
                        return;
                    }
                }
                _ => {}
            }
        }
        if t.kind == TK::Punct && self.text(t) == "@" {
            let n = self.parse_decorated();
            out.push(n);
            return;
        }
        self.parse_simple_statements(out);
    }

    fn looks_like_match_stmt(&self) -> bool {
        // scan to the end of logical line: must end with ':' then Newline
        let mut i = self.pos + 1;
        let mut depth = 0;
        let mut last_colon = false;
        while i < self.toks.len() {
            let t = self.toks[i];
            match t.kind {
                TK::Newline | TK::Eof => break,
                TK::Punct => {
                    let tx = self.text(t);
                    match tx {
                        "(" | "[" | "{" => depth += 1,
                        ")" | "]" | "}" => depth -= 1,
                        _ => {}
                    }
                    last_colon = tx == ":" && depth == 0;
                    if tx == "=" && depth == 0 {
                        return false;
                    }
                }
                _ => last_colon = false,
            }
            i += 1;
        }
        last_colon && i + 1 < self.toks.len() && self.toks[i + 1].kind == TK::Indent && self.pos + 1 < self.toks.len() && self.toks[self.pos + 1].kind != TK::Newline
    }

    fn parse_simple_statements(&mut self, out: &mut Vec<P>) {
        loop {
            let before = self.pos;
            let s = self.parse_simple_statement();
            out.push(s);
            if self.at(";") {
                let _ = self.advance(); // ';' is dropped by tree-sitter? it's anonymous child of module; keep simple
                if self.peek().kind == TK::Newline || self.peek().kind == TK::Eof {
                    break;
                }
                continue;
            }
            if self.pos == before {
                let e = self.error_tok();
                let err = self.node("ERROR", vec![e]);
                out.push(err);
            }
            break;
        }
        if self.peek().kind == TK::Newline {
            self.advance();
        }
    }

    fn parse_simple_statement(&mut self) -> P {
        let t = self.peek();
        if t.kind == TK::Ident {
            match self.text(t) {
                "pass" => {
                    let k = self.tok("pass");
                    return self.node("pass_statement", vec![k]);
                }
                "break" => {
                    let k = self.tok("break");
                    return self.node("break_statement", vec![k]);
                }
                "continue" => {
                    let k = self.tok("continue");
                    return self.node("continue_statement", vec![k]);
                }
                "return" => {
                    let k = self.tok("return");
                    let mut ch = vec![k];
                    if !self.at_line_end() {
                        let e = self.parse_expressions();
                        ch.push(e);
                    }
                    return self.node("return_statement", ch);
                }
                "raise" => {
                    let k = self.tok("raise");
                    let mut ch = vec![k];
                    if !self.at_line_end() {
                        let e = self.parse_expressions();
                        ch.push(e);
                        if self.at_kw("from") {
                            let f = self.tok("from");
                            ch.push(f);
                            let c = self.parse_expression();
                            let c = self.field(c, "cause");
                            ch.push(c);
                        }
                    }
                    return self.node("raise_statement", ch);
                }
                "assert" => {
                    let k = self.tok("assert");
                    let mut ch = vec![k];
                    let e = self.parse_expression();
                    ch.push(e);
                    while self.eat(",", &mut ch) {
                        let e = self.parse_expression();
                        ch.push(e);
                    }
                    return self.node("assert_statement", ch);
                }
                "del" => {
                    let k = self.tok("del");
                    let e = self.parse_expressions();
                    return self.node("delete_statement", vec![k, e]);
                }
                "global" | "nonlocal" => {
                    let kw = static_str(self.text(t));
                    let k = self.tok(kw);
                    let mut ch = vec![k];
                    loop {
                        let id = self.named_leaf("identifier");
                        ch.push(id);
                        if !self.eat(",", &mut ch) {
                            break;
                        }
                    }
                    return self.node(if kw == "global" { "global_statement" } else { "nonlocal_statement" }, ch);
                }
                "import" => return self.parse_import(),
                "from" => return self.parse_import_from(),
                "type" if self.peek_at(1).kind == TK::Ident && self.peek_at(2).kind == TK::Punct && matches!(self.text(self.peek_at(2)), "=" | "[") => {
                    let k = self.tok("type");
                    let n = self.parse_primary();
                    let n = self.field(n, "name");
                    let mut ch = vec![k, n];
                    self.eat("=", &mut ch);
                    let v = self.parse_type();
                    ch.push(v);
                    return self.node("type_alias_statement", ch);
                }
                _ => {}
            }
        }
        self.parse_expression_statement()
    }

    fn at_line_end(&self) -> bool {
        let t = self.peek();
        matches!(t.kind, TK::Newline | TK::Eof | TK::Dedent) || (t.kind == TK::Punct && self.text(t) == ";")
    }

    fn parse_expression_statement(&mut self) -> P {
        let start_pos = self.pos;
        let first = self.parse_expression_or_assignment();
        if self.pos == start_pos {
            let e = self.error_tok();
            return self.node("ERROR", vec![e]);
        }
        let mut ch = vec![first];
        while self.at(",") {
            let c = self.tok(",");
            ch.push(c);
            if self.at_line_end() {
                break;
            }
            let e = self.parse_expression_or_assignment();
            ch.push(e);
        }
        self.node("expression_statement", ch)
    }

    fn parse_expression_or_assignment(&mut self) -> P {
        if self.at_kw("yield") {
            return self.parse_yield();
        }
        let save = self.save();
        // try assignment target
        let lhs = self.parse_star_expression();
        // tuple targets without parens: a, b = ...
        let t = self.peek();
        if t.kind == TK::Punct {
            let tx = self.text(t);
            if tx == "," {
                // could be pattern_list / expression_list; look ahead for '='
                if self.line_has_assignment() {
                    self.restore(save);
                    let pl = self.parse_pattern_list();
                    return self.parse_assignment_rest(pl);
                }
                return lhs;
            }
            if tx == "=" || tx == ":" {
                return self.parse_assignment_rest(lhs);
            }
            if tx.len() >= 2 && tx.ends_with('=') && tx != "==" && tx != "!=" && tx != "<=" && tx != ">=" {
                let lhs = self.field(lhs, "left");
                let op = static_str(tx);
                let o = self.tok(op);
                let o = self.field(o, "operator");
                let rhs = if self.at_kw("yield") { self.parse_yield() } else { self.parse_expressions() };
                let rhs = self.field(rhs, "right");
                return self.node("augmented_assignment", vec![lhs, o, rhs]);
            }
        }
        lhs
    }

    fn line_has_assignment(&self) -> bool {
        let mut i = self.pos;
        let mut depth = 0;
        while i < self.toks.len() {
            let t = self.toks[i];
            match t.kind {
                TK::Newline | TK::Eof => return false,
                TK::Punct => {
                    let tx = self.text(t);
                    match tx {
                        "(" | "[" | "{" => depth += 1,
                        ")" | "]" | "}" => depth -= 1,
                        "=" if depth == 0 => return true,
                        ";" if depth == 0 => return false,
                        _ => {}
                    }
                }
                _ => {}
            }
            i += 1;
        }
        false
    }

    fn parse_pattern_list(&mut self) -> P {
        let mut ch = Vec::new();
        loop {
            let p = self.parse_star_expression();
            ch.push(p);
            if !self.at(",") {
                break;
            }
            let c = self.tok(",");
            ch.push(c);
            if self.at("=") {
                break;
            }
        }
        if ch.len() == 1 {
            return ch.pop().unwrap();
        }
        self.node("pattern_list", ch)
    }

    fn parse_assignment_rest(&mut self, lhs: P) -> P {
        let lhs = self.field(lhs, "left");
        let mut ch = vec![lhs];
        if self.at(":") {
            let c = self.tok(":");
            ch.push(c);
            let ty = self.parse_type();
            let ty = self.field(ty, "type");
            ch.push(ty);
            if !self.at("=") {
                return self.node("assignment", ch);
            }
        }
        let eq = self.tok("=");
        ch.push(eq);
        let rhs = if self.at_kw("yield") {
            self.parse_yield()
        } else {
            let save = self.save();
            let r = self.parse_star_expression();
            if self.at(",") {
                if self.line_has_assignment() {
                    self.restore(save);
                    let pl = self.parse_pattern_list();
                    self.parse_assignment_rest(pl)
                } else {
                    let mut lch = vec![r];
                    while self.at(",") {
                        let c = self.tok(",");
                        lch.push(c);
                        if self.at_line_end() || self.at(")") {
                            break;
                        }
                        let e = self.parse_star_expression();
                        lch.push(e);
                    }
                    self.node("expression_list", lch)
                }
            } else if self.at("=") {
                self.parse_assignment_rest(r)
            } else {
                r
            }
        };
        let rhs = self.field(rhs, "right");
        ch.push(rhs);
        self.node("assignment", ch)
    }

    fn parse_type(&mut self) -> P {
        let e = self.parse_type_inner();
        self.node("type", vec![e])
    }

    fn parse_type_inner(&mut self) -> P {
        let mut first = self.parse_type_atom();
        while self.at("|") {
            let o = self.tok("|");
            let r = self.parse_type_atom();
            first = self.node("union_type", vec![first, o, r]);
        }
        first
    }

    fn parse_type_atom(&mut self) -> P {
        let save = self.save();
        if self.peek().kind == TK::Ident && !self.at_kw("None") {
            let mut n = self.named_leaf("identifier");
            while self.at(".") && self.peek_at(1).kind == TK::Ident {
                let o = self.field(n, "object");
                let d = self.tok(".");
                let a = self.named_leaf("identifier");
                let a = self.field(a, "attribute");
                n = self.node("attribute", vec![o, d, a]);
            }
            if self.at("[") {
                let l = self.tok("[");
                let mut pch = vec![l];
                while !self.at("]") && self.peek().kind != TK::Eof && self.peek().kind != TK::Newline {
                    let t = self.parse_type();
                    pch.push(t);
                    if !self.eat(",", &mut pch) {
                        break;
                    }
                }
                let r = self.expect("]");
                pch.push(r);
                let tp = self.node("type_parameter", pch);
                return self.node("generic_type", vec![n, tp]);
            }
            if self.at("(") || self.at(",") || self.at("=") || self.at(")") || self.at("|") || self.at(":") || self.at_line_end() {
                return n;
            }
            self.restore(save);
        }
        self.parse_expression()
    }

    // ---------- compound statements ----------
    fn parse_if(&mut self) -> P {
        let k = self.tok("if");
        let c = self.parse_expression();
        let c = self.field(c, "condition");
        let colon = self.expect(":");
        let body = self.parse_block();
        let body = self.field(body, "consequence");
        let mut ch = vec![k, c, colon, body];
        loop {
            self.skip_newlines_if_followed_by(&["elif", "else"]);
            if self.at_kw("elif") {
                let e = self.tok("elif");
                let c = self.parse_expression();
                let c = self.field(c, "condition");
                let colon = self.expect(":");
                let b = self.parse_block();
                let b = self.field(b, "consequence");
                let clause = self.node("elif_clause", vec![e, c, colon, b]);
                let clause = self.field(clause, "alternative");
                ch.push(clause);
                continue;
            }
            if self.at_kw("else") {
                let clause = self.parse_else_clause();
                let clause = self.field(clause, "alternative");
                ch.push(clause);
            }
            break;
        }
        self.node("if_statement", ch)
    }

    /// Dedent/newline handling: after a block, the next token may be the keyword directly.
    fn skip_newlines_if_followed_by(&mut self, kws: &[&str]) {
        let mut i = self.pos;
        while i < self.toks.len() && self.toks[i].kind == TK::Newline {
            i += 1;
        }
        let t = self.toks[i.min(self.toks.len() - 1)];
        if t.kind == TK::Ident && kws.contains(&self.text(t)) {
            self.pos = i;
        }
    }

    fn parse_else_clause(&mut self) -> P {
        let e = self.tok("else");
        let colon = self.expect(":");
        let b = self.parse_block();
        let b = self.field(b, "body");
        self.node("else_clause", vec![e, colon, b])
    }

    fn parse_for(&mut self, mut ch: Vec<P>) -> P {
        let k = self.tok("for");
        ch.push(k);
        let left = self.parse_for_target();
        let left = self.field(left, "left");
        ch.push(left);
        let i = self.expect("in");
        ch.push(i);
        let right = self.parse_expressions_no_cond();
        let right = self.field(right, "right");
        ch.push(right);
        let colon = self.expect(":");
        ch.push(colon);
        let body = self.parse_block();
        let body = self.field(body, "body");
        ch.push(body);
        self.skip_newlines_if_followed_by(&["else"]);
        if self.at_kw("else") {
            let clause = self.parse_else_clause();
            let clause = self.field(clause, "alternative");
            ch.push(clause);
        }
        self.node("for_statement", ch)
    }

    fn parse_for_target(&mut self) -> P {
        let first = self.parse_star_target();
        if self.at(",") {
            let mut ch = vec![first];
            while self.at(",") {
                let c = self.tok(",");
                ch.push(c);
                if self.at_kw("in") {
                    break;
                }
                let e = self.parse_star_target();
                ch.push(e);
            }
            return self.node("pattern_list", ch);
        }
        first
    }

    fn parse_star_target(&mut self) -> P {
        if self.at("*") {
            let s = self.tok("*");
            let e = self.parse_primary();
            return self.node("list_splat_pattern", vec![s, e]);
        }
        self.parse_bitor()
    }

    fn parse_while(&mut self) -> P {
        let k = self.tok("while");
        let c = self.parse_expression();
        let c = self.field(c, "condition");
        let colon = self.expect(":");
        let body = self.parse_block();
        let body = self.field(body, "body");
        let mut ch = vec![k, c, colon, body];
        self.skip_newlines_if_followed_by(&["else"]);
        if self.at_kw("else") {
            let clause = self.parse_else_clause();
            let clause = self.field(clause, "alternative");
            ch.push(clause);
        }
        self.node("while_statement", ch)
    }

    fn parse_try(&mut self) -> P {
        let k = self.tok("try");
        let colon = self.expect(":");
        let body = self.parse_block();
        let body = self.field(body, "body");
        let mut ch = vec![k, colon, body];
        loop {
            self.skip_newlines_if_followed_by(&["except", "else", "finally"]);
            if self.at_kw("except") {
                let e = self.tok("except");
                let mut ech = vec![e];
                if self.at("*") {
                    let s = self.tok("*");
                    ech.push(s);
                }
                if !self.at(":") {
                    let v = self.parse_expression();
                    let v = if self.at_kw("as") {
                        let a = self.tok("as");
                        let al = self.named_leaf("identifier");
                        let al = self.node("as_pattern_target", vec![al]);
                        let al = self.field(al, "alias");
                        self.node("as_pattern", vec![v, a, al])
                    } else if self.at(",") {
                        // py2 style except A, e
                        let c = self.tok(",");
                        let al = self.parse_expression();
                        self.node("ERROR", vec![v, c, al])
                    } else {
                        v
                    };
                    let v = self.field(v, "value");
                    ech.push(v);
                }
                let colon = self.expect(":");
                ech.push(colon);
                let b = self.parse_block();
                ech.push(b);
                let clause = self.node("except_clause", ech);
                ch.push(clause);
                continue;
            }
            if self.at_kw("else") {
                let clause = self.parse_else_clause();
                ch.push(clause);
                continue;
            }
            if self.at_kw("finally") {
                let f = self.tok("finally");
                let colon = self.expect(":");
                let b = self.parse_block();
                let clause = self.node("finally_clause", vec![f, colon, b]);
                ch.push(clause);
                continue;
            }
            break;
        }
        self.node("try_statement", ch)
    }

    fn parse_with(&mut self, mut ch: Vec<P>) -> P {
        let k = self.tok("with");
        ch.push(k);
        let mut wch = Vec::new();
        let paren = self.at("(") && self.with_parenthesized();
        if paren {
            let l = self.tok("(");
            wch.push(l);
        }
        loop {
            let v = self.parse_expression();
            let v = if self.at_kw("as") {
                let a = self.tok("as");
                let target = self.parse_star_target();
                let target = self.node("as_pattern_target", vec![target]);
                let target = self.field(target, "alias");
                self.node("as_pattern", vec![v, a, target])
            } else {
                v
            };
            let v = self.field(v, "value");
            let item = self.node("with_item", vec![v]);
            wch.push(item);
            if !self.eat(",", &mut wch) {
                break;
            }
            if paren && self.at(")") {
                break;
            }
        }
        if paren {
            let r = self.expect(")");
            wch.push(r);
        }
        let clause = self.node("with_clause", wch);
        ch.push(clause);
        let colon = self.expect(":");
        ch.push(colon);
        let body = self.parse_block();
        let body = self.field(body, "body");
        ch.push(body);
        self.node("with_statement", ch)
    }

    fn with_parenthesized(&self) -> bool {
        // `with (a as b, c):` — parenthesized with items contain `as` at depth 1 or trailing ':' right after ')'
        let mut i = self.pos + 1;
        let mut depth = 1;
        while i < self.toks.len() {
            let t = self.toks[i];
            match t.kind {
                TK::Newline | TK::Eof => return false,
                TK::Punct => match self.text(t) {
                    "(" | "[" | "{" => depth += 1,
                    ")" | "]" | "}" => {
                        depth -= 1;
                        if depth == 0 {
                            let n = self.toks[(i + 1).min(self.toks.len() - 1)];
                            return n.kind == TK::Punct && self.text(n) == ":";
                        }
                    }
                    _ => {}
                },
                TK::Ident if depth == 1 && self.text(t) == "as" => return true,
                _ => {}
            }
            i += 1;
        }
        false
    }

    fn parse_def(&mut self, mut ch: Vec<P>) -> P {
        let k = self.tok("def");
        ch.push(k);
        let n = self.named_leaf("identifier");
        let n = self.field(n, "name");
        ch.push(n);
        if self.at("[") {
            let tp = self.parse_type_params();
            let tp = self.field(tp, "type_parameters");
            ch.push(tp);
        }
        let params = self.parse_parameters();
        let params = self.field(params, "parameters");
        ch.push(params);
        if self.at("->") {
            let a = self.tok("->");
            ch.push(a);
            let t = self.parse_type();
            let t = self.field(t, "return_type");
            ch.push(t);
        }
        let colon = self.expect(":");
        ch.push(colon);
        let body = self.parse_block();
        let body = self.field(body, "body");
        ch.push(body);
        self.node("function_definition", ch)
    }

    fn parse_type_params(&mut self) -> P {
        let mut ch = vec![self.tok("[")];
        while !self.at("]") && self.peek().kind != TK::Eof {
            let t = self.parse_type();
            ch.push(t);
            if !self.eat(",", &mut ch) {
                break;
            }
        }
        let r = self.expect("]");
        ch.push(r);
        self.node("type_parameter", ch)
    }

    fn parse_parameters(&mut self) -> P {
        let mut ch = vec![self.expect("(")];
        while !self.at(")") && self.peek().kind != TK::Eof {
            let before = self.pos;
            let p = self.parse_parameter();
            ch.push(p);
            if !self.eat(",", &mut ch) {
                break;
            }
            if self.pos == before {
                break;
            }
        }
        let r = self.expect(")");
        ch.push(r);
        self.node("parameters", ch)
    }

    fn parse_parameter(&mut self) -> P {
        if self.at("*") {
            let s = self.tok("*");
            if self.at(",") || self.at(")") {
                return self.node("keyword_separator", vec![s]);
            }
            let id = self.parse_param_name();
            let mut ch = vec![s, id];
            if self.at(":") {
                // typed splat: list_splat_pattern inside typed_parameter
                let sp = self.node("list_splat_pattern", ch);
                let c = self.tok(":");
                let t = self.parse_type();
                let t = self.field(t, "type");
                return self.node("typed_parameter", vec![sp, c, t]);
            }
            let _ = &mut ch;
            return self.node("list_splat_pattern", ch);
        }
        if self.at("**") {
            let s = self.tok("**");
            let id = self.parse_param_name();
            if self.at(":") {
                let sp = self.node("dictionary_splat_pattern", vec![s, id]);
                let c = self.tok(":");
                let t = self.parse_type();
                let t = self.field(t, "type");
                return self.node("typed_parameter", vec![sp, c, t]);
            }
            return self.node("dictionary_splat_pattern", vec![s, id]);
        }
        if self.at("/") {
            let s = self.tok("/");
            return self.node("positional_separator", vec![s]);
        }
        if self.at("(") {
            return self.parse_tuple_pattern();
        }
        let id = self.parse_param_name();
        if self.at(":") {
            let c = self.tok(":");
            let t = self.parse_type();
            let t = self.field(t, "type");
            if self.at("=") {
                let id = self.field(id, "name");
                let eq = self.tok("=");
                let v = self.parse_expression();
                let v = self.field(v, "value");
                return self.node("typed_default_parameter", vec![id, c, t, eq, v]);
            }
            return self.node("typed_parameter", vec![id, c, t]);
        }
        if self.at("=") {
            let id = self.field(id, "name");
            let eq = self.tok("=");
            let v = self.parse_expression();
            let v = self.field(v, "value");
            return self.node("default_parameter", vec![id, eq, v]);
        }
        id
    }

    fn parse_param_name(&mut self) -> P {
        if self.peek().kind == TK::Ident {
            self.named_leaf("identifier")
        } else {
            let t = self.peek();
            self.b.missing("identifier", t.start)
        }
    }

    fn parse_tuple_pattern(&mut self) -> P {
        let mut ch = vec![self.tok("(")];
        while !self.at(")") && self.peek().kind != TK::Eof {
            let p = if self.at("(") { self.parse_tuple_pattern() } else if self.at("*") { let s = self.tok("*"); let id = self.parse_param_name(); self.node("list_splat_pattern", vec![s, id]) } else { self.parse_param_name() };
            ch.push(p);
            if !self.eat(",", &mut ch) {
                break;
            }
        }
        let r = self.expect(")");
        ch.push(r);
        self.node("tuple_pattern", ch)
    }

    fn parse_class(&mut self) -> P {
        let k = self.tok("class");
        let n = self.named_leaf("identifier");
        let n = self.field(n, "name");
        let mut ch = vec![k, n];
        if self.at("[") {
            let tp = self.parse_type_params();
            let tp = self.field(tp, "type_parameters");
            ch.push(tp);
        }
        if self.at("(") {
            let args = self.parse_argument_list();
            let args = self.field(args, "superclasses");
            ch.push(args);
        }
        let colon = self.expect(":");
        ch.push(colon);
        let body = self.parse_block();
        let body = self.field(body, "body");
        ch.push(body);
        self.node("class_definition", ch)
    }

    fn parse_decorated(&mut self) -> P {
        let mut ch = Vec::new();
        while self.at("@") {
            let at = self.tok("@");
            let e = self.parse_expression();
            let d = self.node("decorator", vec![at, e]);
            ch.push(d);
            self.skip_newlines();
        }
        let mut defs = Vec::new();
        self.parse_statement(&mut defs);
        if let Some(d) = defs.first() {
            let d = self.field(*d, "definition");
            ch.push(d);
        }
        self.node("decorated_definition", ch)
    }

    fn parse_match(&mut self) -> P {
        let k = self.tok("match");
        let mut ch = vec![k];
        let subj = self.parse_expressions();
        let subj = self.field(subj, "subject");
        ch.push(subj);
        let colon = self.expect(":");
        ch.push(colon);
        // body: block of case clauses
        let mut bch = Vec::new();
        if self.peek().kind == TK::Newline {
            self.advance();
            if self.peek().kind == TK::Indent {
                self.advance();
                loop {
                    self.skip_newlines();
                    let t = self.peek();
                    if t.kind == TK::Dedent {
                        self.advance();
                        break;
                    }
                    if t.kind == TK::Eof {
                        break;
                    }
                    if self.at_kw("case") {
                        let c = self.tok("case");
                        let mut cch = vec![c];
                        let pat = self.parse_expression();
                        let pat = self.node("case_pattern", vec![pat]);
                        cch.push(pat);
                        while self.eat(",", &mut cch) {
                            let pat = self.parse_expression();
                            let pat = self.node("case_pattern", vec![pat]);
                            cch.push(pat);
                        }
                        if self.at_kw("if") {
                            let i = self.tok("if");
                            let cond = self.parse_expression();
                            let g = self.node("if_clause", vec![i, cond]);
                            let g = self.field(g, "guard");
                            cch.push(g);
                        }
                        let colon = self.expect(":");
                        cch.push(colon);
                        let b = self.parse_block();
                        let b = self.field(b, "consequence");
                        cch.push(b);
                        let cl = self.node("case_clause", cch);
                        bch.push(cl);
                    } else {
                        let before = self.pos;
                        self.parse_statement(&mut bch);
                        if self.pos == before {
                            let e = self.error_tok();
                            bch.push(e);
                        }
                    }
                }
            }
        }
        let body = self.node("block", bch);
        let body = self.field(body, "body");
        ch.push(body);
        self.node("match_statement", ch)
    }

    fn parse_import(&mut self) -> P {
        let k = self.tok("import");
        let mut ch = vec![k];
        loop {
            let n = self.parse_dotted_name();
            let n = if self.at_kw("as") {
                let n = self.field(n, "name");
                let a = self.tok("as");
                let al = self.named_leaf("identifier");
                let al = self.field(al, "alias");
                self.node("aliased_import", vec![n, a, al])
            } else {
                n
            };
            let n = self.field(n, "name");
            ch.push(n);
            if !self.eat(",", &mut ch) {
                break;
            }
        }
        self.node("import_statement", ch)
    }

    fn parse_dotted_name(&mut self) -> P {
        let mut ch = Vec::new();
        let id = self.parse_param_name();
        ch.push(id);
        while self.at(".") && self.peek_at(1).kind == TK::Ident {
            let d = self.tok(".");
            ch.push(d);
            let id = self.named_leaf("identifier");
            ch.push(id);
        }
        self.node("dotted_name", ch)
    }

    fn parse_import_from(&mut self) -> P {
        let k = self.tok("from");
        let mut ch = vec![k];
        // module name
        if self.at(".") || self.at("...") {
            let mut pch = Vec::new();
            while self.at(".") || self.at("...") {
                let k = if self.at(".") { "." } else { "..." };
                let d = self.tok(k);
                pch.push(d);
            }
            let prefix = self.node("import_prefix", pch);
            let mut rch = vec![prefix];
            if self.peek().kind == TK::Ident && !self.at_kw("import") {
                let dn = self.parse_dotted_name();
                rch.push(dn);
            }
            let rel = self.node("relative_import", rch);
            let rel = self.field(rel, "module_name");
            ch.push(rel);
        } else {
            let dn = self.parse_dotted_name();
            let dn = self.field(dn, "module_name");
            ch.push(dn);
        }
        let i = self.expect("import");
        ch.push(i);
        if self.at("*") {
            let s = self.tok("*");
            let w = self.node("wildcard_import", vec![s]);
            ch.push(w);
            return self.node("import_from_statement", ch);
        }
        let paren = self.at("(");
        if paren {
            let l = self.tok("(");
            ch.push(l);
        }
        loop {
            if paren && self.at(")") {
                break;
            }
            let n = self.parse_dotted_name();
            let n = if self.at_kw("as") {
                let n = self.field(n, "name");
                let a = self.tok("as");
                let al = self.named_leaf("identifier");
                let al = self.field(al, "alias");
                self.node("aliased_import", vec![n, a, al])
            } else {
                n
            };
            let n = self.field(n, "name");
            ch.push(n);
            if !self.eat(",", &mut ch) {
                break;
            }
        }
        if paren {
            let r = self.expect(")");
            ch.push(r);
        }
        self.node("import_from_statement", ch)
    }

    fn save(&self) -> (usize, usize) {
        (self.pos, self.b.nodes.len())
    }
    fn restore(&mut self, s: (usize, usize)) {
        self.pos = s.0;
        self.b.nodes.truncate(s.1);
    }
}
