// ---------- expressions ----------
impl<'s> Parser<'s> {
    /// expression or expression_list (comma separated)
    fn parse_expressions(&mut self) -> P {
        let first = self.parse_star_expression();
        if self.at(",") {
            let mut ch = vec![first];
            while self.at(",") {
                let c = self.tok(",");
                ch.push(c);
                if self.at_line_end() || self.at(")") || self.at("]") || self.at("}") || self.at("=") || self.at(":") {
                    break;
                }
                let e = self.parse_star_expression();
                ch.push(e);
            }
            return self.node("expression_list", ch);
        }
        first
    }

    /// like parse_expressions but stop before `:` (for loops)
    fn parse_expressions_no_cond(&mut self) -> P {
        self.parse_expressions()
    }

    fn parse_star_expression(&mut self) -> P {
        if self.at("*") {
            let s = self.tok("*");
            let e = self.parse_bitor();
            return self.node("list_splat", vec![s, e]);
        }
        if self.at("**") {
            let s = self.tok("**");
            let e = self.parse_bitor();
            return self.node("dictionary_splat", vec![s, e]);
        }
        self.parse_expression()
    }

    pub fn parse_expression(&mut self) -> P {
        if self.at_kw("lambda") {
            return self.parse_lambda();
        }
        if self.at_kw("yield") {
            return self.parse_yield();
        }
        let e = self.parse_or();
        if self.at_kw("if") {
            let i = self.tok("if");
            let c = self.parse_or();
            let mut ch = vec![e, i, c];
            if self.at_kw("else") {
                let el = self.tok("else");
                ch.push(el);
                let alt = self.parse_expression();
                ch.push(alt);
            }
            return self.node("conditional_expression", ch);
        }
        if self.at(":=") {
            let e = self.field(e, "name");
            let o = self.tok(":=");
            let v = self.parse_expression();
            let v = self.field(v, "value");
            return self.node("named_expression", vec![e, o, v]);
        }
        e
    }

    fn parse_lambda(&mut self) -> P {
        let k = self.tok("lambda");
        let mut ch = vec![k];
        if !self.at(":") {
            let mut pch = Vec::new();
            while !self.at(":") && self.peek().kind != TK::Eof && !self.at_line_end() {
                let p = self.parse_parameter();
                pch.push(p);
                if !self.eat(",", &mut pch) {
                    break;
                }
            }
            let params = self.node("lambda_parameters", pch);
            let params = self.field(params, "parameters");
            ch.push(params);
        }
        let colon = self.expect(":");
        ch.push(colon);
        let body = self.parse_expression();
        let body = self.field(body, "body");
        ch.push(body);
        self.node("lambda", ch)
    }

    fn parse_yield(&mut self) -> P {
        let k = self.tok("yield");
        let mut ch = vec![k];
        if self.at_kw("from") {
            let f = self.tok("from");
            ch.push(f);
            let e = self.parse_expression();
            ch.push(e);
        } else if !self.at_line_end() && !self.at(")") && !self.at("]") && !self.at("}") {
            let e = self.parse_expressions();
            ch.push(e);
        }
        self.node("yield", ch)
    }

    fn parse_or(&mut self) -> P {
        let mut l = self.parse_and();
        while self.at_kw("or") {
            let l2 = self.field(l, "left");
            let o = self.tok("or");
            let o = self.field(o, "operator");
            let r = self.parse_and();
            let r = self.field(r, "right");
            l = self.node("boolean_operator", vec![l2, o, r]);
        }
        l
    }

    fn parse_and(&mut self) -> P {
        let mut l = self.parse_not();
        while self.at_kw("and") {
            let l2 = self.field(l, "left");
            let o = self.tok("and");
            let o = self.field(o, "operator");
            let r = self.parse_not();
            let r = self.field(r, "right");
            l = self.node("boolean_operator", vec![l2, o, r]);
        }
        l
    }

    fn parse_not(&mut self) -> P {
        if self.at_kw("not") {
            let n = self.tok("not");
            let a = self.parse_not();
            let a = self.field(a, "argument");
            return self.node("not_operator", vec![n, a]);
        }
        self.parse_comparison()
    }

    fn comparison_op(&self) -> Option<(&'static str, usize)> {
        let t = self.peek();
        let tx = self.text(t);
        match t.kind {
            TK::Punct => match tx {
                "<" | ">" | "==" | "!=" | "<=" | ">=" | "<>" => Some((static_str(tx), 1)),
                _ => None,
            },
            TK::Ident => match tx {
                "in" => Some(("in", 1)),
                "is" => {
                    let t2 = self.peek_at(1);
                    if t2.kind == TK::Ident && self.text(t2) == "not" {
                        Some(("is not", 2))
                    } else {
                        Some(("is", 1))
                    }
                }
                "not" => {
                    let t2 = self.peek_at(1);
                    if t2.kind == TK::Ident && self.text(t2) == "in" {
                        Some(("not in", 2))
                    } else {
                        None
                    }
                }
                _ => None,
            },
            _ => None,
        }
    }

    fn parse_comparison(&mut self) -> P {
        let first = self.parse_bitor();
        if self.comparison_op().is_none() {
            return first;
        }
        let mut ch = vec![first];
        while let Some((op, ntoks)) = self.comparison_op() {
            let t1 = self.advance();
            let mut end = t1.end;
            for _ in 1..ntoks {
                let t = self.advance();
                end = t.end;
            }
            let o = self.b.token(op, t1.start, end);
            let o = self.field(o, "operators");
            ch.push(o);
            let r = self.parse_bitor();
            ch.push(r);
        }
        self.node("comparison_operator", ch)
    }

    fn binop(&mut self, ops: &[&'static str], next: fn(&mut Self) -> P) -> P {
        let mut l = next(self);
        loop {
            let t = self.peek();
            if t.kind != TK::Punct {
                break;
            }
            let tx = self.text(t);
            let Some(op) = ops.iter().find(|o| **o == tx) else { break };
            let l2 = self.field(l, "left");
            let o = self.tok(op);
            let o = self.field(o, "operator");
            let r = next(self);
            let r = self.field(r, "right");
            l = self.node("binary_operator", vec![l2, o, r]);
        }
        l
    }

    fn parse_bitor(&mut self) -> P {
        self.binop(&["|"], Self::parse_bitxor)
    }
    fn parse_bitxor(&mut self) -> P {
        self.binop(&["^"], Self::parse_bitand)
    }
    fn parse_bitand(&mut self) -> P {
        self.binop(&["&"], Self::parse_shift)
    }
    fn parse_shift(&mut self) -> P {
        self.binop(&["<<", ">>"], Self::parse_arith)
    }
    fn parse_arith(&mut self) -> P {
        self.binop(&["+", "-"], Self::parse_term)
    }
    fn parse_term(&mut self) -> P {
        self.binop(&["*", "/", "//", "%", "@"], Self::parse_factor)
    }

    fn parse_factor(&mut self) -> P {
        let t = self.peek();
        if t.kind == TK::Punct {
            let tx = self.text(t);
            if matches!(tx, "-" | "+" | "~") {
                let op = static_str(tx);
                let o = self.tok(op);
                let o = self.field(o, "operator");
                let a = self.parse_factor();
                let a = self.field(a, "argument");
                return self.node("unary_operator", vec![o, a]);
            }
        }
        self.parse_power()
    }

    fn parse_power(&mut self) -> P {
        let base = self.parse_await();
        if self.at("**") {
            let l = self.field(base, "left");
            let o = self.tok("**");
            let o = self.field(o, "operator");
            let r = self.parse_factor();
            let r = self.field(r, "right");
            return self.node("binary_operator", vec![l, o, r]);
        }
        base
    }

    fn parse_await(&mut self) -> P {
        if self.at_kw("await") {
            let a = self.tok("await");
            let e = self.parse_await();
            return self.node("await", vec![a, e]);
        }
        self.parse_primary()
    }

    fn parse_primary(&mut self) -> P {
        let mut e = self.parse_atom();
        loop {
            let t = self.peek();
            if t.kind != TK::Punct {
                break;
            }
            match self.text(t) {
                "." => {
                    let o = self.field(e, "object");
                    let d = self.tok(".");
                    let a = self.parse_param_name();
                    let a = self.field(a, "attribute");
                    e = self.node("attribute", vec![o, d, a]);
                }
                "(" => {
                    let f = self.field(e, "function");
                    let args = self.parse_call_args();
                    let args = self.field(args, "arguments");
                    e = self.node("call", vec![f, args]);
                }
                "[" => {
                    let v = self.field(e, "value");
                    let l = self.tok("[");
                    let mut ch = vec![v, l];
                    loop {
                        let s = self.parse_subscript_item();
                        let s = self.field(s, "subscript");
                        ch.push(s);
                        if !self.eat(",", &mut ch) {
                            break;
                        }
                        if self.at("]") {
                            break;
                        }
                    }
                    let r = self.expect("]");
                    ch.push(r);
                    e = self.node("subscript", ch);
                }
                _ => break,
            }
        }
        e
    }

    fn parse_subscript_item(&mut self) -> P {
        if self.at(":") {
            return self.parse_slice(None);
        }
        let e = self.parse_star_expression();
        if self.at(":") {
            return self.parse_slice(Some(e));
        }
        e
    }

    fn parse_slice(&mut self, first: Option<P>) -> P {
        let mut ch = Vec::new();
        if let Some(f) = first {
            ch.push(f);
        }
        let c = self.tok(":");
        ch.push(c);
        if !self.at(":") && !self.at("]") && !self.at(",") {
            let e = self.parse_expression();
            ch.push(e);
        }
        if self.at(":") {
            let c = self.tok(":");
            ch.push(c);
            if !self.at("]") && !self.at(",") {
                let e = self.parse_expression();
                ch.push(e);
            }
        }
        self.node("slice", ch)
    }

    fn parse_call_args(&mut self) -> P {
        // generator expression argument: f(x for x in y)
        let save = self.save();
        let l = self.tok("(");
        if !self.at(")") && !self.at("*") && !self.at("**") {
            let e = self.parse_expression();
            if self.at_kw("for") || self.at_kw("async") {
                let mut ch = vec![l];
                let body = self.field(e, "body");
                ch.push(body);
                self.parse_comprehension_clauses(&mut ch);
                let r = self.expect(")");
                ch.push(r);
                return self.node("generator_expression", ch);
            }
        }
        self.restore(save);
        self.parse_argument_list()
    }

    fn parse_argument_list(&mut self) -> P {
        let mut ch = vec![self.expect("(")];
        while !self.at(")") && self.peek().kind != TK::Eof {
            let before = self.pos;
            let a = if self.at("*") {
                let s = self.tok("*");
                let e = self.parse_expression();
                self.node("list_splat", vec![s, e])
            } else if self.at("**") {
                let s = self.tok("**");
                let e = self.parse_expression();
                self.node("dictionary_splat", vec![s, e])
            } else if self.peek().kind == TK::Ident && self.peek_at(1).kind == TK::Punct && self.text(self.peek_at(1)) == "=" {
                let n = self.named_leaf("identifier");
                let n = self.field(n, "name");
                let eq = self.tok("=");
                let v = self.parse_expression();
                let v = self.field(v, "value");
                self.node("keyword_argument", vec![n, eq, v])
            } else {
                let e = self.parse_expression();
                if self.at_kw("for") || self.at_kw("async") {
                    let body = self.field(e, "body");
                    let mut gch = vec![body];
                    self.parse_comprehension_clauses(&mut gch);
                    self.node("generator_expression", gch)
                } else {
                    e
                }
            };
            ch.push(a);
            if !self.eat(",", &mut ch) {
                break;
            }
            if self.pos == before {
                break;
            }
        }
        let r = self.expect(")");
        ch.push(r);
        self.node("argument_list", ch)
    }

    fn parse_comprehension_clauses(&mut self, ch: &mut Vec<P>) {
        loop {
            if self.at_kw("for") || (self.at_kw("async") && self.text(self.peek_at(1)) == "for") {
                let mut fch = Vec::new();
                if self.at_kw("async") {
                    let a = self.tok("async");
                    fch.push(a);
                }
                let f = self.tok("for");
                fch.push(f);
                let left = self.parse_for_target();
                let left = self.field(left, "left");
                fch.push(left);
                let i = self.expect("in");
                fch.push(i);
                let right = self.parse_or();
                let right = self.field(right, "right");
                fch.push(right);
                let n = self.node("for_in_clause", fch);
                ch.push(n);
                continue;
            }
            if self.at_kw("if") {
                let i = self.tok("if");
                let c = self.parse_or_no_cond();
                let n = self.node("if_clause", vec![i, c]);
                ch.push(n);
                continue;
            }
            break;
        }
    }

    fn parse_or_no_cond(&mut self) -> P {
        self.parse_or()
    }

    fn parse_atom(&mut self) -> P {
        let t = self.peek();
        match t.kind {
            TK::Ident => {
                let tx = self.text(t);
                match tx {
                    "True" => self.named_leaf("true"),
                    "False" => self.named_leaf("false"),
                    "None" => self.named_leaf("none"),
                    "lambda" => self.parse_lambda(),
                    "yield" => self.parse_yield(),
                    "await" => self.parse_await(),
                    "not" => self.parse_not(),
                    "print" | "exec" => self.named_leaf("identifier"),
                    _ => self.named_leaf("identifier"),
                }
            }
            TK::Number => {
                let tx = self.text(t);
                let is_float = (tx.contains('.') || tx.contains('e') || tx.contains('E')) && !tx.starts_with("0x") && !tx.starts_with("0X");
                self.named_leaf(if is_float { "float" } else { "integer" })
            }
            TK::Str => self.parse_strings(),
            TK::Punct => {
                let tx = self.text(t);
                match tx {
                    "(" => self.parse_paren(),
                    "[" => self.parse_list(),
                    "{" => self.parse_dict_or_set(),
                    "..." => self.named_leaf("ellipsis"),
                    "-" | "+" | "~" => self.parse_factor(),
                    "*" => {
                        let s = self.tok("*");
                        let e = self.parse_bitor();
                        self.node("list_splat", vec![s, e])
                    }
                    _ => {
                        let e = self.error_tok();
                        self.node("ERROR", vec![e])
                    }
                }
            }
            _ => {
                let m = self.b.missing("identifier", t.start);
                m
            }
        }
    }

    fn parse_paren(&mut self) -> P {
        let l = self.tok("(");
        if self.at(")") {
            let r = self.tok(")");
            return self.node("tuple", vec![l, r]);
        }
        if self.at_kw("yield") {
            let y = self.parse_yield();
            let r = self.expect(")");
            return self.node("parenthesized_expression", vec![l, y, r]);
        }
        let first = self.parse_star_expression();
        if self.at_kw("for") || self.at_kw("async") {
            let body = self.field(first, "body");
            let mut ch = vec![l, body];
            self.parse_comprehension_clauses(&mut ch);
            let r = self.expect(")");
            ch.push(r);
            return self.node("generator_expression", ch);
        }
        if self.at(",") {
            let mut ch = vec![l, first];
            while self.at(",") {
                let c = self.tok(",");
                ch.push(c);
                if self.at(")") {
                    break;
                }
                let e = self.parse_star_expression();
                ch.push(e);
            }
            let r = self.expect(")");
            ch.push(r);
            return self.node("tuple", ch);
        }
        let r = self.expect(")");
        if self.b.kind(first) == "list_splat" {
            return self.node("parenthesized_list_splat", vec![l, first, r]);
        }
        self.node("parenthesized_expression", vec![l, first, r])
    }

    fn parse_list(&mut self) -> P {
        let l = self.tok("[");
        if self.at("]") {
            let r = self.tok("]");
            return self.node("list", vec![l, r]);
        }
        let first = self.parse_star_expression();
        if self.at_kw("for") || self.at_kw("async") {
            let body = self.field(first, "body");
            let mut ch = vec![l, body];
            self.parse_comprehension_clauses(&mut ch);
            let r = self.expect("]");
            ch.push(r);
            return self.node("list_comprehension", ch);
        }
        let mut ch = vec![l, first];
        while self.at(",") {
            let c = self.tok(",");
            ch.push(c);
            if self.at("]") {
                break;
            }
            let e = self.parse_star_expression();
            ch.push(e);
        }
        let r = self.expect("]");
        ch.push(r);
        self.node("list", ch)
    }

    fn parse_dict_or_set(&mut self) -> P {
        let l = self.tok("{");
        if self.at("}") {
            let r = self.tok("}");
            return self.node("dictionary", vec![l, r]);
        }
        if self.at("**") {
            // dictionary with splat first
            let s = self.tok("**");
            let e = self.parse_bitor();
            let first = self.node("dictionary_splat", vec![s, e]);
            return self.finish_dict(l, first);
        }
        let first = self.parse_star_expression();
        if self.at(":") {
            let k = self.field(first, "key");
            let c = self.tok(":");
            let v = self.parse_expression();
            let v = self.field(v, "value");
            let pair = self.node("pair", vec![k, c, v]);
            if self.at_kw("for") || self.at_kw("async") {
                let mut ch = vec![l];
                let pair = self.field(pair, "body");
                ch.push(pair);
                self.parse_comprehension_clauses(&mut ch);
                let r = self.expect("}");
                ch.push(r);
                return self.node("dictionary_comprehension", ch);
            }
            return self.finish_dict(l, pair);
        }
        if self.at_kw("for") || self.at_kw("async") {
            let body = self.field(first, "body");
            let mut ch = vec![l, body];
            self.parse_comprehension_clauses(&mut ch);
            let r = self.expect("}");
            ch.push(r);
            return self.node("set_comprehension", ch);
        }
        let mut ch = vec![l, first];
        while self.at(",") {
            let c = self.tok(",");
            ch.push(c);
            if self.at("}") {
                break;
            }
            let e = self.parse_star_expression();
            ch.push(e);
        }
        let r = self.expect("}");
        ch.push(r);
        self.node("set", ch)
    }

    fn finish_dict(&mut self, l: P, first: P) -> P {
        let mut ch = vec![l, first];
        while self.at(",") {
            let c = self.tok(",");
            ch.push(c);
            if self.at("}") {
                break;
            }
            if self.at("**") {
                let s = self.tok("**");
                let e = self.parse_bitor();
                let sp = self.node("dictionary_splat", vec![s, e]);
                ch.push(sp);
                continue;
            }
            let k = self.parse_expression();
            let k = self.field(k, "key");
            let c = self.expect(":");
            let v = self.parse_expression();
            let v = self.field(v, "value");
            let pair = self.node("pair", vec![k, c, v]);
            ch.push(pair);
        }
        let r = self.expect("}");
        ch.push(r);
        self.node("dictionary", ch)
    }

    fn parse_strings(&mut self) -> P {
        let first = self.parse_string();
        if self.peek().kind == TK::Str {
            let mut ch = vec![first];
            while self.peek().kind == TK::Str {
                let s = self.parse_string();
                ch.push(s);
            }
            return self.node("concatenated_string", ch);
        }
        first
    }

    fn parse_string(&mut self) -> P {
        let t = self.advance();
        let text = self.text(t);
        let prefix = string_prefix_len(self.src, t.start).unwrap_or(0);
        let q = self.src.as_bytes()[t.start + prefix];
        let triple = text.len() >= prefix + 6 && text.as_bytes()[prefix + 1] == q && text.as_bytes()[prefix + 2] == q;
        let qlen = if triple { 3 } else { 1 };
        let is_f = text[..prefix].to_ascii_lowercase().contains('f');
        let start_end = t.start + prefix + qlen;
        let mut ch = vec![self.b.leaf("string_start", true, t.start, start_end)];
        // determine closing
        let closed = if triple {
            t.end >= start_end + 3 && &self.src[t.end - 3..t.end] == std::str::from_utf8(&[q, q, q]).unwrap()
        } else {
            t.end > start_end && self.src.as_bytes()[t.end - 1] == q
        };
        let content_end = if closed { t.end - qlen } else { t.end };
        self.string_body(start_end, content_end, is_f, &mut ch);
        if closed {
            let e = self.b.leaf("string_end", true, content_end, t.end);
            ch.push(e);
        } else {
            let m = self.b.missing("string_end", t.end);
            ch.push(m);
        }
        self.b.node_with_range("string", ch, t.start, t.end)
    }

    fn string_body(&mut self, start: usize, end: usize, is_f: bool, ch: &mut Vec<P>) {
        let bytes = self.src.as_bytes();
        let mut i = start;
        let mut frag = start;
        let flush = |p: &mut Parser<'s>, frag: usize, i: usize, ch: &mut Vec<P>| {
            if frag < i {
                let f = p.b.leaf("string_content", true, frag, i);
                ch.push(f);
            }
        };
        while i < end {
            let b = bytes[i];
            if b == b'\\' {
                flush(self, frag, i, ch);
                let mut e = (i + 2).min(end);
                if i + 1 < end {
                    match bytes[i + 1] {
                        b'x' => e = (i + 4).min(end),
                        b'u' => e = (i + 6).min(end),
                        b'U' => e = (i + 10).min(end),
                        b'N' => {
                            e = self.src[i..end].find('}').map(|x| i + x + 1).unwrap_or(end);
                        }
                        b'0'..=b'7' => {
                            let mut k = i + 1;
                            while k < end && k < i + 4 && (b'0'..=b'7').contains(&bytes[k]) {
                                k += 1;
                            }
                            e = k;
                        }
                        _ => {}
                    }
                }
                let n = self.b.leaf("escape_sequence", true, i, e);
                ch.push(n);
                i = e;
                frag = i;
                continue;
            }
            if is_f && b == b'{' {
                if i + 1 < end && bytes[i + 1] == b'{' {
                    // escaped brace: part of content
                    i += 2;
                    continue;
                }
                flush(self, frag, i, ch);
                // find matching }
                let mut depth = 0;
                let mut j = i;
                while j < end {
                    match bytes[j] {
                        b'{' => depth += 1,
                        b'}' => {
                            depth -= 1;
                            if depth == 0 {
                                break;
                            }
                        }
                        _ => {}
                    }
                    j += 1;
                }
                let close = j.min(end);
                let open = self.b.token("{", i, i + 1);
                let mut ich = vec![open];
                // inner expression: parse with a sub-parser
                let inner_start = i + 1;
                // find conversion / format spec at depth 0
                let inner = &self.src[inner_start..close];
                let mut expr_end = close;
                let mut conv: Option<(usize, usize)> = None;
                let mut spec: Option<(usize, usize)> = None;
                {
                    let ib = inner.as_bytes();
                    let mut d = 0;
                    let mut k = 0;
                    let mut in_str: Option<u8> = None;
                    while k < ib.len() {
                        let c = ib[k];
                        if let Some(q) = in_str {
                            if c == q {
                                in_str = None;
                            }
                            k += 1;
                            continue;
                        }
                        match c {
                            b'\'' | b'"' => in_str = Some(c),
                            b'(' | b'[' | b'{' => d += 1,
                            b')' | b']' | b'}' => d -= 1,
                            b'!' if d == 0 && k + 1 < ib.len() && ib[k + 1] != b'=' => {
                                expr_end = inner_start + k;
                                conv = Some((inner_start + k, inner_start + k + 2));
                                // spec after conversion
                                if k + 2 < ib.len() && ib[k + 2] == b':' {
                                    spec = Some((inner_start + k + 2, close));
                                }
                                break;
                            }
                            b':' if d == 0 => {
                                expr_end = inner_start + k;
                                spec = Some((inner_start + k, close));
                                break;
                            }
                            b'=' if d == 0 && k + 1 == ib.len() => {
                                expr_end = inner_start + k;
                                break;
                            }
                            _ => {}
                        }
                        k += 1;
                    }
                }
                let sub_src = &self.src[..expr_end];
                let mut lx = Lexer { src: sub_src, toks: Vec::new(), comments: Vec::new() };
                // lex only the inner region
                let mut toks = lex_region(sub_src, inner_start, expr_end);
                toks.push(Tok { kind: TK::Eof, start: expr_end, end: expr_end });
                let _ = &mut lx;
                let saved_toks = std::mem::replace(&mut self.toks, toks);
                let saved_pos = self.pos;
                self.pos = 0;
                let e = self.parse_expressions();
                let e = self.field(e, "expression");
                ich.push(e);
                self.toks = saved_toks;
                self.pos = saved_pos;
                if expr_end < close && self.src.as_bytes()[expr_end] == b'=' && conv.is_none() && spec.is_none() {
                    let eq = self.b.token("=", expr_end, expr_end + 1);
                    ich.push(eq);
                }
                if let Some((s, e)) = conv {
                    let c = self.b.leaf("type_conversion", true, s, e.min(close));
                    let c = self.field(c, "type_conversion");
                    ich.push(c);
                }
                if let Some((s, e)) = spec {
                    let colon = self.b.token(":", s, s + 1);
                    let mut sch = vec![colon];
                    if s + 1 < e {
                        // nested interpolations in format spec are rare; treat as content
                        let fs = self.b.leaf("format_specifier_content", true, s + 1, e);
                        let _ = fs;
                        self.b.nodes.pop();
                    }
                    let fsn = self.b.node_with_range("format_specifier", sch.drain(..).collect(), s, e);
                    let fsn = self.field(fsn, "format_specifier");
                    ich.push(fsn);
                }
                if close < end {
                    let cl = self.b.token("}", close, close + 1);
                    ich.push(cl);
                    i = close + 1;
                } else {
                    i = end;
                }
                let interp = self.node("interpolation", ich);
                ch.push(interp);
                frag = i;
                continue;
            }
            i += 1;
        }
        flush(self, frag, end, ch);
    }
}

fn lex_region(src: &str, start: usize, end: usize) -> Vec<Tok> {
    let region = &src[..end];
    let mut lx = Lexer { src: region, toks: Vec::new(), comments: Vec::new() };
    // lex from start by using a sub-lexer on the suffix and offsetting
    let sub = &region[start..];
    let mut l2 = Lexer { src: sub, toks: Vec::new(), comments: Vec::new() };
    l2.run();
    let _ = &mut lx;
    l2.toks
        .into_iter()
        .filter(|t| !matches!(t.kind, TK::Newline | TK::Indent | TK::Dedent | TK::Eof))
        .map(|t| Tok { kind: t.kind, start: t.start + start, end: t.end + start })
        .collect()
}

pub fn parse(src: Rc<str>, lang: Language) -> Tree {
    let mut lx = Lexer { src: &src, toks: Vec::new(), comments: Vec::new() };
    lx.run();
    let comments = std::mem::take(&mut lx.comments);
    let mut p = Parser { src: &src, toks: lx.toks, pos: 0, b: TreeBuilder::new() };
    let root = p.parse_module();
    let mut extras = Vec::new();
    for (s, e) in comments {
        let c = p.b.leaf("comment", true, s, e);
        extras.push(c);
    }
    // extend module range to include trailing comments
    insert_extras(&mut p.b, root, extras);
    super::js::flatten_errors(&mut p.b, root);
    p.b.finish(src, lang, root)
}
