fn sev_to_codespan(s: Severity) -> codespan::Severity {
    match s {
        Severity::Error => codespan::Severity::Error,
        Severity::Warning => codespan::Severity::Warning,
        Severity::Info => codespan::Severity::Note,
        _ => codespan::Severity::Help,
    }
}

fn yaml_to_json(v: &serde_yaml::Value) -> Value {
    match v {
        serde_yaml::Value::Null => Value::Null,
        serde_yaml::Value::Bool(b) => Value::Bool(*b),
        serde_yaml::Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                json!(i)
            } else if let Some(u) = n.as_u64() {
                json!(u)
            } else {
                json!(n.as_f64().unwrap_or(0.0))
            }
        }
        serde_yaml::Value::String(s) => Value::String(s.clone()),
        serde_yaml::Value::Sequence(seq) => Value::Array(seq.iter().map(yaml_to_json).collect()),
        serde_yaml::Value::Mapping(m) => {
            let mut map = serde_json::Map::new();
            for (k, v) in m {
                let key = match k {
                    serde_yaml::Value::String(s) => s.clone(),
                    other => serde_yaml::to_string(other).unwrap_or_default().trim().to_string(),
                };
                map.insert(key, yaml_to_json(v));
            }
            Value::Object(map)
        }
        serde_yaml::Value::Tagged(t) => yaml_to_json(&t.value),
    }
}

struct Overrides {
    error: Option<Vec<String>>,
    warning: Option<Vec<String>>,
    info: Option<Vec<String>>,
    hint: Option<Vec<String>>,
    off: Option<Vec<String>>,
}

fn get_override(m: &ArgMatches, name: &str) -> Option<Vec<String>> {
    if !m.contains_id(name) {
        return None;
    }
    let vals: Vec<String> = m.get_many::<String>(name).map(|v| v.cloned().filter(|s| !s.is_empty()).collect()).unwrap_or_default();
    Some(vals)
}

impl Overrides {
    fn apply(&self, id: &str, sev: Severity) -> Severity {
        let mut s = sev;
        let check = |o: &Option<Vec<String>>, target: Severity, s: &mut Severity| {
            if let Some(ids) = o {
                if ids.is_empty() || ids.iter().any(|i| i == id) {
                    *s = target;
                }
            }
        };
        check(&self.error, Severity::Error, &mut s);
        check(&self.warning, Severity::Warning, &mut s);
        check(&self.info, Severity::Info, &mut s);
        check(&self.hint, Severity::Hint, &mut s);
        check(&self.off, Severity::Off, &mut s);
        s
    }
}

pub struct ScanPrinter {
    pub colored: ColoredPrinter,
    pub report_style: String,
}

impl ScanPrinter {
    fn severity_header(&self, sev: Severity, id: &str) -> String {
        let text = format!("{}[{}]:", sev_to_codespan(sev).name(), id);
        if !self.colored.styles.color {
            return text;
        }
        match sev {
            Severity::Error => format!("\x1b[1;31m{}\x1b[0m", text),
            Severity::Warning => format!("\x1b[1;33m{}\x1b[0m", text),
            Severity::Info => format!("\x1b[1m{}\x1b[0m", text),
            _ => format!("\x1b[1;2m{}\x1b[0m", text),
        }
    }

    pub fn print_rule_match(&self, out: &mut String, path: &str, tree: &Tree, rule: &RuleConfig, sev: Severity, m: &NodeMatch, edit: Option<&Edit>) {
        let message = crate::meta_var::expand_template(&rule.message, &m.env, tree.lang.meta_var_char());
        if let Some(edit) = edit {
            // diff style
            if self.report_style == "rich" {
                let _ = writeln!(out, "{}", self.colored.styles.file(path));
                let _ = writeln!(out, "{} {}", self.severity_header(sev, &rule.id), self.colored.styles.bold(&message));
                let new_src = apply_edits(&tree.source, std::slice::from_ref(edit));
                self.colored.print_unified(out, &tree.source, &new_src);
            } else {
                let (l, c) = m.node.start_pos();
                let _ = writeln!(out, "{}:{}:{}: {} {}", path, l + 1, c + 1, self.severity_header(sev, &rule.id), self.colored.styles.bold(&message));
            }
            if let Some(note) = &rule.note {
                let _ = writeln!(out, "{}", self.colored.styles.italic("Note:"));
                let _ = writeln!(out, "{}\n", note.trim_end_matches('\n'));
            }
            return;
        }
        // codespan style
        let mut labels = vec![Label { start: m.node.start(), end: m.node.end(), primary: true, message: String::new() }];
        if let Some(lc) = &rule.labels {
            labels.clear();
            let mut names: Vec<&String> = lc.keys().collect();
            names.sort();
            for name in names {
                let cfg = &lc[name];
                if let Some(n) = m.env.get_single(name) {
                    labels.push(Label {
                        start: n.start(),
                        end: n.end(),
                        primary: cfg.style == LabelStyle::Primary,
                        message: cfg.message.as_ref().map(|t| crate::meta_var::expand_template(t, &m.env, tree.lang.meta_var_char())).unwrap_or_default(),
                    });
                }
            }
            if labels.is_empty() {
                labels.push(Label { start: m.node.start(), end: m.node.end(), primary: true, message: String::new() });
            }
        }
        let notes: Vec<String> = rule.note.iter().map(|n| n.trim_end_matches('\n').to_string()).collect();
        let d = Diagnostic { severity: sev_to_codespan(sev), code: &rule.id, message: &message, path, labels, notes };
        out.push_str(&codespan::render(&d, tree, &self.report_style, self.colored.styles.color));
    }
}

pub fn scan(m: &ArgMatches, config: Option<String>) -> SgResult<i32> {
    let is_tty = crate::print::stdout_is_tty();
    let color = ColorMode::parse(m.get_one::<String>("color").map(|s| s.as_str()).unwrap_or("auto")).should_color(is_tty);
    let ctx = *m.get_one::<u16>("context").unwrap_or(&0) as usize;
    let before = if ctx > 0 { ctx } else { *m.get_one::<u16>("before").unwrap_or(&0) as usize };
    let after = if ctx > 0 { ctx } else { *m.get_one::<u16>("after").unwrap_or(&0) as usize };
    let printer = ScanPrinter {
        colored: ColoredPrinter { styles: Styles { color }, heading: true, before, after },
        report_style: m.get_one::<String>("report_style").cloned().unwrap_or_else(|| "rich".into()),
    };
    let json_style = m.get_one::<String>("json").map(|s| JsonStyle::parse(s));
    let format = m.get_one::<String>("format").cloned();
    let include_metadata = m.get_flag("include_metadata");
    let files_with_matches = m.get_flag("files_with_matches");
    let update_all = m.get_flag("update_all");
    let max_results = m.get_one::<usize>("max_results").copied();
    let inspect = m.get_one::<String>("inspect").cloned().unwrap_or_else(|| "nothing".into());
    let overrides = Overrides {
        error: get_override(m, "error"),
        warning: get_override(m, "warning"),
        info: get_override(m, "info"),
        hint: get_override(m, "hint"),
        off: get_override(m, "off"),
    };
    let filter = m.get_one::<String>("filter").map(|r| regex::Regex::new(r)).transpose().map_err(|e| SgError::new("Cannot parse regex", "The filter regex is invalid", None, 8).cause(e.to_string()))?;

    let project = load_project(config.as_deref())?;
    let rule_file = m.get_one::<String>("rule").cloned();
    let inline = m.get_one::<String>("inline_rules").cloned();
    let mut rules: Vec<RuleConfig> = if let Some(rf) = &rule_file {
        let utils = match &project {
            Some(p) => crate::config::load_global_utils(p).unwrap_or_default(),
            None => HashMap::new(),
        };
        load_rule_file(rf, &utils)?
    } else if let Some(text) = &inline {
        let utils = match &project {
            Some(p) => crate::config::load_global_utils(p).unwrap_or_default(),
            None => HashMap::new(),
        };
        parse_rule_text(text, None, &utils).map_err(|causes| parse_rule_error("", causes).with_inline())?
    } else {
        let Some(p) = &project else { return Err(no_project_error()) };
        load_project_rules(p)?.rules
    };
    if let Some(re) = &filter {
        rules.retain(|r| re.is_match(&r.id));
    }
    let lang_globs = project.as_ref().and_then(|p| p.config.language_globs.as_ref()).map(LangGlobs::from_map).unwrap_or_default();
    if inspect != "nothing" {
        match &project {
            Some(p) => {
                let dir = std::fs::canonicalize(&p.dir).unwrap_or_else(|_| p.dir.clone());
                eprintln!("sg: summary|project: isProject=true,projectDir={}", dir.display());
            }
            None => eprintln!("sg: summary|project: isProject=false"),
        }
    }
    // effective severities
    let mut effective: Vec<(usize, Severity)> = Vec::new();
    let mut skipped_rules = 0;
    for (i, r) in rules.iter().enumerate() {
        let sev = overrides.apply(&r.id, r.severity);
        if sev == Severity::Off {
            skipped_rules += 1;
            if inspect == "entity" {
                eprintln!("sg: entity|rule|{}: finalSeverity=Off", r.id);
            }
            continue;
        }
        if inspect == "entity" {
            let name = match sev {
                Severity::Error => "Error",
                Severity::Warning => "Warning",
                Severity::Info => "Info",
                _ => "Hint",
            };
            eprintln!("sg: entity|rule|{}: finalSeverity={}", r.id, name);
        }
        effective.push((i, sev));
    }

    let mut out = String::new();
    let mut json_printer = json_style.map(JsonPrinter::new);
    if let Some(jp) = &mut json_printer {
        jp.begin(&mut out);
    }
    let mut sarif_results: Vec<Value> = Vec::new();
    let mut error_count = 0usize;
    let mut total = 0usize;
    let mut scanned = 0usize;
    let mut skipped = 0usize;
    let mut stop = false;

    let stdin_mode = m.get_flag("stdin");
    let mut files: Vec<(String, PathBuf, Option<String>)> = Vec::new();
    if stdin_mode {
        let mut src = String::new();
        std::io::Read::read_to_string(&mut std::io::stdin(), &mut src).ok();
        files.push(("STDIN".into(), PathBuf::from("STDIN"), Some(src)));
    } else {
        let paths: Vec<PathBuf> = m.get_many::<String>("paths").map(|v| v.map(PathBuf::from).collect()).unwrap_or_else(|| vec![PathBuf::from(".")]);
        let no_ignore = NoIgnore::from_values(&m.get_many::<String>("no_ignore").map(|v| v.cloned().collect::<Vec<_>>()).unwrap_or_default());
        let globs: Vec<String> = m.get_many::<String>("globs").map(|v| v.cloned().collect()).unwrap_or_default();
        let wr = walk(&WalkOptions { paths, follow: m.get_flag("follow"), no_ignore, globs, threads: 0 });
        for e in &wr.errors {
            eprintln!("ERROR: {}", e);
        }
        for f in wr.files {
            files.push((display_path(&f), f, None));
        }
    }

    for (display, path, content) in files {
        if stop {
            break;
        }
        scanned += 1;
        let lang = if stdin_mode {
            // stdin: use the language of rules? ast-grep requires rules to decide; use first rule's language
            match rules.first() {
                Some(r) => r.language,
                None => continue,
            }
        } else {
            match lang_globs.detect(&path) {
                Some(l) => l,
                None => {
                    skipped += 1;
                    continue;
                }
            }
        };
        let applicable: Vec<(usize, Severity)> = effective.iter().copied().filter(|(i, _)| rules[*i].language == lang && rules[*i].applies_to(&path)).collect();
        if inspect == "entity" {
            eprintln!("sg: entity|file|{}: language={},appliedRuleCount={}", display, lang.name(), applicable.len());
        }
        if applicable.is_empty() {
            continue;
        }
        let src = match content {
            Some(s) => s,
            None => match std::fs::read_to_string(&path) {
                Ok(s) => s,
                Err(_) => continue,
            },
        };
        let tree = crate::parsers::parse(lang, &src);
        let root = tree.root();
        let mut file_edits: Vec<Edit> = Vec::new();
        for (ri, sev) in &applicable {
            if stop {
                break;
            }
            let rule = &rules[*ri];
            let matches = rule.find_all(root);
            if matches.is_empty() {
                continue;
            }
            if files_with_matches {
                out.push_str(&display);
                out.push('\n');
                if *sev == Severity::Error {
                    error_count += matches.len();
                }
                continue;
            }
            for mt in &matches {
                if let Some(mx) = max_results {
                    if total >= mx {
                        stop = true;
                        break;
                    }
                }
                total += 1;
                if *sev == Severity::Error {
                    error_count += 1;
                }
                let edit = rule.fix_edit(mt.node, &mt.env);
                let message = crate::meta_var::expand_template(&rule.message, &mt.env, lang.meta_var_char());
                if update_all {
                    if let Some(e) = &edit {
                        file_edits.push(e.clone());
                    }
                    continue;
                }
                if let Some(jp) = &mut json_printer {
                    let rep = edit.as_ref().map(|e| (e.inserted.clone(), e.start, e.end));
                    let mut labels: Vec<(usize, usize, &'static str)> = vec![(mt.node.start(), mt.node.end(), "primary")];
                    if let Some(lc) = &rule.labels {
                        labels.clear();
                        let mut names: Vec<&String> = lc.keys().collect();
                        names.sort();
                        for name in names {
                            if let Some(n) = mt.env.get_single(name) {
                                labels.push((n.start(), n.end(), if lc[name].style == LabelStyle::Primary { "primary" } else { "secondary" }));
                            }
                        }
                    }
                    let info = RuleInfo {
                        id: &rule.id,
                        severity: sev.name(),
                        note: rule.note.as_deref(),
                        message: &message,
                        labels,
                        metadata: if include_metadata { Some(rule.metadata.as_ref().map(yaml_to_json).unwrap_or(Value::Null)) } else { None },
                    };
                    let v = match_json(mt, &display, rep.as_ref(), Some(&info));
                    jp.print(&mut out, &v);
                    continue;
                }
                match format.as_deref() {
                    Some("github") => {
                        let (sl, _) = mt.node.start_pos();
                        let (el, _) = mt.node.end_pos();
                        let level = match sev {
                            Severity::Error => "error",
                            Severity::Warning => "warning",
                            Severity::Info => "notice",
                            _ => continue,
                        };
                        let _ = writeln!(out, "::{} file={},line={},endLine={},title={}::{}", level, display, sl + 1, el + 1, rule.id, message);
                    }
                    Some("sarif") => {
                        sarif_results.push(sarif_result(&display, &tree, mt, rule, *sev, &message, edit.as_ref()));
                    }
                    _ => {
                        printer.print_rule_match(&mut out, &display, &tree, rule, *sev, mt, edit.as_ref());
                    }
                }
            }
        }
        if update_all && !file_edits.is_empty() && !stdin_mode {
            file_edits.sort_by_key(|e| e.start);
            let new_src = apply_edits(&src, &file_edits);
            let _ = std::fs::write(&path, new_src);
        }
    }
    if inspect != "nothing" {
        eprintln!("sg: summary|file: scannedFileCount={},skippedFileCount={}", scanned, skipped);
        eprintln!("sg: summary|rule: effectiveRuleCount={},skippedRuleCount={}", effective.len(), skipped_rules);
    }
    if let Some(jp) = &mut json_printer {
        jp.end(&mut out);
    }
    if format.as_deref() == Some("sarif") {
        let doc = sarif_doc(sarif_results);
        out.push_str(&serde_json::to_string_pretty(&doc).unwrap());
        out.push('\n');
    }
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(out.as_bytes());
    let _ = lock.flush();
    if error_count > 0 {
        eprintln!("Error: {} error(s) found in code.\nHelp: Scan succeeded and found error level diagnostics in the codebase.\n", error_count);
        return Ok(1);
    }
    Ok(0)
}

trait InlineErr {
    fn with_inline(self) -> SgError;
}
impl InlineErr for SgError {
    fn with_inline(mut self) -> SgError {
        self.message = "Cannot parse inline rules.".to_string();
        self.help = "The inline rules are not valid ast-grep rules. Please refer to doc and fix the error.".to_string();
        self
    }
}

fn region(tree: &Tree, start: usize, end: usize, snippet: bool) -> Value {
    let (sl, sc) = tree.position(start);
    let (el, ec) = tree.position(end);
    let mut map = serde_json::Map::new();
    map.insert("byteLength".into(), json!(end - start));
    map.insert("byteOffset".into(), json!(start));
    map.insert("endColumn".into(), json!(ec + 1));
    map.insert("endLine".into(), json!(el + 1));
    if snippet {
        map.insert("snippet".into(), json!({"text": &tree.source[start..end]}));
    }
    map.insert("startColumn".into(), json!(sc + 1));
    map.insert("startLine".into(), json!(sl + 1));
    Value::Object(map)
}

fn sarif_result(path: &str, tree: &Tree, m: &NodeMatch, rule: &RuleConfig, sev: Severity, message: &str, edit: Option<&Edit>) -> Value {
    let mut map = serde_json::Map::new();
    if let Some(e) = edit {
        map.insert(
            "fixes".into(),
            json!([{
                "artifactChanges": [{
                    "artifactLocation": {"uri": path},
                    "replacements": [{
                        "deletedRegion": region(tree, e.start, e.end, false),
                        "insertedContent": {"text": e.inserted},
                    }]
                }],
                "description": {"text": "Apply suggested fix"}
            }]),
        );
    }
    let level = match sev {
        Severity::Error => "error",
        Severity::Warning => "warning",
        _ => "note",
    };
    map.insert("level".into(), json!(level));
    map.insert(
        "locations".into(),
        json!([{"physicalLocation": {"artifactLocation": {"uri": path}, "region": region(tree, m.node.start(), m.node.end(), true)}}]),
    );
    map.insert("message".into(), json!({"text": message}));
    map.insert("ruleId".into(), json!(rule.id));
    Value::Object(map)
}

fn sarif_doc(results: Vec<Value>) -> Value {
    let mut run = serde_json::Map::new();
    run.insert("results".into(), Value::Array(results));
    run.insert("tool".into(), json!({"driver": {"name": "ast-grep"}}));
    let mut doc = serde_json::Map::new();
    doc.insert("runs".into(), Value::Array(vec![Value::Object(run)]));
    doc.insert("version".into(), json!("0.42.1"));
    Value::Object(doc)
}
