pub fn myers_ops<T: PartialEq>(old: &[T], new: &[T]) -> Vec<Op> {
    let mut ops: Vec<Op> = Vec::new();
    let n = old.len();
    let m = new.len();
    let mut vf = V::new(n + m + 3);
    let mut vb = V::new(n + m + 3);
    conquer(&mut ops, old, 0..n, new, 0..m, &mut vf, &mut vb);
    merge_ops(ops)
}

struct V {
    offset: isize,
    v: Vec<usize>,
}

impl V {
    fn new(max_d: usize) -> V {
        V { offset: max_d as isize, v: vec![0; 2 * max_d + 2] }
    }
    fn len(&self) -> usize {
        self.v.len()
    }
}

impl std::ops::Index<isize> for V {
    type Output = usize;
    fn index(&self, i: isize) -> &usize {
        &self.v[(i + self.offset) as usize]
    }
}
impl std::ops::IndexMut<isize> for V {
    fn index_mut(&mut self, i: isize) -> &mut usize {
        &mut self.v[(i + self.offset) as usize]
    }
}

fn common_prefix_len<T: PartialEq>(old: &[T], or: std::ops::Range<usize>, new: &[T], nr: std::ops::Range<usize>) -> usize {
    let mut i = 0;
    while or.start + i < or.end && nr.start + i < nr.end && old[or.start + i] == new[nr.start + i] {
        i += 1;
    }
    i
}

fn common_suffix_len<T: PartialEq>(old: &[T], or: std::ops::Range<usize>, new: &[T], nr: std::ops::Range<usize>) -> usize {
    let mut i = 0;
    while or.end > or.start + i && nr.end > nr.start + i && old[or.end - 1 - i] == new[nr.end - 1 - i] {
        i += 1;
    }
    i
}

fn push_op(ops: &mut Vec<Op>, tag: Tag, old_index: usize, old_len: usize, new_index: usize, new_len: usize) {
    ops.push(Op { tag, old_index, old_len, new_index, new_len });
}

fn find_middle_snake<T: PartialEq>(
    old: &[T],
    or: std::ops::Range<usize>,
    new: &[T],
    nr: std::ops::Range<usize>,
    vf: &mut V,
    vb: &mut V,
) -> Option<(usize, usize)> {
    let n = or.len();
    let m = nr.len();
    let delta = n as isize - m as isize;
    let odd = delta & 1 == 1;
    // reset
    for x in vf.v.iter_mut() {
        *x = 0;
    }
    for x in vb.v.iter_mut() {
        *x = 0;
    }
    let _ = vf.len();
    vf[1] = 0;
    vb[1] = 0;
    let d_max = ((n + m + 1) / 2 + 1) as isize;
    for d in 0..d_max {
        // forward
        let mut k = d;
        while k >= -d {
            let mut x = if k == -d || (k != d && vf[k - 1] < vf[k + 1]) { vf[k + 1] } else { vf[k - 1] + 1 };
            let y = (x as isize - k) as usize;
            let (x0, y0) = (x, y);
            if x < n && y < m {
                let adv = common_prefix_len(old, or.start + x..or.end, new, nr.start + y..nr.end);
                x += adv;
            }
            vf[k] = x;
            if odd && (k - delta).abs() <= (d - 1) && vf[k] + vb[-(k - delta)] >= n {
                return Some((x0 + or.start, y0 + nr.start));
            }
            k -= 2;
        }
        // backward
        let mut k = d;
        while k >= -d {
            let mut x = if k == -d || (k != d && vb[k - 1] < vb[k + 1]) { vb[k + 1] } else { vb[k - 1] + 1 };
            let mut y = (x as isize - k) as usize;
            if x < n && y < m {
                let adv = common_suffix_len(old, or.start..or.start + n - x, new, nr.start..nr.start + m - y);
                x += adv;
                y += adv;
            }
            vb[k] = x;
            if !odd && (k - delta).abs() <= d && vb[k] + vf[-(k - delta)] >= n {
                return Some((n - x + or.start, m - y + nr.start));
            }
            k -= 2;
        }
    }
    None
}

fn conquer<T: PartialEq>(
    ops: &mut Vec<Op>,
    old: &[T],
    mut or: std::ops::Range<usize>,
    new: &[T],
    mut nr: std::ops::Range<usize>,
    vf: &mut V,
    vb: &mut V,
) {
    let prefix = common_prefix_len(old, or.clone(), new, nr.clone());
    if prefix > 0 {
        push_op(ops, Tag::Equal, or.start, prefix, nr.start, prefix);
    }
    or.start += prefix;
    nr.start += prefix;
    let suffix = common_suffix_len(old, or.clone(), new, nr.clone());
    let suffix_pos = (or.end - suffix, nr.end - suffix);
    or.end -= suffix;
    nr.end -= suffix;
    if or.is_empty() && nr.is_empty() {
        // nothing
    } else if nr.is_empty() {
        push_op(ops, Tag::Delete, or.start, or.len(), nr.start, 0);
    } else if or.is_empty() {
        push_op(ops, Tag::Insert, or.start, 0, nr.start, nr.len());
    } else if let Some((xs, ys)) = find_middle_snake(old, or.clone(), new, nr.clone(), vf, vb) {
        let (oa, ob) = (or.start..xs, xs..or.end);
        let (na, nb) = (nr.start..ys, ys..nr.end);
        conquer(ops, old, oa, new, na, vf, vb);
        conquer(ops, old, ob, new, nb, vf, vb);
    } else {
        push_op(ops, Tag::Delete, or.start, or.len(), nr.start, 0);
        push_op(ops, Tag::Insert, or.start, 0, nr.start, nr.len());
    }
    if suffix > 0 {
        push_op(ops, Tag::Equal, suffix_pos.0, suffix, suffix_pos.1, suffix);
    }
}

