language: {lang}
rule:
  pattern: Your Rule Pattern here...
# utils: Extract repeated rule as local utility here.";

fn not_tty() -> SgError {
    SgError { message: "The input device is not a TTY".into(), help: String::new(), see_also: None, causes: vec![], code: 1 }
}

fn insufficient(what: &str) -> SgError {
    SgError::new(
        "Insufficient command line argument provided to use `--yes` option.",
        format!("You need to provide `{}` in command line to use non-interactive `new`.", what),
        None,
        22,
    )
}

fn file_exists(path: &Path) -> SgError {
    SgError::new(
        format!("File `{}` already exists.", path.display()),
        "The item you want to create already exists. Try editing the existing file or create a new one with a different name?",
        None,
        17,
    )
}

fn project_exists() -> SgError {
    SgError::new(
        "ast-grep project already exists.",
        "You are already inside a sub-folder of an ast-grep project. Try finding sgconfig.yml in ancestor directory?",
        Some("https://ast-grep.github.io/guide/scan-project.html"),
        17,
    )
}

fn no_test_dir() -> SgError {
    SgError::new(
        "No test file directory is configured.",
        "Fail to create a test file because the project `sgconfig.yml` does not specify any test configuration.",
        Some("https://ast-grep.github.io/guide/test-rule.html"),
        5,
    )
}

fn io_err(e: std::io::Error) -> SgError {
    SgError { message: e.to_string(), help: String::new(), see_also: None, causes: vec![], code: 1 }
}

fn abs(project: &Project, p: &Path) -> PathBuf {
    let dir = std::fs::canonicalize(&project.dir).unwrap_or_else(|_| project.dir.clone());
    if p.is_absolute() {
        p.to_path_buf()
    } else {
        dir.join(p)
    }
}

fn create_project(yes: bool) -> SgResult<i32> {
    if find_config(None).is_some() {
        return Err(project_exists());
    }
    if !yes {
        return Err(not_tty());
    }
    let cwd = std::env::current_dir().map_err(io_err)?;
    let cwd = std::fs::canonicalize(&cwd).unwrap_or(cwd);
    let rules = cwd.join("rules");
    let tests = cwd.join("rule-tests");
    let utils = cwd.join("utils");
    let config = format!("ruleDirs:\n- {}\ntestConfigs:\n- testDir: {}\nutilDirs:\n- {}\n", rules.display(), tests.display(), utils.display());
    std::fs::write(cwd.join("sgconfig.yml"), config).map_err(io_err)?;
    for d in [&rules, &tests, &utils] {
        std::fs::create_dir_all(d).map_err(io_err)?;
        std::fs::write(d.join(".gitkeep"), "").map_err(io_err)?;
    }
    println!("Your new ast-grep project has been created!");
    Ok(0)
}

fn write_new(path: &Path, content: &str) -> SgResult<()> {
    if path.exists() {
        return Err(file_exists(path));
    }
    std::fs::write(path, content).map_err(io_err)
}

fn create_test(project: &Project, id: &str) -> SgResult<()> {
    let Some(tcs) = &project.config.test_configs else { return Err(no_test_dir()) };
    let Some(tc) = tcs.first() else { return Err(no_test_dir()) };
    let dir = abs(project, &tc.test_dir);
    let path = dir.join(format!("{}-test.yml", id));
    write_new(&path, &TEST_TEMPLATE.replace("{id}", id))?;
    println!("Created test at {}", path.display());
    Ok(())
}

fn create_rule(project: &Project, id: &str, lang: Language, yes: bool) -> SgResult<()> {
    if project.config.rule_dirs.len() != 1 && !yes {
        return Err(not_tty());
    }
    if project.config.rule_dirs.len() > 1 {
        return Err(not_tty());
    }
    let Some(dir) = project.config.rule_dirs.first() else { return Err(not_tty()) };
    let dir = abs(project, dir);
    let path = dir.join(format!("{}.yml", id));
    write_new(&path, &RULE_TEMPLATE.replace("{id}", id).replace("{lang}", lang.name()))?;
    println!("Created rules at {}", path.display());
    create_test(project, id)
}

fn create_util(project: &Project, id: &str, lang: Language) -> SgResult<()> {
    let dirs = project.config.util_dirs.clone().unwrap_or_default();
    if dirs.len() > 1 {
        return Err(not_tty());
    }
    let Some(dir) = dirs.first() else {
