    write_new(&path, &UTIL_TEMPLATE.replace("{id}", id).replace("{lang}", lang.name()))?;
    println!("Created util at {}", path.display());
    Ok(())
}

pub fn new(m: &ArgMatches, config: Option<String>) -> SgResult<i32> {
    let yes = m.get_flag("yes");
    let name = m.get_one::<String>("name").cloned();
    let lang = m.get_one::<Language>("lang").copied();
    let sub = m.subcommand_name();
    if sub == Some("project") {
        if !yes {
            return Err(not_tty());
        }
        println!("Creating a new ast-grep project...");
        return create_project(yes);
    }
    let project = load_project(config.as_deref())?;
    let project = match project {
        Some(p) => p,
        None => {
            if sub.is_none() {
                if !yes {
                    return Err(not_tty());
                }
                println!("No sgconfig.yml found. Creating a new ast-grep project...");
                return create_project(yes);
