        }
        return Err(not_tty());
    };
    if !yes {
        return Err(not_tty());
    }
    match sub {
        "rule" => {
            let Some(name) = name else { return Err(insufficient("name")) };
            let Some(lang) = lang else { return Err(insufficient("lang")) };
            create_rule(&project, &name, lang, yes)?;
        }
