fn walk_yaml(dir: &Path) -> Result<Vec<PathBuf>, String> {
    let mut out = Vec::new();
    let walker = ignore::WalkBuilder::new(dir).hidden(false).git_ignore(false).require_git(false).sort_by_file_name(|a, b| a.cmp(b)).build();
    for e in walker {
        match e {
            Ok(e) => {
                let p = e.path();
                if p.is_file() {
                    if let Some(ext) = p.extension().and_then(|e| e.to_str()) {
                        if ext == "yml" || ext == "yaml" {
                            out.push(p.to_path_buf());
                        }
                    }
                }
            }
            Err(err) => return Err(format!("{}", err)),
        }
    }
    Ok(out)
}

fn make_snapshot(rule: &RuleConfig, code: &str) -> Option<TestSnapshot> {
    let tree = crate::parsers::parse(rule.language, code);
    let root = tree.root();
    let matches = rule.find_all(root);
    let m = matches.first()?;
    let fixed = rule.fix_edit(m.node, &m.env).map(|e| {
        let mut s = String::new();
        s.push_str(&code[..e.start]);
        s.push_str(&e.inserted);
        s.push_str(&code[e.end..]);
        s
    });
    let mut labels = vec![LabelSnapshot { source: m.node.text().to_string(), style: "primary".into(), start: m.node.start(), end: m.node.end() }];
    if let Some(lc) = &rule.labels {
        labels.clear();
        let mut names: Vec<&String> = lc.keys().collect();
        names.sort();
        for name in names {
            if let Some(n) = m.env.get_single(name) {
                labels.push(LabelSnapshot {
                    source: n.text().to_string(),
                    style: if lc[name].style == LabelStyle::Primary { "primary".into() } else { "secondary".into() },
                    start: n.start(),
                    end: n.end(),
                });
            }
        }
    }
    Some(TestSnapshot { fixed, labels })
}

