        test_dirs.push((dir, snap));
    } else if let Some(tcs) = &project.config.test_configs {
        for tc in tcs {
            let dir = project.dir.join(&tc.test_dir);
            let snap = match (&snapshot_dir_name, &tc.snapshot_dir) {
                (Some(s), _) => dir.join(s),
                (None, Some(s)) => dir.join(s),
                (None, None) => dir.join("__snapshots__"),
            };
            test_dirs.push((dir, snap));
        }
    }
    // collect test cases
    let mut cases: Vec<(TestCase, PathBuf)> = Vec::new();
    for (dir, snap) in &test_dirs {
        let files = walk_yaml(dir).map_err(|e| {
            SgError::new("Cannot read test cases", "Please check the test directory configured in sgconfig.yml", Some("https://ast-grep.github.io/guide/test-rule.html"), 6).cause(e)
        })?;
        for f in files {
            if f.starts_with(snap) {
                continue;
            }
            let Ok(text) = std::fs::read_to_string(&f) else { continue };
            let Ok(tc) = serde_yaml::from_str::<TestCase>(&text) else { continue };
            if let Some(re) = &filter {
                if !re.is_match(&tc.id) {
                    continue;
                }
            }
            cases.push((tc, snap.clone()));
        }
    }
    let mut out = String::new();
    let _ = writeln!(out, "Running {} tests", cases.len());
    let mut details = String::new();
    let mut summary = String::new();
    let mut passed = 0;
    let mut failed = 0;
    let mut any_noisy_missing = false;
    let mut any_wrong = false;
    for (tc, snap_dir) in &cases {
        let Some(rule) = rules.iter().find(|r| r.id == tc.id) else {
            let _ = writeln!(out, "Configuration not found! {}", tc.id);
            continue;
        };
        if rule.severity == crate::rule::Severity::Off && !include_off {
            continue;
        }
        let snap_path = snap_dir.join(format!("{}-snapshot.yml", tc.id));
        let mut snap_file: SnapshotFile = std::fs::read_to_string(&snap_path).ok().and_then(|t| serde_yaml::from_str(&t).ok()).unwrap_or_default();
        snap_file.id = tc.id.clone();
        let mut statuses: Vec<CaseStatus> = Vec::new();
        let mut changed = false;
        for code in &tc.valid {
            let tree = crate::parsers::parse(rule.language, code);
            let ms = rule.find_all(tree.root());
            if ms.is_empty() {
                statuses.push(CaseStatus::Pass);
            } else {
                statuses.push(CaseStatus::Noisy);
                let _ = write!(details, "[{}] Expect {} to report no issue, but some issues found in:\n\n{}\n\n", styles.underline("Noisy"), styles.bold(&tc.id), indent_code(code));
            }
        }
        for code in &tc.invalid {
            let Some(actual) = make_snapshot(rule, code) else {
                statuses.push(CaseStatus::Missing);
                let _ = write!(details, "[{}] Expect rule {} to report issues, but none found in:\n\n{}\n\n", styles.underline("Missing"), styles.bold(&tc.id), indent_code(code));
                continue;
            };
            if skip_snapshot {
                statuses.push(CaseStatus::Pass);
                continue;
            }
            match snap_file.snapshots.get(code) {
                Some(expected) if *expected == actual => statuses.push(CaseStatus::Pass),
                Some(expected) => {
                    if update_all {
                        snap_file.snapshots.insert(code.clone(), actual);
                        changed = true;
                        statuses.push(CaseStatus::Updated);
                        let _ = write!(details, "[{}] Rule {}'s snapshot baseline has been updated.\n\n{}\n\n", styles.underline("Updated"), styles.bold(&tc.id), indent_code(code));
                    } else {
                        statuses.push(CaseStatus::Wrong);
                        let _ = writeln!(details, "[{}] {} snapshot is different from baseline.", styles.underline("Wrong"), styles.bold(&tc.id));
                        let _ = writeln!(details, "{}", styles.italic("Diff:"));
                        let old = serde_yaml::to_string(expected).unwrap_or_default();
                        let new = serde_yaml::to_string(&actual).unwrap_or_default();
                        printer.print_unified(&mut details, &old, &new);
                        let _ = write!(details, "{}\n{}\n\n", styles.italic("For Code:"), indent_code(code));
                    }
                }
                None => {
                    if update_all {
                        snap_file.snapshots.insert(code.clone(), actual);
                        changed = true;
                        statuses.push(CaseStatus::Updated);
                        let _ = write!(details, "[{}] Rule {}'s snapshot baseline has been updated.\n\n{}\n\n", styles.underline("Updated"), styles.bold(&tc.id), indent_code(code));
                    } else {
                        statuses.push(CaseStatus::Wrong);
                        let _ = writeln!(details, "[{}] No {} baseline found.", styles.underline("Wrong"), styles.bold(&tc.id));
                        let _ = writeln!(details, "{}", styles.italic("Generated Snapshot:"));
                        let yaml = serde_yaml::to_string(&actual).unwrap_or_default();
                        for l in yaml.trim_end().lines() {
                            let _ = writeln!(details, "  {}", l);
                        }
                        let _ = write!(details, "{}\n{}\n\n", styles.italic("For Code:"), indent_code(code));
                    }
                }
            }
        }
        if changed {
            if let Some(parent) = snap_path.parent() {
                let _ = std::fs::create_dir_all(parent);
            }
            if let Ok(text) = serde_yaml::to_string(&snap_file) {
                let _ = std::fs::write(&snap_path, text);
            }
        }
        let case_passed = statuses.iter().all(|s| matches!(s, CaseStatus::Pass | CaseStatus::Updated));
        if statuses.iter().any(|s| matches!(s, CaseStatus::Noisy | CaseStatus::Missing)) {
            any_noisy_missing = true;
        }
        if statuses.iter().any(|s| matches!(s, CaseStatus::Wrong)) {
            any_wrong = true;
        }
        let chars: String = statuses
            .iter()
            .map(|s| match s {
                CaseStatus::Pass => '.',
                CaseStatus::Noisy => 'N',
                CaseStatus::Missing => 'M',
                CaseStatus::Wrong => 'W',
                CaseStatus::Updated => 'U',
            })
            .collect();
        let tag = if case_passed {
            passed += 1;
            if color {
                "\x1b[1;42;37mPASS\x1b[0m".to_string()
            } else {
                "PASS".to_string()
            }
        } else {
            failed += 1;
            if color {
                "\x1b[1;41;37mFAIL\x1b[0m".to_string()
            } else {
                "FAIL".to_string()
            }
        };
        let _ = writeln!(summary, "{} {}  {}", tag, tc.id, chars);
    }
    out.push('\n');
    out.push_str("----------- Case Details -----------\n");
    out.push_str(&details);
    out.push_str(&summary);
    out.push('\n');
    if failed == 0 {
        let _ = writeln!(out, "test result: ok. {} passed; {} failed;", passed, failed);
        print!("{}", out);
        return Ok(0);
    }
    print!("{}", out);
    use std::io::Write;
    let _ = std::io::stdout().flush();
    let (help, link) = if any_noisy_missing {
        ("You can use ast-grep playground to debug your rules and test cases.", "https://ast-grep.github.io/playground.html")
    } else if any_wrong {
        ("Test failed due to mismatching snapshots. Run with `--update-all` to update all snapshots, or `--interactive` to update selectively.", "https://ast-grep.github.io/guide/test-rule.html")
    } else {
        ("You can use ast-grep playground to debug your rules and test cases.", "https://ast-grep.github.io/playground.html")
    };
    Err(SgError::new(format!("test failed. {} passed; {} failed;", passed, failed), help, Some(link), 4))
}
