//! Generic fallback parser: tokenizes source and builds a bracket-nested tree with
//! light heuristics (member chains, calls, statements). Node kinds are approximate.
use super::lexer::*;
use crate::lang::Language;
use crate::tree::{NodeId, Tree, TreeBuilder};
use std::rc::Rc;

fn static_tok(s: &str) -> &'static str {
    super::js::static_str(s)
}

#[derive(Clone, Copy, PartialEq)]
enum Kind {
    Ident,
    Number,
    Str,
    Comment,
    Punct,
}

struct Tok {
    kind: Kind,
    start: usize,
    end: usize,
    nl_before: bool,
}

struct Lexer<'s> {
    src: &'s str,
    lang: Language,
}

impl<'s> Lexer<'s> {
    fn line_comment_prefix(&self) -> &'static [&'static str] {
        use Language::*;
        match self.lang {
            Bash | Python | Ruby | Yaml | Nix | Elixir | Hcl => &["#"],
            Lua | Haskell => &["--"],
            Html | Css | Json => &[],
            Php => &["//", "#"],
            _ => &["//"],
        }
    }
    fn block_comment(&self) -> Option<(&'static str, &'static str)> {
        use Language::*;
        match self.lang {
            Bash | Python | Ruby | Yaml | Elixir => None,
            Lua => Some(("--[[", "]]")),
            Haskell => Some(("{-", "-}")),
            Html => Some(("<!--", "-->")),
            _ => Some(("/*", "*/")),
        }
    }
    fn tokens(&self) -> Vec<Tok> {
        let src = self.src;
        let bytes = src.as_bytes();
        let mut out = Vec::new();
        let mut i = 0;
        let mut nl = false;
        while i < bytes.len() {
            let p = skip_ws(src, i);
            if p != i {
                if src[i..p].contains('\n') {
                    nl = true;
                }
                i = p;
                continue;
            }
            let rest = &src[i..];
            let mut matched = false;
            for pre in self.line_comment_prefix() {
                if rest.starts_with(pre) {
                    let end = rest.find('\n').map(|x| i + x).unwrap_or(bytes.len());
                    out.push(Tok { kind: Kind::Comment, start: i, end, nl_before: nl });
                    i = end;
                    matched = true;
                    break;
                }
            }
            if matched {
                continue;
            }
            if let Some((open, close)) = self.block_comment() {
                if rest.starts_with(open) {
                    let end = rest[open.len()..].find(close).map(|x| i + open.len() + x + close.len()).unwrap_or(bytes.len());
                    out.push(Tok { kind: Kind::Comment, start: i, end, nl_before: nl });
                    i = end;
                    continue;
                }
            }
            let c = rest.chars().next().unwrap();
            if is_ident_start(c) || (c == '@' && self.lang == Language::Css) || (c == '#' && self.lang == Language::Css) {
                let mut e = ident_end(src, i);
                if e == i {
                    e = i + c.len_utf8();
                    e = ident_end(src, e).max(e);
                }
                // Rust macros: foo! ; Ruby/Elixir ? and ! suffixes
                if e < bytes.len() && bytes[e] == b'!' && matches!(self.lang, Language::Rust) && e + 1 < bytes.len() && bytes[e + 1] != b'=' {
                    e += 1;
                }
                out.push(Tok { kind: Kind::Ident, start: i, end: e, nl_before: nl });
                i = e;
                nl = false;
                continue;
            }
            if c.is_ascii_digit() {
                let e = scan_number(src, i);
                out.push(Tok { kind: Kind::Number, start: i, end: e, nl_before: nl });
                i = e;
                nl = false;
                continue;
            }
            if c == '"' || c == '\'' || c == '`' {
                // raw-ish string scan; for languages where ' is a char literal or lifetime (Rust), handle simply
                let e = skip_string(src, i, c as u8, true);
                out.push(Tok { kind: Kind::Str, start: i, end: e, nl_before: nl });
                i = e;
                nl = false;
                continue;
            }
            const OPS: &[&str] = &[
                ">>>=", "...", "===", "!==", "**=", "<<=", ">>=", "&&=", "||=", "??=", "::", "->", "=>", "==", "!=", "<=", ">=", "&&",
                "||", "??", "?.", "++", "--", "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", "<<", ">>", "**", ":=", "<-", "..", "|>",
            ];
            let mut len = c.len_utf8();
            for op in OPS {
                if rest.starts_with(op) {
                    len = op.len();
                    break;
                }
            }
            out.push(Tok { kind: Kind::Punct, start: i, end: i + len, nl_before: nl });
            i += len;
            nl = false;
        }
        out
    }
}

struct Builder<'s> {
    src: &'s str,
    toks: Vec<Tok>,
    pos: usize,
    b: TreeBuilder,
    extras: Vec<NodeId>,
}

fn closer_of(open: &str) -> &'static str {
    match open {
        "(" => ")",
        "[" => "]",
        _ => "}",
    }
}

impl<'s> Builder<'s> {
    fn text(&self, i: usize) -> &'s str {
        &self.src[self.toks[i].start..self.toks[i].end]
    }

    /// Parse items until the given closer (or EOF). Returns items (grouped).
    fn parse_items(&mut self, closer: Option<&'static str>, split_statements: bool) -> Vec<NodeId> {
        let mut items: Vec<(NodeId, bool)> = Vec::new(); // (node, nl_before)
        while self.pos < self.toks.len() {
            let t = &self.toks[self.pos];
            let text = &self.src[t.start..t.end];
            let nl = t.nl_before;
            match t.kind {
                Kind::Comment => {
                    let c = self.b.leaf("comment", true, t.start, t.end);
                    self.extras.push(c);
                    self.pos += 1;
                }
                Kind::Ident => {
                    let n = self.b.leaf("identifier", true, t.start, t.end);
                    self.pos += 1;
                    items.push((n, nl));
                }
                Kind::Number => {
                    let n = self.b.leaf("number", true, t.start, t.end);
                    self.pos += 1;
                    items.push((n, nl));
                }
                Kind::Str => {
                    let n = self.b.leaf("string", true, t.start, t.end);
                    self.pos += 1;
                    items.push((n, nl));
                }
                Kind::Punct => {
                    if let Some(cl) = closer {
                        if text == cl {
                            break;
                        }
                    }
                    match text {
                        "(" | "[" | "{" => {
                            let open_kind = static_tok(text);
                            let (s, e) = (t.start, t.end);
                            let open = self.b.token(open_kind, s, e);
                            self.pos += 1;
                            let cl = closer_of(text);
                            let inner = self.parse_items(Some(cl), text == "{");
                            let mut ch = vec![open];
                            ch.extend(inner);
                            if self.pos < self.toks.len() && self.text(self.pos) == cl {
                                let ct = &self.toks[self.pos];
                                let close = self.b.token(cl, ct.start, ct.end);
                                ch.push(close);
                                self.pos += 1;
                            } else {
                                let m = self.b.missing(cl, self.toks.get(self.pos).map(|t| t.start).unwrap_or(self.src.len()));
                                ch.push(m);
                            }
                            let kind = match text {
                                "(" => "parenthesized",
                                "[" => "bracketed",
                                _ => "block",
                            };
                            let n = self.b.node(kind, ch);
                            items.push((n, nl));
                        }
                        ")" | "]" | "}" => {
                            // stray closer
                            let k = static_tok(text);
                            let tk = self.b.token(k, t.start, t.end);
                            let err = self.b.node("ERROR", vec![tk]);
                            self.pos += 1;
                            items.push((err, nl));
                        }
                        _ => {
                            let k = static_tok(text);
                            let n = self.b.token(k, t.start, t.end);
                            self.pos += 1;
                            items.push((n, nl));
                        }
                    }
                }
            }
        }
        let grouped = self.group(items);
        if split_statements {
            self.split_statements(grouped)
        } else {
            grouped.into_iter().map(|(n, _)| n).collect()
        }
    }

    /// Group member chains and calls.
    fn group(&mut self, items: Vec<(NodeId, bool)>) -> Vec<(NodeId, bool)> {
        let mut out: Vec<(NodeId, bool)> = Vec::new();
        let mut i = 0;
        while i < items.len() {
            let (mut cur, nl) = items[i];
            i += 1;
            loop {
                if i >= items.len() {
                    break;
                }
                let (next, next_nl) = items[i];
                let nk = self.b.kind(next);
                let ck = self.b.kind(cur);
                let cur_is_value = matches!(ck, "identifier" | "member" | "call" | "index" | "parenthesized" | "string" | "number" | "bracketed");
                if !cur_is_value {
                    break;
                }
                if matches!(nk, "." | "::" | "->" | "?.") && i + 1 < items.len() && self.b.kind(items[i + 1].0) == "identifier" && !next_nl {
                    let obj = self.b.set_field(cur, "object");
                    let prop = self.b.set_field(items[i + 1].0, "property");
                    cur = self.b.node("member", vec![obj, next, prop]);
                    i += 2;
                    continue;
                }
                if nk == "parenthesized" && !next_nl && matches!(ck, "identifier" | "member" | "call" | "index") {
                    let f = self.b.set_field(cur, "function");
                    self.b.set_kind(next, "arguments");
                    let a = self.b.set_field(next, "arguments");
                    cur = self.b.node("call", vec![f, a]);
                    i += 1;
                    continue;
                }
                if nk == "bracketed" && !next_nl && matches!(ck, "identifier" | "member" | "call" | "index") {
                    let o = self.b.set_field(cur, "object");
                    cur = self.b.node("index", vec![o, next]);
                    i += 1;
                    continue;
                }
                break;
            }
            out.push((cur, nl));
        }
        out
    }

    fn split_statements(&mut self, items: Vec<(NodeId, bool)>) -> Vec<NodeId> {
        let mut out = Vec::new();
        let mut cur: Vec<NodeId> = Vec::new();
        let flush = |b: &mut TreeBuilder, cur: &mut Vec<NodeId>, out: &mut Vec<NodeId>| {
            if cur.is_empty() {
                return;
            }
            if cur.len() == 1 {
                out.push(cur[0]);
            } else {
                let n = b.node("statement", std::mem::take(cur));
                out.push(n);
            }
            cur.clear();
        };
        let continues = |k: &str| {
            matches!(k, "," | "+" | "-" | "*" | "/" | "=" | "==" | "!=" | "&&" | "||" | "." | "::" | "->" | "?" | ":" | "<" | ">" | "<=" | ">=" | "+=" | "-=" | "=>" | "|" | "&" | "||" | "<-" | "|>" | "=>" | "else" | "catch" | "finally" | "elif" | "elsif")
        };
        for (n, nl) in items {
            let k = self.b.kind(n);
            if k == ";" {
                cur.push(n);
                flush(&mut self.b, &mut cur, &mut out);
                continue;
            }
            if nl && !cur.is_empty() {
                let last_k = self.b.kind(*cur.last().unwrap());
                if !continues(last_k) && !continues(k) {
                    flush(&mut self.b, &mut cur, &mut out);
                }
            }
            cur.push(n);
        }
        flush(&mut self.b, &mut cur, &mut out);
        out
    }
}

pub fn parse(src: Rc<str>, lang: Language) -> Tree {
    let lexer = Lexer { src: &src, lang };
    let toks = lexer.tokens();
    let mut bld = Builder { src: &src, toks, pos: 0, b: TreeBuilder::new(), extras: Vec::new() };
    let mut items = Vec::new();
    while bld.pos < bld.toks.len() {
        let before = bld.pos;
        let more = bld.parse_items(None, true);
        items.extend(more);
        if bld.pos == before {
            bld.pos += 1;
        }
    }
    let start = items.iter().map(|&c| bld.b.start(c)).min().unwrap_or(0);
    let root = bld.b.node_with_range("source_file", items, start, src.len());
    let extras = std::mem::take(&mut bld.extras);
    crate::tree::insert_extras(&mut bld.b, root, extras);
    bld.b.finish(src, lang, root)
}
